double MeanUpdateArrivalTime[] = {5, 10, 20, 100, 200};

// Define cache structure
typedef struct {
  int data_item; // data item id
  int valid; // valid flag (1 = valid, 0 = invalid)
  unsigned long last_used; // for LRU replacement policy
} CacheEntry;

// Global variables
CacheEntry cache[NUM_CLIENTS][CACHE_SIZE]; // caches for each node
int database[DB_SIZE]; // the database with the data items
unsigned long current_time; // current time in the simulation

