        // Send data message to client
        data_message* data = malloc(sizeof(data_message));
        data->item_id = item_id;
        sprintf(data->data, "Data of item %d", item_id);
        printf("[Time %d] Server sends data of item %d to client %d\n", simtime(), item_id, client_id);
