        sendto(data, client_id);
    } else {
        // Send confirm message to client
        confirm_message* confirm = malloc(sizeof(confirm_message));
        confirm->item_id = item_id;
        confirm->client_id = client_id;
        printf("[Time %d] Server sends confirm of item %d to client %d\n", simtime(), item_id, client_id);
        hold(0); // no transmission time
        sendto(confirm, client_id);
    }
}

