// Define functions for cache management
int find_item_in_cache(int* cache, int size, int item_id) {
    for (int i = 0; i < size; i++) {
        if (cache[i] == item_id) {
            return i;
        }
    }
    return -1;
}

void replace_lru_item_in_cache(int* cache, int size, int item_id) {
    int lru_time = simtime();
    int lru_index = 0;
    for (int i = 0; i < size; i++) {
        int item = cache[i];
        int item_time = gettag(item);
        if (item_time < lru_time) {
            lru_time = item_time;
            lru_index = i;
        }
    }
    printf("[Time %d] Remove item %d from cache\n", lru_time, cache[lru_index]);
    cache[lru_index] = item_id;
    settag(item_id, simtime());
}

// Define functions for client behavior
void query(int client_id) {
    int item_id = random(DB_SIZE);
    printf("[Time %d] Client %d queries item %d\n", simtime(), client_id, item_id);
    int cache_index = find_item_in_cache(getcache(client_id), CACHE_SIZE, item_id);
    if (cache_index >= 0) {
        // Send check message to server
        check_message* check = malloc(sizeof(check_message));
        check->item_id = item_id;
        check->client_id = client_id;
        printf("[Time %d] Client %d sends check of item %d to server\n", simtime(), client_id, item_id);
        hold(0); // no transmission time
        sendto(check, NUM_CLIENTS);
    } else {
        // Send request message to server
        request_message* req = malloc(sizeof(request_message));
        req->item_id = item_id;
        req->client_id = client_id;
        printf("[Time %d] Client %d sends request of item %d to server\n", simtime(), client_id, item_id);
        hold(0); // no transmission time
        sendto(req, NUM_CLIENTS);
    }
}

void handle_hot_update() {
    int item_id = hot_items[random(HOT_ITEMS)];
    printf("[Time %d] Server updates hot item %d\n", simtime(), item_id);
    sprintf("New data of item %d", item_id);
    for (int i = 0; i < NUM_CLIENTS; i++) {
        int cache_index = find_item_in_cache(getcache(i), CACHE_SIZE, item_id);
        if (cache_index >= 0) {
            // Send invalidate message to client
            invalidate(i, getcache(i)[cache_index]);
            handle_invalidate(item_id, i);
        }
    }
}

void handle_cold_update() {
    int item_id = cold_items[random(DB_SIZE - HOT_ITEMS)] + HOT_ITEMS;
    printf("[Time %d] Server updates cold item %d\n", simtime(), item_id);
    sprintf("New data of item %d", item_id);
    for (int i = 0; i < NUM_CLIENTS; i++) {
        // Send confirm message to client
        confirm_message* confirm = malloc(sizeof(confirm_message));
        confirm->item_id = item_id;
        confirm->client_id = i;
        printf("[Time %d] Server sends confirm of item %d to client %d\n", simtime(), item_id, i);
        hold(0); // no transmission time
        sendto(confirm, i);
    }
}

void initialize() {
    printf("Initializing...\n");
    // Initialize hot and cold items
    for (int i = 0; i < HOT_ITEMS; i++) {
        hot_items[i] = i;
    }
    for (int i = 0; i < DB_SIZE - HOT_ITEMS; i++) {
        cold_items[i] = i + HOT_ITEMS;
    }
    // Initialize clients
    for (int i = 0; i < NUM_CLIENTS; i++) {
        setcache(i, (int*) malloc(CACHE_SIZE * sizeof(int)));
        setcachesize(i, CACHE_SIZE);
    }
}

int main() {
    printf("Starting simulation...\n");
    init_simlib();
    initialize();
    // Schedule hot and cold updates periodically
    while (server_last_update_time < 3600) { // simulate 1 hour
        double update_interval;
        if (random(1.0) < UPDATE_PROBABILITY) {
            // Hot update
            update_interval = expon(1.0 / 10); // T_update = 10 seconds
            schedule(handle_hot_update, update_interval);
        } else {
            // Cold update
            update_interval = expon(1.0 / 100); // T_update = 100 seconds
            schedule(handle_cold_update, update_interval);
        }
        server_last_update_time += update_interval;
    }
    // Schedule queries periodically
    double query_time = 0;
    for (int i = 0; i < NUM_CLIENTS; i++) {
        query(i);
    }
    while (query_time < 3600) { // simulate 1 hour
        hold(expon(1.0 / 5)); // T_query = 5 seconds
        query_time += simtime() - query_time;
        for (int i = 0; i < NUM_CLIENTS; i++) {
            query(i);
        }
    }
    // Calculate cache hit ratio and query delay
    int num_queries = NUM_CLIENTS * (3600 / 5);
    int num_hits = cachehits();
    double hit_ratio = num_hits / (double) num_queries;
    double query_delay = mean(1) * 5;
    printf("Cache hit ratio: %f\n", hit_ratio);
    printf("Query delay: %f seconds\n", query_delay);
    return 0;
}
