        }
    }

    // Clean up
    table_rm(query_delay);
    table_rm(cache_hit_ratio);
    facility_rm(server);
    cleanup();
    free(nodes);

    return 0;
}

void client() {
    node *n = nodes+process_id();
    while (clock < 10e4) {
        hold(expntl(n->q_gen_time));

        double prob = mrand48();

        // Hot data item or cold data item
        int data_item;
        if (prob < hot_access_prob) {
            data_item = mrand48() % NUM_HOT_ITEMS + 1;
        } else {
            data_item = NUM_HOT_ITEMS + (mrand48() % (DB_SIZE - NUM_HOT_ITEMS));
        }

        generate_query(n);
    }
}

void generate_query(node *n) {
    wait(server);
    double q_start_time = clock;
    hold(DATA_ITEM_SIZE * 8 / BANDWIDTH);

    double prob = mrand48();

    // Query can be answered using the local cache
    if (prob < (CACHE_SIZE / (double)DB_SIZE)) {
        cache_hits++;
        signal(server);

        // Send a check message to the server
        wait(server);
        hold(DATA_ITEM_SIZE * 8 / BANDWIDTH);

        // Receive confirm message from the server
        signal(server);

    } else {
        // Request data item from the server
        signal(server);
        query_result(n);
    }

    // Calculate query delay
    double q_delay = clock - q_start_time;
    record(q_delay, query_delay);

    total_queries++;
}

void query_result(node *n) {
    hold(expntl(n->u_arr_time));

    // Probability of hot data item update
    double prob = mrand48();

    if (prob < hot_update_prob) {
        wait(server);
        hold(DATA_ITEM_SIZE * 8 / BANDWIDTH);

        // Update hot data item
        signal(server);
    }
}

void handle_csim_error_message(long err) {
    if (err != 0) {
        printf("Error: %s\n", csim_error_message[err]);
        exit(1);
    }
}
```

