    fs::path p(file_path);
    fs::path dir = p.parent_path();
    fs::path file = p.filename();
    long long dir_id = get_directory_id(dir.string());

    if (dir_id == -1) {
        throw std::runtime_error("Directory not found: " + dir_path);
    }

    sqlite3_stmt *stmt = prepare_statement("SELECT size FROM files WHERE directory_id = ? AND name = ?;");
    sqlite3_bind_int64(stmt, 1, dir_id);
    sqlite3_bind_text(stmt, 2, file.string().c_str(), -1, 0);

    long long size = -1;
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        size = sqlite3_column_int64(stmt, 0);
    }

    finalize_statement(stmt);
    return size;
}

long long DirectoryMetadata::get_directory_size(const std::string &dir_path) {
    if (!fs::is_directory(dir_path)) {
        throw std::runtime_error("Not a directory: " + dir_path);
    }

    long long dir_id = get_directory_id(dir_path);

    if (dir_id == -1) {
        throw std::runtime_error("Directory not found: " + dir.string());
    }

    sqlite3_stmt *stmt = prepare_statement("SELECT SUM(size) FROM files WHERE directory_id = ?;");
    sqlite3_bind_int64(stmt, 1, dir_id);

    long long size = -1;
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        size = sqlite3_column_int64(stmt, 0);
    }

    finalize_statement(stmt);
    return size;
}
```

