#include <oboe/Oboe.h>
#include <jni.h>
#include <android/asset_manager_jni.h>
#include <cstring>
#include <math.h>

using namespace oboe;

class AudioEngine : public AudioStreamCallback {
public:
    AudioEngine(JNIEnv *env, jobject assetManager, int sampleRate, int channels, int format) {
        // open assets
        mAssetManager = AAssetManager_fromJava(env, assetManager);

        // set variables
        mSampleRate = sampleRate;
        mChannelCount = channels;
        mFormat = format;

        // set buffer size and frame count
        mBufferSizeInFrames = getBufferCapacityInFrames();
        mBuffer = new float[mBufferSizeInFrames * mChannelCount];

        // create stream
        AudioStreamBuilder builder;
        builder.setCallback(this);
        builder.setDeviceId(0); // default device
        builder.setDirection(Direction::Input);
        builder.setFormat(AudioFormat::Float);
        builder.setChannelCount(mChannelCount);
        builder.setSampleRate(mSampleRate);
        builder.setSharingMode(SharingMode::Exclusive);
        builder.setContentType(ContentType::Music);
        builder.setPerformanceMode(PerformanceMode::LowLatency);

        AudioStream *stream = nullptr;
        Result result = builder.openStream(&stream);
        if (result != Result::OK || stream == nullptr) {
            parseError(result);
            return;
        }

        // set stream parameters
        stream->setBufferSizeInFrames(mBufferSizeInFrames);
        stream->setFramesPerCallback(mBufferSizeInFrames);

        // start stream
        result = stream->requestStart();
        if (result != Result::OK) {
            parseError(result);
            return;
        }
    }

    ~AudioEngine() {
        // stop and close stream
        if (mStream != nullptr) {
            mStream->requestStop();
            mStream->close();
            delete mStream;
            mStream = nullptr;
        }

        // free buffer
        if (mBuffer != nullptr) {
            delete[] mBuffer;
            mBuffer = nullptr;
        }
    }

    void setRecordCallback(jobject callback) {
        mRecordCallback = callback;
    }

    void setPlaybackCallback(jobject callback) {
        mPlaybackCallback = callback;
    }

    float *getBuffer() {
        return mBuffer;
    }

    int getBufferSizeInFrames() {
        return mBufferSizeInFrames;
    }

    int getChannelCount() {
        return mChannelCount;
    }

    int getSampleRate() {
        return mSampleRate;
    }

    int getBytesPerFrame() {
        return mChannelCount * mFormat / 8;
    }

    static int getBufferCapacityInFrames() {
        return kBufferCapacitySeconds * kSampleRate;
    }

    DataCallbackResult onAudioReady(AudioStream *audioStream,
                                    void *audioData,
                                    int32_t numFrames) override {
        if (mStream == nullptr || audioStream != mStream) {
            return DataCallbackResult::Stop;
        }

        // call recording callback
        if (audioStream->getDirection() == Direction::Input && mRecordCallback != nullptr) {
            JNIEnv *env;
            int isAttached = getJNIEnv(&env);
            if (isAttached == JNI_OK) {
                jbyteArray buffer = env->NewByteArray(numFrames * getBytesPerFrame());
                float *data = static_cast<float *>(audioData);
                int byteCount = numFrames * getBytesPerFrame();
                memcpy(buffer, data, byteCount);
                env->CallVoidMethod(mRecordCallback, mRecordMethod, buffer);
                env->DeleteLocalRef(buffer);
                releaseJNIEnv();
            }
        }

        // call playback callback
        if (audioStream->getDirection() == Direction::Output && mPlaybackCallback != nullptr) {
            JNIEnv *env;
            int isAttached = getJNIEnv(&env);
            if (isAttached == JNI_OK) {
                jbyteArray buffer = env->NewByteArray(numFrames * getBytesPerFrame());
                float *data = static_cast<float *>(audioData);
                int byteCount = numFrames * getBytesPerFrame();
                memcpy(buffer, data, byteCount);
                env->CallVoidMethod(mPlaybackCallback, mPlaybackMethod, buffer);
                env->DeleteLocalRef(buffer);
                releaseJNIEnv();
            }
        }

        return DataCallbackResult::Continue;
    }

private:
    const static int kBufferCapacitySeconds = 5;
    const static int kSampleRate = 44100;

    JavaVM *mJavaVM = nullptr;
    AAssetManager *mAssetManager = nullptr;
    AudioStream *mStream = nullptr;
    int mSampleRate = 0;
    int mBufferSizeInFrames = 0;
    int mChannelCount = 0;
    int mFormat = 0;
    float *mBuffer = nullptr;

    jobject mRecordCallback = nullptr;
    jmethodID mRecordMethod = nullptr;

    jobject mPlaybackCallback = nullptr;
    jmethodID mPlaybackMethod = nullptr;

    jint getJNIEnv(JNIEnv **env) {
        jint result = mJavaVM->AttachCurrentThread(env, nullptr);
        if (result != JNI_OK) {
            return result;
        }

        return JNI_OK;
    }

    void releaseJNIEnv() {
        mJavaVM->DetachCurrentThread();
    }

    void parseError(Result error) {
        switch (error) {
            case Result::ErrorUnknown:
                break;
            case Result::ErrorInvalidArgument:
                break;
            case Result::ErrorInvalidState:
                break;
            case Result::ErrorUnsupported:
                break;
            case Result::ErrorUnavailable:
                break;
            case Result::ErrorTimeout:
                break;
            case Result::ErrorIllegalArgument:
                break;
            case Result::ErrorInternal:
                break;
            case Result::ErrorOutOfMemory:
                break;
            case Result::ErrorDeviceUnavailable:
                break;
            case Result::ErrorInexact:
                break;
            case Result::ErrorDisconnected:
                break;
            case Result::ErrorResourceBusy:
                break;
            default:
                break;
        }
    }
};

