class DuplexStreamCallback : public AudioStreamCallback {
public:
    DuplexStreamCallback(float *buffer, int bufferSize, int sampleRate, int channelCount)
        : mBuffer(buffer), mBufferSize(bufferSize), mSampleRate(sampleRate), mChannelCount(channelCount) {}

    DataCallbackResult onAudioReady(AudioStream *audioStream, void *audioData, int32_t numFrames) override {
        if (audioStream == mInputStream) {
            // read audio data from input buffer
            int byteCount = numFrames * mChannelCount * sizeof(float);
            memcpy(mBuffer, audioData, byteCount);
        } else if (audioStream == mOutputStream) {
            // write audio data to output buffer
            int byteCount = numFrames * mChannelCount * sizeof(float);
            memcpy(audioData, mBuffer, byteCount);
        }

        return DataCallbackResult::Continue;
    }

    void onErrorAfterClose(AudioStream *audioStream, Result error) override {}

private:
    float *mBuffer;
    int mBufferSize;
    int mSampleRate;
    int mChannelCount;
};
```

接着，我们创建一个名为DuplexStream的类，用于初始化DuplexStream和开始/停止录制和播放。

```cpp
class DuplexStream {
public:
    DuplexStream(int sampleRate, int channelCount, int format)
        : mSampleRate(sampleRate), mChannelCount(channelCount), mFormat(format) {}

    bool start() {
        AudioStreamBuilder builder;
        builder.setSampleRate(mSampleRate);
        builder.setChannelCount(mChannelCount);
        builder.setFormat(static_cast<AudioFormat>(mFormat));
        builder.setSharingMode(SharingMode::Exclusive);
        builder.setPerformanceMode(PerformanceMode::LowLatency);
        builder.setCallback(nullptr);

        Result result = builder.openStream(&mInputStream);
        if (result != Result::OK) {
            return false;
        }

        builder.setDirection(Direction::Output);

        result = builder.openStream(&mOutputStream, mInputStream);
        if (result != Result::OK) {
            return false;
        }

        mBufferSize = mInputStream->getFramesPerBurst() * mChannelCount;
        mBuffer = new float[mBufferSize];

        mInputCallback = std::make_unique<DuplexStreamCallback>(mBuffer, mBufferSize, mSampleRate, mChannelCount);
        mOutputCallback = std::make_unique<DuplexStreamCallback>(mBuffer, mBufferSize, mSampleRate, mChannelCount);

        mInputStream->setCallback(mInputCallback.get());
        mOutputStream->setCallback(mOutputCallback.get());

        mInputStream->requestStart();
        mOutputStream->requestStart();

        return true;
    }

    void stop() {
        if (mInputStream != nullptr) {
            mInputStream->requestStop();
            mInputStream->close();
            mInputStream = nullptr;
        }

        if (mOutputStream != nullptr) {
            mOutputStream->requestStop();
            mOutputStream->close();
            mOutputStream = nullptr;
        }

        if (mBuffer != nullptr) {
            delete[] mBuffer;
            mBuffer = nullptr;
        }
    }

private:
    int mSampleRate = 44100;
    int mChannelCount = 2;
    int mFormat = AudioFormat::Float;
    int mBufferSize = 0;
    float *mBuffer = nullptr;

    AudioStream *mInputStream = nullptr;
    AudioStream *mOutputStream = nullptr;

    std::unique_ptr<DuplexStreamCallback> mInputCallback;
    std::unique_ptr<DuplexStreamCallback> mOutputCallback;
};
```

