    public class LayoutZoomer
    {
        [CommandMethod("ZoomToBlockInNewLayout")]
        public void ZoomToBlockInNewLayout()
        {
            Document doc = Application.DocumentManager.MdiActiveDocument;
            Editor ed = doc.Editor;

            // Prompt user for block name
            PromptStringOptions stringOptions = new PromptStringOptions("\nEnter block name: ");
            stringOptions.AllowSpaces = true;
            PromptResult stringResult = ed.GetString(stringOptions);
            if (stringResult.Status != PromptStatus.OK) return;
            string blockName = stringResult.StringResult.Trim();

            Database db = doc.Database;
            Transaction tr = db.TransactionManager.StartTransaction();
            try
            {
                // Check if the block exists
                BlockTable blockTable = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);
                if (!blockTable.Has(blockName))
                {
                    ed.WriteMessage("\nBlock not found.");
                    return;
                }
                ObjectId blockId = blockTable[blockName];

                // Create new layout
                string layoutName = "Layout_" + blockName;
                ObjectId layoutId = LayoutManager.Current.CreateAndMakeLayoutCurrent(layoutName);
                Layout layout = (Layout)tr.GetObject(layoutId, OpenMode.ForRead);

                // Create a viewport
                ViewportTableRecord vpRecord = new ViewportTableRecord();
                layout.BlockTableRecordId.UpgradeOpen();
                db.AddNewlyCreatedDBObject(vpRecord, true);
                layout.BlockTableRecordId.DowngradeOpen();

                // Add block reference to layout
                BlockTableRecord blkRec = (BlockTableRecord)tr.GetObject(blockId, OpenMode.ForRead);
                BlockReference blkRef = new BlockReference(Point3d.Origin, blockId);
                layout.BlockTableRecordId.UpgradeOpen();
                layout.BlockTableRecordId.InsertDBObject(blkRef, true);
                layout.BlockTableRecordId.DowngradeOpen();

                // Set the viewport size and position
                Extents3d extents = blkRef.Bounds.Value;
                Point2d center = new Point2d((extents.MinPoint.X + extents.MaxPoint.X) / 2, (extents.MinPoint.Y + extents.MaxPoint.Y) / 2);
                vpRecord.CenterPoint = center;
                vpRecord.CustomScale = 1;
                vpRecord.Width = extents.MaxPoint.X - extents.MinPoint.X;
                vpRecord.Height = extents.MaxPoint.Y - extents.MinPoint.Y;

                // Update the viewport display
                vpRecord.NumDefaultViewports();
                tr.Commit();
                ed.UpdateScreen();
            }
            catch (Autodesk.AutoCAD.Runtime.Exception ex)
            {
                ed.WriteMessage($"\nError: {ex.Message}");
            }
            finally
            {
                tr.Dispose();
            }
        }
    }
}
