void delete_directory_recursively(const std::string& db_path, int dir_id)
{
    // Delete all subdirectories recursively
    std::string subdirectories_sql = "SELECT id FROM directories WHERE parent_directory = ?;";
    sqlite3* db;
    if (sqlite3_open(db_path.c_str(), &db))
    {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return;
    }
    sqlite3_stmt* stmt;

    sqlite3_prepare_v2(db, subdirectories_sql.c_str(), -1, &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);

    while (sqlite3_step(stmt) == SQLITE_ROW)
    {
        int subdir_id = sqlite3_column_int(stmt, 0);
        delete_directory_recursively(db_path, subdir_id);
    }

    sqlite3_finalize(stmt);

    // Remove all files in the directory
    std::string delete_files_sql = "DELETE FROM files WHERE parent_directory = ?;";
    sqlite3_prepare_v2(db, delete_files_sql.c_str(), delete_files_sql.size(), &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);
    sqlite3_step(stmt);

    sqlite3_finalize(stmt);

    // Remove the directory
    std::string delete_dir_sql = "DELETE FROM directories WHERE id = ?;";
    sqlite3_prepare_v2(db, delete_dir_sql.c_str(), delete_dir_sql.size(), &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);
    sqlite3_step(stmt);

    sqlite3_finalize(stmt);
    sqlite3_close(db);
}
```

