void store_directory_structure_incrementally(const std::string& db_path, const std::filesystem::path& dir_path, int parent_id)
{
    for (const auto& entry : std::filesystem::directory_iterator{ dir_path })
    {
        std::string name = entry.path().filename().string();
        int existing_dir_id = get_directory_id(db_path, name, parent_id);

        if (entry.is_directory())
        {
            if (existing_dir_id == -1)
            {
                add_directory(db_path, name, parent_id);
                existing_dir_id = get_directory_id(db_path, name, parent_id);
            }

            store_directory_structure_incrementally(db_path, entry.path(), existing_dir_id);
        }
        else
        {
            std::string file_name = entry.path().filename().string();

            // Check if the file already exists in the database
            bool file_exists = false;
            std::string check_query = "SELECT 1 FROM files WHERE name = ? AND parent_directory = ?;";
            sqlite3* db;
            sqlite3_stmt* stmt;

            if (sqlite3_open(db_path.c_str(), &db))
            {
                std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
                return;
            }

            sqlite3_prepare_v2(db, check_query.c_str(), -1, &stmt, nullptr);
            sqlite3_bind_text(stmt, 1, name.c_str(), name.size(), SQLITE_TRANSIENT);
            sqlite3_bind_int(stmt, 2, parent_id);

            if (sqlite3_step(stmt) == SQLITE_ROW)
            {
                file_exists = true;
            }

            sqlite3_finalize(stmt);
            sqlite3_close(db);

            if (!file_exists)
            {
                add_file(db_path, file_name, parent_id);
            }
        }
    }
}
