    // ... (the rest of the code remains unchanged)
}
```

Modify the `store_directory_structure_incrementally` function to store the absolute path in the tables:

```cpp
void store_directory_structure_incrementally(const std::string& db_path, const std::filesystem::path& dir_path, int parent_id)
{
    for (const auto& entry : std::filesystem::directory_iterator{ dir_path })
    {
        std::string name = entry.path().filename().string();
        std::string full_path = entry.path().string();

        if (entry.is_directory())
        {
