        {
            std::string file_name = entry.path().filename().string();
            add_file(db_path, file_name, full_path, parent_id);
        }
    }
}
```

Finally, ensure that the `monitor_directory` function passes the absolute path to `store_directory_structure_incrementally`:

```cpp
void monitor_directory(const std::string& db_path, const std::string& dir_path)
{
    // ...

    namespace fs = std::filesystem;
    fs::path monitored_dir{ dir_path };

    // ...

    while (true)
    {
        store_directory_structure_incrementally(db_path, monitored_dir, 0); // Store initial structure

        // ...

        while (true) // Run monitoring and update loop
        {
            // ...

            if (it == last_write_map.end() || it->second != current_name)
            {
