2. Create a new Java class (e.g., `TaxiPerSourcePoint.java`) with the following code:

    ```java
    import org.apache.hadoop.conf.Configuration;
    import org.apache.hadoop.fs.Path;
    import org.apache.hadoop.io.IntWritable;
    import org.apache.hadoop.io.LongWritable;
    import org.apache.hadoop.io.Text;
    import org.apache.hadoop.mapreduce.Job;
    import org.apache.hadoop.mapreduce.Mapper;
    import org.apache.hadoop.mapreduce.Reducer;
    import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;
    import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;
    import org.apache.hadoop.util.GenericOptionsParser;

    import java.io.IOException;

    public class TaxiPerSourcePoint {

        public static class TaxiMapper extends Mapper<LongWritable, Text, Text, IntWritable> {

            private static final IntWritable one = new IntWritable(1);
            private Text sourcePoint = new Text();

            @Override
            protected void map(LongWritable key, Text value, Context context) throws IOException, InterruptedException {
                String[] fields = value.toString().split(",");
                if (fields.length >= 4) {
                    sourcePoint.set(fields[3]);
                    context.write(sourcePoint, one);
                }
            }
        }

        public static class TaxiReducer extends Reducer<Text, IntWritable, Text, IntWritable> {

            @Override
            protected void reduce(Text key, Iterable<IntWritable> values, Context context) throws IOException, InterruptedException {
                int sum = 0;
                for (IntWritable val : values) {
                    sum += val.get();
                }
                context.write(key, new IntWritable(sum));
            }
        }

        public static void main(String[] args) throws IOException, ClassNotFoundException, InterruptedException {
            Configuration conf = new Configuration();
            String[] otherArgs = new GenericOptionsParser(conf, args).getRemainingArgs();
            if (otherArgs.length != 2) {
                System.err.println("Usage: TaxiPerSourcePoint <input> <output>");
                System.exit(2);
            }

            Job job = Job.getInstance(conf, "taxi per source point");
            job.setJarByClass(TaxiPerSourcePoint.class);
            job.setMapperClass(TaxiMapper.class);
            job.setCombinerClass(TaxiReducer.class);
            job.setReducerClass(TaxiReducer.class);
            job.setOutputKeyClass(Text.class);
            job.setOutputValueClass(IntWritable.class);

            FileInputFormat.addInputPath(job, new Path(otherArgs[0]));
            FileOutputFormat.setOutputPath(job, new Path(otherArgs[1]));

            System.exit(job.waitForCompletion(true) ? 0 : 1);
        }
    }
    ```

