import org.apache.hadoop.io.Writable;

import java.io.DataInput;
import java.io.DataOutput;
import java.io.IOException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PointCoordinate implements Writable {
    private double lat;
    private double lon;

    public PointCoordinate() {}

    public PointCoordinate(double lat, double lon) {
        this.lat = lat;
        this.lon = lon;
    }

    public void readFields(DataInput in) throws IOException {
        lat = in.readDouble();
        lon = in.readDouble();
    }

    public void write(DataOutput out) throws IOException {
        out.writeDouble(lat);
        out.writeDouble(lon);
    }

    public static PointCoordinate fromString(String value) {
        Pattern pattern = Pattern.compile("POINT\\(([-+]?[0-9]*\\.?[0-9]+) ([-+]?[0-9]*\\.?[0-9]+)\\)");
        Matcher matcher = pattern.matcher(value);

        if (matcher.find()) {
            return new PointCoordinate(Double.parseDouble(matcher.group(2)), Double.parseDouble(matcher.group(1)));
        } else {
            return null;
        }
    }

    @Override
    public String toString() {
        return "(" + lat + "," + lon + ")";
    }
}
```

