        Camera.main.transform.position = new Vector3(tileCount / 2.0f - 0.5f, maxHeight / 2.0f + bottomLayerHeight / 2.0f, -10.0f);
    }

    float GetTerrainTop()
    {
        float highestYPos = float.MinValue;
        foreach (GameObject tile in terrainTiles)
        {
            if (tile.transform.position.y > highestYPos)
            {
                highestYPos = tile.transform.position.y;
            }
        }
        return highestYPos;
    }

    void GenerateTerrain()
    {
        foreach (GameObject tile in terrainTiles)
        {
            tile.GetComponent<TerrainHealth>().Die();
        }

        terrainTiles.Clear();

        GameObject tilePrefab = new GameObject("TerrainTile");
        SpriteRenderer renderer = tilePrefab.AddComponent<SpriteRenderer>();
        renderer.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f));
        renderer.color = terrainColor;

        tilePrefab.transform.localScale = new Vector3(100, 100, 1);

        BoxCollider2D collider = tilePrefab.AddComponent<BoxCollider2D>();
        collider.size = new Vector2(0.01f, 0.01f);

        // Generate the bottom layer
        for (int i = 0; i < tileCount; i++)
        {
            GameObject bottomTile = Instantiate(tilePrefab);
            bottomTile.transform.position = new Vector3(i, bottomLayerHeight, 0);
            bottomTile.GetComponent<SpriteRenderer>().color = bottomLayerColor;

            TerrainHealth health = bottomTile.AddComponent<TerrainHealth>();
            health.health = Random.Range(minHealth, maxHealth);

            terrainTiles.Add(bottomTile);
        }

        float prevYPos = bottomLayerHeight;
        float targetYPos = prevYPos;

        // Generate the rest of the tiles
        for (int i = 1; i < tileCount - 1; i++)
        {
            float progress = (float)i / (tileCount - 1);
            if (progress >= 1.0f || i % Mathf.FloorToInt(tileCount * 0.125f) == 0)
            {
                float noiseValue = Mathf.PerlinNoise(i * noiseScale, 0);
                targetYPos = bottomLayerHeight + 1 + maxHeight * noiseValue;
            }

            prevYPos = Mathf.Lerp(prevYPos, targetYPos, 0.25f);
            float yPos = prevYPos + Random.Range(-heightRandomness, heightRandomness);

            GameObject tile = Instantiate(tilePrefab);
            tile.transform.position = new Vector3(i, yPos, 0);

