#include <SPI.h>
#include <Ethernet.h>

// Replace with your network settings
byte mac[] = { 0xDE, 0xAD, 0xBE, 0xEF, 0xFE, 0xEE };
IPAddress ip(192, 168, 1, 101);
IPAddress remote(192, 168, 1, 100);

