Here's your updated code. I've introduced a new `float` variable to control the height scale (as `scale` will be used for width) and I've made some adjustments to the Perlin noise offset and input parameters to make the terrain smoother. Also, you don't need to add SpriteShapeController yourself, simply add this script to your GameObject with SpriteShapeController already attached to it.

```csharp
using UnityEngine;
using UnityEngine.U2D;

[RequireComponent(typeof(SpriteShapeController))]
public class TerrainCreator : MonoBehaviour
{
    public int scale = 5000;
    public int numofPoints = 100;
    public float heightScale = 3f;
    public float perlinOffset = 1000f;

    private SpriteShapeController shape;

    private void Start()
    {
        float distanceBwtnpoints = (float)scale / (float)numofPoints;
        shape = GetComponent<SpriteShapeController>();
        shape.spline.SetPosition(2, shape.spline.GetPosition(2) + Vector3.right * scale);
        shape.spline.SetPosition(3, shape.spline.GetPosition(3) + Vector3.right * scale);

        for (int i = 0; i < numofPoints - 2; i++)
        {
            float xPos = shape.spline.GetPosition(i + 1).x + distanceBwtnpoints;
            float yPos = Mathf.PerlinNoise(i * 0.1f, perlinOffset) * heightScale;
            shape.spline.InsertPointAt(i + 2, new Vector3(xPos, yPos));
        }

        for (int i = 2; i < numofPoints; i++)
        {
            shape.spline.SetTangentMode(i, ShapeTangentMode.Continuous);
            shape.spline.SetLeftTangent(i, new Vector3(-2, 0, 0));
            shape.spline.SetRightTangent(i, new Vector3(2, 0, 0));
        }
    }
}
```

