Creating a multi-window OpenGL application with SDL 2 requires the use of multiple `SDL_Window` objects and their corresponding `SDL_GLContext` objects. You'll need to create windows and contexts for each of the windows, then loop over the windows and draw an OpenGL scene for each.

Here's an example that creates two windows with OpenGL contexts, and clears each of them with a different color:

```cpp
#include <iostream>
#include <SDL.h>
#include <SDL_opengl.h>

const unsigned int WIDTH = 800;
const unsigned int HEIGHT = 600;

int main(int argc, char* argv[])
{
    if (SDL_Init(SDL_INIT_VIDEO) != 0)
    {
        std::cout << "SDL_Init Error: " << SDL_GetError() << std::endl;
        return 1;
    }

    // Set the desired OpenGL version
    SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION, 3);
    SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION, 3);
    SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK, SDL_GL_CONTEXT_PROFILE_CORE);

    // Create two windows
    SDL_Window* window1 = SDL_CreateWindow("Window 1", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, WIDTH, HEIGHT, SDL_WINDOW_OPENGL);
    SDL_Window* window2 = SDL_CreateWindow("Window 2", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, WIDTH, HEIGHT, SDL_WINDOW_OPENGL);

    if (window1 == nullptr || window2 == nullptr)
    {
        std::cout << "SDL_CreateWindow Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return 1;
    }

    // Create corresponding OpenGL contexts for windows
    SDL_GLContext context1 = SDL_GL_CreateContext(window1);
    SDL_GLContext context2 = SDL_GL_CreateContext(window2);

    if (context1 == NULL || context2 == NULL)
    {
        std::cout << "SDL_GL_CreateContext Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(window1);
        SDL_DestroyWindow(window2);
        SDL_Quit();
        return 1;
    }

    bool running = true;
    SDL_Event event;

    while (running)
    {
        // Poll events
        while (SDL_PollEvent(&event))
        {
            if (event.type == SDL_QUIT)
            {
                running = false;
            }
        }

        // Draw window1
        SDL_GL_MakeCurrent(window1, context1);
        glClearColor(0.2f, 0.3f, 0.4f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT);
        SDL_GL_SwapWindow(window1);

        // Draw window2
        SDL_GL_MakeCurrent(window2, context2);
        glClearColor(0.4f, 0.3f, 0.2f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT);
        SDL_GL_SwapWindow(window2);
    }

    // Clean up
    SDL_GL_DeleteContext(context1);
    SDL_GL_DeleteContext(context2);
    SDL_DestroyWindow(window1);
    SDL_DestroyWindow(window2);
    SDL_Quit();

    return 0;
}
```

Remember to compile with `g++` with the appropriate flags, like so:

```bash
g++ main.cpp -o multiwindow -lSDL2 -lGL
```

This example creates two windows with separate OpenGL contexts, and continuously updates the screen of the windows with different colors until the user closes one of the windows.

