Next, update the `useEffect` to handle multiple `user_id`s in `referralId`:

```javascript
useEffect(() => {
  referrersList(bearer).then((data) => {
    if (!data) return;
    setReferralList(data.data);
  });

  // Create an array of promises for each user_id in referralId
  const referralPromises = referralId.map((id) =>
    referrerIncomesStatistics(bearer, from, to, id)
  );

  // Wait for all promises to complete and combine the results
  Promise.all(referralPromises).then((results) => {
    if (results.some((result) => !result)) return;

    const combinedData: ReferrerIncomesStatistics = {
      open_link: [],
      registration: [],
      order_pay: [],
      subscription_pay: [],
    };

    results.forEach((result) => {
      if (result) {
        combinedData.open_link.push(...result.data.open_link);
        combinedData.registration.push(...result.data.registration);
        combinedData.order_pay.push(...result.data.order_pay);
        combinedData.subscription_pay.push(...result.data.subscription_pay);
      }
    });

    // Set the combined data in state
    setCombinedData(combinedData);
  });
}, [referralId]);
