<style>
  .container {
    display: flex;
    flex-wrap: wrap;
  }

  .photo {
    margin: 5px;
    width: calc(33.333% - 10px);
  }

  .photo img {
    width: 100%;
    height: auto;
  }
</style>
<title>Photo Album</title>
</head>
<body>
<h1>My Photo Album</h1>
<div class="container">
<?php
  // Set the images folder name
  $folder_path = 'images/';

  // Set the accepted extensions and initialize the file list
  $extensions_array = ['jpg', 'png', 'gif'];
  $file_list = [];

  // Scan the folder, filter images by extension, and push them into the file list
  if (is_dir($folder_path)) {
    $files = scandir($folder_path);
    foreach ($files as $file) {
      $file_extension = strtolower(pathinfo($file, PATHINFO_EXTENSION));
      if (in_array($file_extension, $extensions_array)) {
        array_push($file_list, $folder_path . $file);
      }
    }
  }

  // Output the image files in the file list
