```c
int is_item_in_cache(node *n, int item) {
    int item_found = 0;
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (n->cache[i] == item) {
            n->cache_age[i] = 1;
            item_found = 1;
        } else {
            n->cache_age[i]++;
        }
    }
    return item_found;
}
