In this example, we have a simple client/server that uses HTTP tunneling by base64 encoding and decoding data transmitted between the two.

First, let's write a simple server.c:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <stdbool.h>

#define PORT 1234
#define BUFFER_SIZE 4096

void base64_encode(const char *input, char *output, int count);
int base64_decode(const char *input, char *output);

int main() {
    char buffer[BUFFER_SIZE];
    char encoded_buffer[BUFFER_SIZE];
    char decoded_buffer[BUFFER_SIZE];

    bool is_running = true;

    int server_socket = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = htonl(INADDR_ANY);
    server_address.sin_port = htons(PORT);

    bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address));

    listen(server_socket, 5);

    struct sockaddr_in client_address;
    socklen_t client_address_size = sizeof(client_address);

    while (is_running) {
        int client_socket = accept(server_socket, (struct sockaddr*)&client_address, &client_address_size);
        memset(buffer, 0, BUFFER_SIZE);

        recv(client_socket, encoded_buffer, BUFFER_SIZE, 0);
        int decoded_length = base64_decode(encoded_buffer, decoded_buffer);

        printf("Received: %s\n", decoded_buffer);

        send(client_socket, "Base64 received and decoded.", 28, 0);
        close(client_socket);
    }

    close(server_socket);
    return 0;
}
```

Next, let's write a simple client.c:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define SERVER_IP "127.0.0.1"
#define PORT 1234
#define BUFFER_SIZE 4096

void base64_encode(const char *input, char *output, int count);
int base64_decode(const char *input, char *output);

int main() {
    char buffer[BUFFER_SIZE];
    char encoded_buffer[BUFFER_SIZE];
    char decoded_buffer[BUFFER_SIZE];

    int client_socket = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_address.sin_port = htons(PORT);

    connect(client_socket, (struct sockaddr*)&server_address, sizeof(server_address));

    printf("Enter message to send: ");
    fgets(buffer, BUFFER_SIZE, stdin);
    buffer[strlen(buffer) - 1] = '\0';

    base64_encode(buffer, encoded_buffer, strlen(buffer));

    send(client_socket, encoded_buffer, strlen(encoded_buffer), 0);

    recv(client_socket, buffer, BUFFER_SIZE, 0);
    printf("Server response: %s\n", buffer);
    close(client_socket);
    return 0;
}
```

Finally, let's add the base64_encode and base64_decode functions. You can use any available libraries or write the functions yourself. Here, we will use a simple implementation. Save this as base64.h and include it in your server.c and client.c files:

```c
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

static const char b64_table[65] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

void base64_encode(const char *input, char *output, int count) {
    const uint8_t *data = (const uint8_t *) input;
    int size = 0;
    uint32_t n = 0;
    int pad = count % 3;

    for (size_t i = 0; i < count; i += 3) {
        n = (data[i] << 16) + (data[i + 1] << 8) * (i + 1 < count) + (data[i + 2] * (i + 2 < count));
        output[size++] = b64_table[(n >> 18) & 0x3F];
        output[size++] = b64_table[(n >> 12) & 0x3F];
        if (i + 1 < count) {
            output[size++] = b64_table[(n >> 6) & 0x3F];
        }
        if (i + 2 < count) {
            output[size++] = b64_table[n & 0x3F];
        }
    }

    if (pad == 2) {
        output[size++] = '=';
    } else if (pad == 1) {
        output[size++] = '=';
        output[size++] = '=';
    }

    output[size] = '\0';
}

uint8_t b64_val(char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 26;
    }
    if (c >= '0' && c <= '9') {
        return c - '0' + 52;
    }
    if (c == '+') {
        return 62;
    }
    if (c == '/') {
        return 63;
    }
    return 0;
}

int base64_decode(const char *input, char *output) {
    int count = strlen(input);
    int pad = (input[count - 1] == '=' ? (input[count - 2] == '=' ? 2 : 1) : 0);
    int size = count * 3 / 4 - pad;
    uint32_t n = 0;

    for (size_t j = 0, i = 0; j < count; i += 3, j += 4) {
        n = b64_val(input[j]) << 18;
        n += b64_val(input[j + 1]) << 12;
        n += (j + 2 < count ? b64_val(input[j + 2]) : 0) << 6;
        n += (j + 3 < count ? b64_val(input[j + 3]) : 0);

        output[i] = (uint8_t) (n >> 16);
        if (i + 1 < count) {
            output[i + 1] = (uint8_t) (n >> 8);
        }
        if (i + 2 < count) {
            output[i + 2] = (uint8_t) n;
        }
    }

    output[size] = '\0';
    return size;
}
```

