```kotlin
import com.squareup.moshi.Json

data class GitHubUser(
    val id: Long,
    val login: String,
    @Json(name = "avatar_url") val avatarUrl: String,
    val name: String,
    val location: String,
    @Json(name = "public_repos") val publicRepos: Int,
    val followers: Int,
    val following: Int
)
```

5. In the `Main.kt` file, add the following code:

```kotlin
import com.squareup.moshi.Moshi
import com.squareup.moshi.kotlin.reflect.KotlinJsonAdapterFactory
import java.io.IOException

fun main() {
    val username = "octocat" // Replace with your favorite GitHub user's username
    val token = "YOUR_GITHUB_TOKEN" // Replace with your personal access token

    try {
        val json = ApiService.getFavoriteUser(username, token)
        val moshi = Moshi.Builder()
            .add(KotlinJsonAdapterFactory())
            .build()
        val adapter = moshi.adapter(GitHubUser::class.java)
        val user = adapter.fromJson(json)

        if (user != null) {
            println("Favorite user: ${user.name}")
            println("Location: ${user.location}")
            println("Followers: ${user.followers}")
            println("Following: ${user.following}")
            println("Public repos: ${user.publicRepos}")
        } else {
            println("Error: Couldn't fetch user data")
        }
    } catch (ioe: IOException) {
        println("Error: ${ioe.message}")
    }
}
