This is a simple HTTP server in C using the socket programming API. This server will print any received message and send a response back to the client.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fd, addr_len;
    struct sockaddr_in server_addr, client_addr;
    char buffer[BUFFER_SIZE];

    // Create a TCP socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to the port
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *) &server_addr, sizeof(server_addr)) == -1) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    if (listen(server_fd, 3) == -1) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }

    // Accept and handle incoming connections
    addr_len = sizeof(client_addr);
    while (1) {
        printf("Waiting for a connection...\n");
        client_fd = accept(server_fd, (struct sockaddr *) &client_addr, (socklen_t *) &addr_len);
        if (client_fd == -1) {
            perror("accept failed");
            continue;
        }

        printf("Connected!\n");

        // Read the message from the client
        memset(buffer, 0, BUFFER_SIZE);
        read(client_fd, buffer, BUFFER_SIZE);
        printf("Received message: %s\n", buffer);

        // Send a response back to the client
        char response[] = "HTTP/1.1 200 OK\nContent-Type: text/plain\nContent-Length: 12\n\nHello World!";
        write(client_fd, response, strlen(response));

        // Close the client socket
        close(client_fd);
    }

    close(server_fd);
    return 0;
}
```

