function setup() {
  createCanvas(canvasSize, canvasSize);
  pixelDensity(1);
}

function draw() {
  loadPixels();

  let t = (frameCount % animationFrames) / animationFrames;
  let ca = map(sin(2 * PI * t), -1, 1, -1, 1);
  let cb = map(sin(4 * PI * t), -1, 1, -1, 1);

  let w = canvasSize;
  let h = canvasSize;
  let xZoom = w / 3;
  let yZoom = h / 3;

  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) {
      let a = map(x, 0, w, -xZoom, xZoom);
      let b = map(y, 0, w, -yZoom, yZoom);

      let n = 0;
      while (n < maxIter) {
        let aa = a * a - b * b;
        let bb = 2 * a * b;
        a = aa + ca;
        b = bb + cb;
        if (abs(a + b) > 16) {
          break;
        }
        n++;
      }

      let c = map(n, 0, maxIter, 0, 255);
      let pixelIndex = (x + y * w) * 4;
      pixels[pixelIndex + 0] = c;
      pixels[pixelIndex + 1] = c;
      pixels[pixelIndex + 2] = c;
      pixels[pixelIndex + 3] = 255;
    }
  }

