    for (length = 0; message[length] != '\0' && message[length] != '\n'; length++);

    printf("\nMessage fragmentation:\n   [id]");
    int i;
    for (i = 0; i < length; i++)
        printf(" %3d", i);
    printf("\n[data]");
    for (i = 0; i < length; i++)
        printf(" %3c", message[i]);

    TipoItem mixedItems[length * 10];
    int mixedItemCount = 0;

    for (i = 0; i < length; i++)
    {
        int replicas = rand() % 10 + 1;
        int j;
        for (j = 0; j < replicas; j++)
        {
            TipoItem newItem;
            newItem.chave = i;
            newItem.pacote = message[i];
            mixedItems[mixedItemCount++] = newItem;
        }
    }

    for (i = mixedItemCount - 1; i > 0; i--)
    {
        int j = rand() % (i + 1);
        TipoItem temp = mixedItems[i];
        mixedItems[i] = mixedItems[j];
        mixedItems[j] = temp;
    }

    printf("\n\nOrder of arrival of packets (already considering replication) at destination:\n[id]   ");
    for (i = 0; i < mixedItemCount; i++)
        printf(" %3d", mixedItems[i].chave);
    printf("\n[data]");
