class server
{
    net::io_context ioc_;
    net::ip::tcp::acceptor acceptor_;
    std::vector<std::shared_ptr<client_session>> clients_;
    std::atomic_bool stopped_ = false;

public:
    server(net::ip::tcp::endpoint endpoint)
        : ioc_(1)
        , acceptor_(ioc_, endpoint)
    {
    }

    void run()
    {
        acceptor_.async_accept(net::make_strand(ioc_),
            [this](beast::error_code ec, net::ip::tcp::socket socket) {
                if (!ec) {
                    // Start a new session for this client
                    auto session = std::make_shared<client_session>(std::move(socket));
                    session->run();
                    clients_.push_back(session);
                }

                // Accept the next incoming connection
                if (!stopped_) {
                    run();
                }
            });

        ioc_.run();
    }

    void stop()
    {
        stopped_ = true;
        acceptor_.close();
        ioc_.stop();
    }
};

int main()
{
    server srv{ net::ip::tcp::endpoint{ net::ip::make_address("127.0.0.1"), 8080 } };
    std::thread t{ [&]() { srv.run(); } };

    std::this_thread::sleep_for(std::chrono::seconds(60));

    srv.stop();
    t.join();
}
```

In this example, we're using Boost.Beast to listen for incoming HTTP connections on port `8080`. When a connection is established, we create a new `client_session` object to handle the connection. This object reads the incoming HTTP request (which should contain the desired event type as part of the URL path), and then sends SSE responses to the client with the specified event type.

Note that this example assumes that incoming connections are handled by a server running on the same machine, listening on port 8080. In practice, you'll need to modify this example to suit your specific use case, including handling SSL connections (if necessary), implementing error handling, and managing the event loop that listens for incoming connections.

Also note that the `send_sse` function is largely the same as the one in the previous example that sends SSE events to a client. The only change here is that we've moved it into the `client_session` class so that it can be called from the `read_request` function.

