        StringBuilder sb = new StringBuilder();
        sb.append("METHOD=" + params.get("METHOD") + "&");
        sb.append("VERSION=" + params.get("VERSION") + "&");
        sb.append("PWD=" + API_SECRET + "&");
        sb.append("USER=" + API_KEY + "&");
        sb.append("SIGNATURE=" + API_SECRET + "&");

