```java
package com.psl.gems.pack;

import com.psl.gems.cards.PlayingCard;
import com.psl.gems.cards.Rank;
import com.psl.gems.cards.Suit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

public class PackOfCards {
    private List<PlayingCard> cards;

    public PackOfCards() {
        createFullPack();
    }

    public int size() {
        return cards.size();
    }

    public void shuffle() {
        Collections.shuffle(cards);
    }

    public PlayingCard getTopCard() {
        return cards.remove(0);
    }

    public PlayingCard getRandomCard() {
        return cards.remove(new Random().nextInt(cards.size()));
    }

    public void resetAscending() {
        createFullPack();
    }

    public void resetDescending() {
        createFullPack();
        Collections.reverse(cards);
    }

    private void createFullPack() {
        cards = new ArrayList<>();
        for (Suit suit : Suit.values()) {
            for (Rank rank : Rank.values()) {
                cards.add(new PlayingCard(suit, rank));
            }
        }
    }

    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();
        builder.append("[");

        for (PlayingCard card : cards) {
            builder.append(card.toString());
            builder.append(", ");
        }

        builder.replace(builder.length() - 2, builder.length(), "]");
        return builder.toString();
    }
}
```

