`script.js`:

```javascript
document.addEventListener('DOMContentLoaded', function () {
  function sortCards(cards, order) {
    return cards.slice().sort(function (a, b) {
      const aRank = a.RANK === 'ACE' ? 14 : a.RANK === 'KING' ? 13 : a.RANK === 'QUEEN' ? 12 : a.RANK === 'JACK' ? 11 : parseInt(a.RANK);
      const bRank = b.RANK === 'ACE' ? 14 : b.RANK === 'KING' ? 13 : b.RANK === 'QUEEN' ? 12 : b.RANK === 'JACK' ? 11 : parseInt(b.RANK);
      return order === 'ascending' ? aRank - bRank : bRank - aRank;
    });
  }

  const request = new XMLHttpRequest();
  request.open('GET', 'cards.json', true);
  request.onload = function () {
    if (request.status >= 200 && request.status < 400) {
      const cards = JSON.parse(request.responseText);
      renderColumns(cards);
    }
  };
  request.send();

  function renderColumns(cards) {
    const columns = {};

    cards.forEach(function (card) {
      if (!columns[card.SUIT]) {
        columns[card.SUIT] = [];
      }
      columns[card.SUIT].push(card);
    });

    for (const suit in columns) {
      const container = document.createElement('div');
      container.classList.add('column');

      container.innerHTML = '<h2>' + suit + '</h2>';
      const sortAscButton = document.createElement('button');
      sortAscButton.innerText = 'Sort Ascending';
      sortAscButton.addEventListener('click', function () {
        columns[suit] = sortCards(columns[suit], 'ascending');
        renderCards(container, columns[suit]);
      });

      const sortDescButton = document.createElement('button');
      sortDescButton.innerText = 'Sort Descending';
      sortDescButton.addEventListener('click', function () {
        columns[suit] = sortCards(columns[suit], 'descending');
        renderCards(container, columns[suit]);
      });

      container.appendChild(sortAscButton);
      container.appendChild(sortDescButton);

      const cardsContainer = document.createElement('div');
      cardsContainer.classList.add('cards-container');
      container.appendChild(cardsContainer);

      renderCards(cardsContainer, columns[suit]);

      document.querySelector('#content').appendChild(container);
    }
  }

  function renderCards(container, cards) {
    container.innerHTML = '';
    cards.forEach(function (card) {
      const cardElement = document.createElement('div');
      cardElement.classList.add('card');
      cardElement.innerText = card.RANK;
      container.appendChild(cardElement);
    });
  }
});

```

