  if (selectedCells.length >= 7 * 8) {
    drawHappyFaceInGrid();
  }
}

function updateAndDisplayTimer() {
  if (timer > 0) {
    timer -= deltaTime / 1000;
    textSize(24);
    fill(0);
    textAlign(CENTER, CENTER);
    text("Time remaining: " + Math.ceil(timer), width / 2, 20);
  }
}

function startTimer() {
  timer = 20;
}

function drawGrid() {
  for (let i = 0; i < 7; i++) {
    for (let j = 0; j < 8; j++) {
      stroke(0);
      rect(i * cellSize, j * cellSize, cellSize, cellSize);
      noFill();
    }
  }
}

function drawSelectedCells() {
  for (const cell of selectedCells) {
    let x1 = cell.col * cellSize;
    let y1 = cell.row * cellSize;
    if (cell.facePart) {
      fill(cell.facePart.color);
      rect(x1, y1, cellSize, cellSize);
    }
    stroke(255, 0, 0);
    line(x1, y1, x1 + cellSize, y1 + cellSize);
    line(x1, y1 + cellSize, x1 + cellSize, y1);
  }
}

function drawHappyFaceInGrid() {
  selectCell(2, 3, { color: [0, 0, 255] }); // Left eye
  selectCell(4, 3, { color: [0, 0, 255] }); // Right eye

  selectCell(3, 5, { color: [255, 165, 0] }); // Nose

  // Mouth
  selectCell(1, 6, { color: [255, 0, 0] });
  selectCell(2, 7, { color: [255, 0, 0] });
  selectCell(3, 7, { color: [255, 0, 0] });
  selectCell(4, 7, { color: [255, 0, 0] });
  selectCell(5, 6, { color: [255, 0, 0] });
}

function selectCell(col, row, facePart) {
  if (!isSelected(col, row)) {
    selectedCells.push({ col, row, facePart });
  }
}

function selectRandomPosition() {
  if (selectedCells.length >= 7 * 8) {
    return;
  }

  let col, row;
  do {
    col = Math.floor(random(7));
    row = Math.floor(random(8));
  } while (isSelected(col, row));

  selectedCells.push({ col, row });
  startTimer();
}

function isSelected(col, row) {
  return selectedCells.some(cell => cell.col === col && cell.row === row);
}
