        + "&returnUrl=" + URLEncoder.encode(returnUrl, "UTF-8")
        + "&requestEnvelope.errorLanguage=en_US";

    // HMAC-SHA1 signature
    String signature = getSignature(data);

    // create request string
    String request = "requestEnvelope.errorLanguage=en_US"
