  private static String getSignature(String data) throws Exception {
    String payPalPassword = URLEncoder.encode(API_PASSWORD, "UTF-8");
    String payPalSignature = URLEncoder.encode(API_SIGNATURE, "UTF-8");
    String payPalUsername = URLEncoder.encode(API_USERNAME, "UTF-8");

    // Append PayPal API credentials to data
    String dataWithCreds = data + "&password=" + payPalPassword + "&signature=" + payPalSignature + "&username=" + payPalUsername;

    // HMAC-SHA1 signature
    String HMAC_SHA1_ALGORITHM = "HmacSHA1";
    SecretKeySpec signingKey = new SecretKeySpec(payPalSignature.getBytes(), HMAC_SHA1_ALGORITHM);
    Mac mac = Mac.getInstance(HMAC_SHA1_ALGORITHM);
    mac.init(signingKey);
    byte[] signatureBytes = mac.doFinal(dataWithCreds.getBytes("UTF-8"));

    // Convert signature to Base64
    String signature = new String(Base64.encodeBase64(signatureBytes));
    signature = URLEncoder.encode(signature, "UTF-8");

    return signature;
  }
