8. Main loop to handle events:

```cpp
    while (true) {
        int event_count = epoll_wait(epollfd, events, MAX_EVENTS, -1);
        if (event_count < 0) {
            std::cout << "epoll_wait failure" << std::endl;
            break;
        }

        for (int i = 0; i < event_count; i++) {
            int sockfd = events[i].data.fd;
            if (sockfd == listenfd) {
                sockaddr_in client_address;
                socklen_t client_addrlength = sizeof(client_address);
                int connfd = accept(listenfd, (sockaddr *)&client_address, &client_addrlength);
                addfd(epollfd, connfd, true);
                clients_list.push_back(connfd);
                std::cout << "New client connected" << std::endl;
            } else if (events[i].events & EPOLLIN) {
                char buffer[BUFFER_SIZE];
                memset(buffer, '\0', BUFFER_SIZE);
                int data_read = recv(sockfd, buffer, BUFFER_SIZE, 0);
                if (data_read < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) {
                        std::cout << "Read later" << std::endl;
                        continue;
                    }

                    close(sockfd);
                    clients_list.remove(sockfd);
                    std::cout << "A client left" << std::endl;
                } else if (data_read == 0) {
                    close(sockfd);
                    clients_list.remove(sockfd);
                    std::cout << "A client left" << std::endl;
                } else {
                    // Handle the data
                    std::cout << "Received data: " << buffer << std::endl;

                    // Send the same data back to the client
                    send(sockfd, buffer, data_read, 0);
                }
            } else {
                std::cout << "Unhandled epoll event" << std::endl;
            }
        }
    }

    close(listenfd); // Close the socket
    return 0;
