    int port = atoi(argv[2]);
    std::list<int> clients_list;

    int ret = 0;
    sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    inet_pton(AF_INET, argv[1], &address.sin_addr);
    address.sin_port = htons(port);
```

5. Create TCP and UDP sockets:

```cpp
    int tcp_listenfd = socket(PF_INET, SOCK_STREAM, 0);
    if (tcp_listenfd == -1) {
        std::cout << "Failed to create TCP socket" << std::endl;
        return -1;
    }

    int udp_sockfd = socket(PF_INET, SOCK_DGRAM, 0);
    if (udp_sockfd == -1) {
        std::cout << "Failed to create UDP socket" << std::endl;
        return -1;
    }
```

6. Bind and listen:

```cpp
    ret = bind(tcp_listenfd, (sockaddr *)&address, sizeof(address));
    if (ret == -1) {
        std::cout << "Failed to bind TCP socket" << std::endl;
        return -1;
    }

    ret = listen(tcp_listenfd, 5);
    if (ret == -1) {
        std::cout << "Failed to listen to TCP socket" << std::endl;
        return -1;
    }

