    addfd(epollfd, udp_sockfd, true);
```

8. Main loop to handle events:

```cpp
    while (true) {
        int event_count = epoll_wait(epollfd, events, MAX_EVENTS, -1);
        if (event_count < 0) {
            std::cout << "epoll_wait failure" << std::endl;
            break;
        }

        for (int i = 0; i < event_count; i++) {
            int sockfd = events[i].data.fd;
            if (sockfd == tcp_listenfd) {
                sockaddr_in client_address;
                socklen_t client_addrlength = sizeof(client_address);
                int connfd = accept(tcp_listenfd, (sockaddr *)&client_address, &client_addrlength);
                addfd(epollfd, connfd, true);
                clients_list.push_back(connfd);
                std::cout << "New TCP client connected" << std::endl;
            } else if (sockfd == udp_sockfd) {
                sockaddr_in client_address;
                socklen_t client_addrlength = sizeof(client_address);
                char buffer[BUFFER_SIZE];
                memset(buffer, '\0', BUFFER_SIZE);

                int data_read = recvfrom(udp_sockfd, buffer, BUFFER_SIZE, 0,
                                         (sockaddr *)&client_address, &client_addrlength);
                if (data_read <= 0) {
                    continue;
                }
                // Handle the data
                std::cout << "Received UDP data: " << buffer << std::endl;

                // Send the same data back to the client
                sendto(udp_sockfd, buffer, data_read, 0,
                       (sockaddr *)&client_address, client_addrlength);
            } else if (events[i].events & EPOLLIN) {
                char buffer[BUFFER_SIZE];
                memset(buffer, '\0', BUFFER_SIZE);
                int data_read = recv(sockfd, buffer, BUFFER_SIZE, 0);
                if (data_read < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) {
                        std::cout << "Read later" << std::endl;
                        continue;
                    }

                    close(sockfd);
                    clients_list.remove(sockfd);
                    std::cout << "A TCP client left" << std::endl;
                } else if (data_read == 0) {
                    close(sockfd);
                    clients_list.remove(sockfd);
                    std::cout << "A TCP client left" << std::endl;
                } else {
                    // Handle the data
                    std::cout << "Received TCP data: " << buffer << std::endl;

                    // Send the same data back to the client
                    send(sockfd, buffer, data_read, 0);
                }
            } else {
                std::cout << "Unhandled epoll event" << std::endl;
            }
        }
    }

    close(tcp_listenfd); // Close the TCP socket
    close(udp_sockfd);   // Close the UDP socket
    return 0;
}
```

This example demonstrates how to create a high-concurrent server using edge-triggered epoll for both TCP and UDP connections.

