```csharp
using UnityEngine;

public class EconomyManager : MonoBehaviour
{
    public int currentPlayerMoney = 1000; // Starting player's money

    // Returns true if the player has enough money to make the purchase
    public bool CanAfford(int cost)
    {
        return currentPlayerMoney >= cost;
    }

    // Deduct the cost from the player's money
    public void MakePurchase(int cost)
    {
        if (CanAfford(cost))
        {
            currentPlayerMoney -= cost;
        }
