public unsafe struct MD5Hash
{
    private fixed byte _hashBytes[16];

    public MD5Hash(byte* hashBytes)
    {
        if (hashBytes == null)
        {
            throw new ArgumentNullException(nameof(hashBytes));
        }

        fixed (byte* p = _hashBytes)
        {
            for (int i = 0; i < 16; i++)
            {
                *(p + i) = *(hashBytes + i); // Copy bytes from input to struct
            }
        }
    }

    public byte[] ToArray()
    {
        byte[] result = new byte[16];
        fixed (byte* p = _hashBytes)
        {
            for (int i = 0; i < 16; i++)
            {
                result[i] = *(p + i); // Copy bytes from struct to new array
            }
        }
        return result;
    }

