from flask import Flask, request, jsonify
import requests
from bs4 import BeautifulSoup
from selenium import webdriver
import time

app = Flask(__name__)

@app.route('/api', methods=['POST'])
def find_similar_products():
    data = request.get_json()
    img_src = data.get('img_src', '')

    # Set up Selenium WebDriver
    options = webdriver.ChromeOptions()
    options.add_argument("--headless")
    options.add_argument('--no-sandbox')
    options.add_argument('--disable-dev-shm-usage')
    driver = webdriver.Chrome(chrome_options=options)

    product_links = []

    # Search on AliExpress
    driver.get(f"https://www.aliexpress.com/wholesale?SearchText={img_src}")
    time.sleep(5)
    soup = BeautifulSoup(driver.page_source, 'html.parser')
    products = soup.find_all('a', {"class": "product"})
    for product in products:
        product_links.append(product['href'])

    # Search on CJDropshipping
    driver.get(f"https://app.cjdropshipping.com/gallery-search/index?keyword={img_src}")
    time.sleep(5)
    soup = BeautifulSoup(driver.page_source, 'html.parser')
    products = soup.find_all('a', {"class": "single___lF46A"})
    for product in products:
        product_links.append(product['href'])

    # Search on Alibaba
    driver.get(f"https://www.alibaba.com/trade/search?fsb=y&IndexArea=product_en&CatId=&SearchText={img_src}")
    time.sleep(5)
    soup = BeautifulSoup(driver.page_source, 'html.parser')
    products = soup.find_all('a', {"class": "organic-gallery-title"})
    for product in products:
        product_links.append(product['href'])

    driver.quit()

    return jsonify({'products': product_links})

if __name__ == '__main__':
