    // Открытие файла для чтения аудио-сигнала
    fh = fopen("audio.wav", "rb");

    // Начало распознавания речи
    ps_start_utt(ps);

    while (!feof(fh)) {
        size_t nsamp;
        nsamp = fread(buf, 2, 512, fh);
        rv = ps_process_raw(ps, buf, nsamp, FALSE, FALSE);
    }

    // Завершение распознавания речи
    ps_end_utt(ps);

    // Получение результата распознавания
    hyp = ps_get_hyp(ps, &score);
    printf("Recognized: %s\n", hyp);

    // Освобождение ресурсов
    fclose(fh);
    ps_free(ps);
    cmd_ln_free_r(config);

    return 0;

}
