    session_options.config.mutable_gpu_options()->set_allow_growth(true);

    RunOptions run_options;
    run_options.set_trace_level(run_options.FULL_TRACE);

    SavedModelBundle bundle;

    auto status = LoadSavedModel(session_options, run_options, model_path,
                                 {"serve"},
                                &bundle);

    if (!status.ok())
    {
        std::cerr << "Error loading model: " << status << std::endl;
        return nullptr;
    }

    return std::move(bundle.session);
}

// Query the model to test if the loaded audio contains the wake word.
bool DetectWakeWord(const std::unique_ptr<Session> &session, const std::vector<float> &audio_data)
{
    // Convert input data to Tensor
    Tensor input(tensorflow::DT_FLOAT, tensorflow::TensorShape({1, audio_data.size()}));
    auto input_tensor_mapped = input.flat<float>();
    for (size_t i = 0; i < audio_data.size(); ++i)
    {
        input_tensor_mapped(i) = audio_data[i];
    }

    // Run the model
    std::vector<Tensor> outputs;
    auto status = session->Run({{"input_placeholder", input}}, {"output_node"}, {}, &outputs);

    if (!status.ok())
    {
        std::cerr << "Error running model: " << status << std::endl;
        return false;
    }

    // Check if output label is equal to the wake word index
    auto output = outputs[0].matrix<float>();
    int max_label_index = -1;
    float max_label_val = -FLT_MAX;

    for (int i = 0; i < outputs[0].dim_size(1); ++i)
    {
        if (output(0, i) > max_label_val)
        {
            max_label_index = i;
            max_label_val = output(0, i);
        }
    }

    return max_label_index == WAKE_WORD_LABEL_INDEX;
}

