Here is an example of how you can authenticate using a registered app secret:

```csharp
using Microsoft.Identity.Client;
using Microsoft.Graph;
using System;

namespace OutlookPlugin
{
    public class AuthenticationProvider
    {
        const string clientId = "your-client-id";
        const string clientSecret = "your-client-secret";
        const string tenantId = "your-tenant-id";
        const string authority = "https://login.microsoftonline.com/{0}/oauth2/v2.0/token";
        static string[] scopes = new string[] { "https://graph.microsoft.com/.default" };

        public static async Task<GraphServiceClient> GetAuthenticatedClientAsync()
        {
            IConfidentialClientApplication app;
            app = ConfidentialClientApplicationBuilder.Create(clientId)
                .WithClientSecret(clientSecret)
                .WithAuthority(string.Format(authority, tenantId)) 
                .Build();

            AuthenticationResult result = null;
            try
            {
                // Acquire a token for the Graph API
                result = await app.AcquireTokenForClient(scopes).ExecuteAsync();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error acquiring access token: {ex}");
                return null;
            }

            // Create a new Graph service client using the acquired token
            GraphServiceClient graphClient = new GraphServiceClient(
                new DelegateAuthenticationProvider(
                    async (requestMessage) =>
                    {
                        requestMessage.Headers.Authorization =
                            new System.Net.Http.Headers.AuthenticationHeaderValue("bearer", result.AccessToken);
                    }));

            return graphClient;
        }
    }
}
