```csharp
using Microsoft.Identity.Client;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace OutlookPlugin
{
    public class AuthenticationHelper
    {
        private static string clientId = "<your_client_id>";
        private static string tenantId = "<your_tenant_id>";
        private static string clientSecret = "<your_client_secret>";
        private static string[] scopes = new string[] { "https://graph.microsoft.com/.default" };

        public static async Task<AuthenticationResult> GetAccessTokenAsync()
        {
            IConfidentialClientApplication app = ConfidentialClientApplicationBuilder
                .Create(clientId)
                .WithClientSecret(clientSecret)
                .WithAuthority(new Uri($"https://login.microsoftonline.com/{tenantId}/v2.0"))
                .Build();

            AuthenticationResult authResult = null;
            try
            {
                authResult = await app.AcquireTokenForClient(scopes).ExecuteAsync();
            }
            catch (MsalServiceException ex)
            {
                // Handle authentication exception
                Console.WriteLine("Error acquiring token: " + ex.Message);
            }

            return authResult;
        }
    }
}
```

