  }

  searchManga(page, keyword) {
    const queryParams = {
      start: this.pageSize * (page - 1),
      limit: this.pageSize,
      keywords: keyword,
    };
    const path = '/v1/search/getSearchManga';
    return this.getUrl(path, queryParams);
  }

  searchChapter(mangaId) {
    const queryParams = { mangaId };
    const path = '/v1/manga/getDetail';
    return this.getUrl(path, queryParams);
  }

  searchPic(chapterId) {
    const queryParams = {
      netType: '4',
      loadreal: '1',
      imageQuality: '2',
      mangaSectionId: chapterId,
    };
    const path = '/v1/manga/getRead';
    return this.getUrl(path, queryParams);
  }
}

module.exports = ParserApiUtil;
