Class 2: TCPPacketServer.java
```
import java.net.ServerSocket;
import java.net.Socket;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class TCPPacketServer {
    public static final int PORT = 1024;

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("Server is running on port " + PORT);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                handleClient(clientSocket);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void handleClient(Socket clientSocket) {
        try (
            ObjectOutputStream outputStream = new ObjectOutputStream(clientSocket.getOutputStream());
            ObjectInputStream inputStream = new ObjectInputStream(clientSocket.getInputStream())
        ) {
            Packet packet = (Packet) inputStream.readObject();
            System.out.println("Received packet with serial number: " + packet.getSerialNo() + " and data: " + packet.getData());

            if (packet.getData().equals("CLOSE")) {
                inputStream.close();
                outputStream.close();
                clientSocket.close();
                return;
            }

            String data = packet.getData().toUpperCase();
            outputStream.writeObject(new Packet(packet.getSerialNo(), data));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

