```

JavaScript (script.js):

```javascript
$(function() {
  $('.node').draggable();

  $('.output').draggable({
    helper: 'clone',
    revert: 'invalid',
    start: function() {
      $(this).data('connected', false);
    },
    stop: function() {
      if (!$(this).data('connected')) {
        console.log('Not connected');
      }
    }
  });

  $('.input').droppable({
    accept: '.output',
    tolerance: 'touch',
    drop: function(event, ui) {
      $(ui.draggable).data('connected', true);
      console.log('Working');
    }
  });
});
```

