React Remix web framework is a fully-documented framework, but the generic concepts in React (like useEffect hook) can be used without any issues. Here's an example of using the useEffect hook in a React Remix component:

First, make sure to install React Remix:

```
npm install @remix-run/react
```

Now, create a functional component that uses the useEffect hook:

```javascript
// MyComponent.js
import React, { useState, useEffect } from 'react';

function MyComponent() {
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const response = await fetch('https://jsonplaceholder.typicode.com/posts');
        const data = await response.json();
        setData(data);
      } catch (error) {
        console.error('Failed to fetch data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  return (
    <div>
      {isLoading ? (
        <p>Loading data...</p>
      ) : (
        <ul>
          {data.map((item) => (
            <li key={item.id}>{item.title}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default MyComponent;
```

Next, use the Remix `Outlet` to render the `MyComponent` component in a route component:

```javascript
// routes/index.jsx
import { Outlet } from '@remix-run/react';
import MyComponent from '../MyComponent';

function Index() {
  return (
    <div>
      <h1>Hello from Remix</h1>
      <MyComponent />
      <Outlet />
    </div>
  );
}

export default Index;
```

In this example, the `useEffect` hook fetches data from an API when the `MyComponent` is mounted, and updates the component's state accordingly. Note that you might need to configure your data fetching URL and how it's consumed depending on the specific backend service you use, but this should give you a good starting point. The use of the useEffect hook is the same as you would use in any React application.

To create a React Remix app with Express backend and display the D3.js "Versor Dragging" example on the default route, follow these steps.

Note: This answer assumes that you already have created a React Remix App with Express as the backend. If not, please follow the instructions in previous answer first.

1. Install the required packages for D3:

```bash
npm install d3
```

2. Replace the contents of the `routes/index.jsx` file with the following code:

```jsx
// routes/index.jsx
import React, { useRef, useEffect } from 'react';
import { Outlet } from '@remix-run/react';
import * as d3 from 'd3';

function Index() {
  const svgRef = useRef();

  useEffect(() => {
    const width = 800;
    const height = 450;

    const svg = d3.select(svgRef.current)
      .attr('viewBox', [0, 0, width, height]);

    const projection = d3.geoOrthographic()
      .scale((width - 10) / (2 * Math.PI))
      .rotate([0, -15])
      .translate([width / 2, height / 2])
      .precision(0.1);

    const path = d3.geoPath().projection(projection);
    const graticule = d3.geoGraticule();
    const display = svg.append('g');

    display.append('path')
      .datum(graticule)
      .attr('fill', 'none')
      .attr('stroke', '#ccc')
      .attr('stroke-width', 0.5)
      .attr('d', path);

    display.selectAll('.graticule')
      .data(graticule.lines())
      .enter().append('path')
      .attr('class', 'graticule')
      .attr('d', path)
      .attr('fill', 'none')
      .attr('stroke', '#ccc');

    display.append('path')
      .datum(graticule.outline())
      .attr('fill', 'none')
      .attr('stroke', '#000')
      .attr('d', path);

    const versor = {
      start: null,
      current: null,
      drag: function (projection, delta) {
        const v0 = versor.start,
          v1 = [v0[0] + delta[0], v0[1] - delta[1]],
          R = versor.Rotation_delta(v0, v1);
        projection.rotate(versor.Euler(R));
      },
      Rotation: function (v) {
        return [-v[1], -v[0], v[2]].map(function (_) {
          return _ / 2 / Math.PI * 360;
        });
      },
      Rotation_delta: function (v0, v1) {
        const p = [-v1[0] * v0[1] + v0[0] * v1[1], -v0[0] * v1[0] - v1[1] * v0[1], v0[0] * v1[1] + v1[0] * v0[1]];
        const R = Math.sqrt(p[0] * p[0] + p[1] * p[1] + p[2] * p[2]);
        const versor = [Math.cos(R / 2), p[2] * Math.sin(R / 2) / R, -p[1] * Math.sin(R / 2) / R, p[0] * Math.sin(R / 2) / R];

        function Slerp(t) {
          const interp = Math.sin((1 - t) * R) / Math.sin(R) * versor;
          interp.push(Math.sin(t * R) / Math.sin(R) * versor[0]);
          return interp;
        }

        return Slerp;
      },
      drag_start: function (event) {
        this.start = this.current || projection.rotate();
      },
      drag_end: function (event) {
        this.start = null;
      },
      dragged: function (event) {
        if (this.start) {
          this.drag(projection, [event.dx, event.dy]);
          this.current = projection.rotate();
          display.selectAll('path').attr('d', path);
        }
      },
    };

    const d3_drag = d3.drag()
      .on('start', versor.drag_start.bind(versor))
      .on('end', versor.drag_end.bind(versor))
      .on('drag', versor.dragged.bind(versor));

    svg.call(d3_drag);
  }, []);

  return (
    <div>
      <h1>Versor Dragging with D3.js</h1>
      <svg ref={svgRef}></svg>
      <Outlet />
    </div>
  );
}

export default Index;
```

This code sets up the versor dragging example using D3.js and displays it in the main route of the Remix app.

