Here is the Java code to receive IMAP mail and store subject "number" and message example "12345678" in a Hashtable.

```java
import java.util.*;
import javax.mail.*;
import javax.mail.internet.*;

public class ImapMail {

    public static void main(String[] args) throws Exception {

        String host = "imap.gmail.com";
        String username = "example@gmail.com";
        String password = "password";

        // create properties object for the IMAP connection
        Properties properties = new Properties();
        properties.setProperty("mail.store.protocol", "imap");
        properties.setProperty("mail.imap.host", host);
        properties.setProperty("mail.imap.port", "993");
        properties.setProperty("mail.imap.ssl.enable", "true");

        // create session with the credentials
        Session session = Session.getInstance(properties, new Authenticator() {
            protected PasswordAuthentication getPasswordAuthentication() {
                return new PasswordAuthentication(username, password);
            }
        });

        // create the IMAP store and connect to the server
        Store store = session.getStore("imap");
        store.connect(host, username, password);

        // create the inbox folder and open it in read-only mode
        Folder inbox = store.getFolder("INBOX");
        inbox.open(Folder.READ_ONLY);

        // get the messages in the inbox folder
        Message[] messages = inbox.getMessages();

        // create a Hashtable to store the subject and message body
        Hashtable<String, String> mailHash = new Hashtable<String, String>();

        // iterate through the messages and add the subject and message to the Hashtable
        for (int i = 0; i < messages.length; i++) {
            String subject = messages[i].getSubject();
            String body = getTextFromMessage(messages[i]);

            // check if the subject contains the word "number"
            if (subject.toLowerCase().contains("number")) {
                mailHash.put(subject, body);
            }
        }

        // print out the Hashtable
        System.out.println(mailHash);

        // close the mailbox and store
        inbox.close(false);
        store.close();
    }

    // helper function to get the text from a Message object
    private static String getTextFromMessage(Message message) throws Exception {
        String result = "";
        if (message.isMimeType("text/plain")) {
            result = message.getContent().toString();
        } else if (message.isMimeType("multipart/*")) {
            MimeMultipart multipart = (MimeMultipart) message.getContent();
            result = getTextFromMimeMultipart(multipart);
        }
        return result;
    }

    // helper function to get the text from a MimeMultipart object
    private static String getTextFromMimeMultipart(MimeMultipart multipart) throws Exception {
        String result = "";
        int count = multipart.getCount();
        for (int i = 0; i < count; i++) {
            BodyPart bodyPart = multipart.getBodyPart(i);
            if (bodyPart.isMimeType("text/plain")) {
                result = result + "\n" + bodyPart.getContent();
                break;
            } else if (bodyPart.isMimeType("multipart/*")) {
                result = result + getTextFromMimeMultipart((MimeMultipart) bodyPart.getContent());
            }
        }
        return result;
    }

}
```

This code connects to the IMAP server using SSL and retrieves the messages in the INBOX folder. It then iterates through the messages and checks if the subject contains the word "number". If it does, it adds the subject and message body to a Hashtable. The Hashtable is then printed out. This code also includes helper functions to extract the text from a Message and MimeMultipart object.

Here is a PHP script to send and receive messages via HTTP:

Sending a message:

```php
<?php

// Set the URL of the endpoint for sending messages
$url = 'http://your-receiving-endpoint.com';

// Set the parameters to send in the message
$params = array(
  'recipient' => 'john@example.com',
  'subject' => 'Hello from PHP!',
  'body' => 'This is a message sent via HTTP.'
);

// Send the POST request to the endpoint with the message parameters
$result = file_get_contents($url, false, stream_context_create(array(
    'http' => array(
        'method' => 'POST',
        'header' => 'Content-type: application/x-www-form-urlencoded',
        'content' => http_build_query($params)
    )
)));

// Check if the message was sent successfully
if ($result === false) {
  echo 'There was an error sending the message';
} else {
  echo 'Message sent successfully';
}

?>
```

Receiving a message:

```php
<?php

// Check if the request method is POST and if the necessary message parameters are set
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['recipient']) && isset($_POST['subject']) && isset($_POST['body'])) {

  // Store the message parameters in variables
  $recipient = $_POST['recipient'];
  $subject = $_POST['subject'];
  $body = $_POST['body'];

  // Do something with the received message
  // For example, send an email to the recipient with the subject and body
  $headers = array(
    'From: your-email@example.com',
    'Reply-To: your-email@example.com',
    'X-Mailer: PHP/' . phpversion()
  );
  mail($recipient, $subject, $body, implode("\r\n", $headers));

  // Send a response to confirm message receipt
  echo 'Message received successfully';

} else {

  // Send an error response if the request method is not POST or the necessary message parameters are not set
  header($_SERVER['SERVER_PROTOCOL'] . ' 400 Bad Request', true, 400);
  echo 'Bad Request';

}

?>
```

This script receives a POST request with the message parameters in the body. It checks if the necessary parameters are set, stores them in variables, and does something with the received message (in this case, sends an email to the recipient). It then sends a response to confirm that the message was received. If the request method is not POST or the necessary parameters are not set, it sends an error response. Note that this code is for demonstration purposes only and should not be used in production systems without appropriate security measures in place.

Here is a Java code to use this HTTP messenger:

Sending a message:

```java
import java.io.*;
import java.net.*;

public class HttpMessenger {

    public static void main(String[] args) throws Exception {

        // Set the URL of the endpoint for sending messages
        URL url = new URL("http://your-receiving-endpoint.com");

        // Set the parameters to send in the message
        String recipient = "john@example.com";
        String subject = "Hello from Java!";
        String body = "This is a message sent via HTTP.";

        // Send the POST request to the endpoint with the message parameters
        HttpURLConnection con = (HttpURLConnection) url.openConnection();
        con.setRequestMethod("POST");
        con.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
        con.setDoOutput(true);
        OutputStream os = con.getOutputStream();
        os.write(("recipient=" + recipient + "&subject=" + subject + "&body=" + body).getBytes());
        os.flush();
        os.close();

        // Check if the message was sent successfully
        int responseCode = con.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            System.out.println("Message sent successfully");
        } else {
            System.out.println("There was an error sending the message");
        }

    }

}
```

Receiving a message:

```java
import java.io.*;
import java.net.*;
import java.util.*;

public class HttpMessenger {

    public static void main(String[] args) throws Exception {

        // Create a server socket on port 8080
        ServerSocket serverSocket = new ServerSocket(8080);

        // Wait for a client connection
        Socket clientSocket = serverSocket.accept();

        // Read the request from the client
        BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
        String inputLine;
        StringBuilder request = new StringBuilder();
        while ((inputLine = in.readLine()) != null && !inputLine.isEmpty()) {
            request.append(inputLine).append("\r\n");
        }
        System.out.println(request.toString());

        // Parse the message parameters from the request body
        String[] params = request.toString().split("\r\n\r\n")[1].split("&");
        Map<String, String> paramMap = new HashMap<>();
        for (String param : params) {
            String[] splitParam = param.split("=");
            paramMap.put(splitParam[0], splitParam[1]);
        }

        // Store the message parameters in variables
        String recipient = paramMap.get("recipient");
        String subject = paramMap.get("subject");
        String body = paramMap.get("body");

        // Do something with the received message
        // For example, send an email to the recipient with the subject and body
        String sender = "your-email@example.com";
        String[] to = new String[] { recipient };
        String[] cc = new String[0];
        String[] bcc = new String[0];
        String messageBody = body;
        EmailUtility.sendEmail(sender, to, cc, bcc, subject, messageBody);

        // Send a response to confirm message receipt
        PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true);
        out.println("HTTP/1.1 200 OK");
        out.println("Content-Type: text/plain");
        out.println("Connection: close");
        out.println();
        out.println("Message received successfully");

        // Close the input and output streams and the client and server sockets
        in.close();
        out.close();
        clientSocket.close();
        serverSocket.close();

    }

}
```

This code sends a POST request with the message parameters to the receiving endpoint URL. It checks if the response code is HTTP OK to confirm that the message was sent successfully. The code also receives the POST request from the sending endpoint and parses the message parameters from the request body. It stores the parameters in variables, does something with the received message (in this case, sends an email to the recipient), and sends a response to confirm message receipt. Note that this code is for demonstration purposes only and should not be used in production systems without appropriate security measures in place.

To display support and resistance levels on a chart in MQL5, you can use the following example code:

```cpp
//+------------------------------------------------------------------+
//|                                               SupportResistance.mq5 |
//|                                  Copyright 2021, Example Author. |
//|                                             https://www.mql5.com |
//+------------------------------------------------------------------+
#property copyright "Copyright 2021, Example Author."
#property link      "https://www.mql5.com"
#property version   "1.00"
#property strict
#property indicator_chart_window
#property indicator_buffers 2
#property indicator_plots   2

double SupportBuffer[];
double ResistanceBuffer[];

input int Lookback = 150; // Look back bars for support and resistance calculation

void OnInit()
  {
   SetIndexBuffer(0,SupportBuffer,INDICATOR_DATA);
   SetIndexBuffer(1,ResistanceBuffer,INDICATOR_DATA);
   PlotIndexSetInteger(0,PLOT_DRAW_BEGIN, Lookback);
   PlotIndexSetInteger(1,PLOT_DRAW_BEGIN, Lookback);

   PlotIndexSetInteger(0,PLOT_LINE_COLOR, clrGreen);  // Support level color
   PlotIndexSetInteger(1,PLOT_LINE_COLOR, clrRed);    // Resistance level color

   SetIndexStyle(0,DRAW_LINE, STYLE_SOLID, 2, clrGreen);
   SetIndexStyle(1,DRAW_LINE, STYLE_SOLID, 2, clrRed);
  }

int OnCalculate(const int rates_total, const int prev_calculated, const datetime &time[], const double &open[], const double &high[], const double &low[], const double &close[], const long &tick_volume[], const long &volume[], const int &spread[])
  {
   if(rates_total < Lookback)
      return(0);

   ArraySetAsSeries(SupportBuffer,true);
   ArraySetAsSeries(ResistanceBuffer,true);

   for(int i = Lookback; i < rates_total && !IsStopped(); i++)
     {
      // Calculate support from the lowest lows
      double support = low[i];
      for(int j = 1; j < Lookback; j++)
        {
         if(low[i-j] < support)
            support = low[i-j];
        }
      SupportBuffer[i] = support;

      // Calculate resistance from the highest highs
      double resistance = high[i];
      for(int j = 1; j < Lookback; j++)
        {
         if(high[i-j] > resistance)
            resistance = high[i-j];
        }
      ResistanceBuffer[i] = resistance;
     }

   return rates_total;
  }
```

This code defines an indicator that calculates support and resistance levels considering a specific number of bars as a lookback parameter (default value is 150 bars). The support level is represented by the lowest lows and the resistance level represented by the highest highs within the selected lookback period. The chart display will show these support and resistance levels as horizontal lines on the chart.

Please note that this script should be saved as a separate file. To use this script, create a new custom indicator in MetaEditor and save it as `SupportResistance.mq5`.  Compile the code and attach the `SupportResistance` custom indicator to your chart in the MetaTrader 5 platform for testing.

من هذا الكود class MainActivity : AppCompatActivity() {

    private lateinit var player: SimpleExoPlayer
    private lateinit var playButton: Button
    private lateinit var lyricsTextView: TextView
    private lateinit var startRecordingButton: Button
    private lateinit var stopRecordingButton: Button
    private var mediaRecorder: MediaRecorder? = null
    private lateinit var outputFilePath: String
    private val lyricsHandler = Handler(Looper.getMainLooper())
    private lateinit var lyricsRunnable: Runnable
    private var mediaPlayer: MediaPlayer? = null
    private lateinit var playRecordingButton: Button


    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        playButton = findViewById(R.id.playButton)
        lyricsTextView = findViewById(R.id.lyricsTextView)
        startRecordingButton = findViewById(R.id.startRecordingButton)
        stopRecordingButton = findViewById(R.id.stopRecordingButton)

        playButton.setOnClickListener {
            initializePlayer()
            displayLyrics()
        }

        startRecordingButton.setOnClickListener {
            requestAudioPermissionAndStartRecording()
        }

        stopRecordingButton.setOnClickListener {
            stopRecording()
        }

        playRecordingButton = findViewById(R.id.playRecordingButton)

        playRecordingButton.setOnClickListener {
            playRecording()
        }
    }


    private fun initializePlayer() {
        player = SimpleExoPlayer.Builder(this).build()

        val dataSourceFactory = DefaultDataSourceFactory(
            this,
            Util.getUserAgent(this, "KaraokeApp")
        )

        val mediaSource = ProgressiveMediaSource.Factory(dataSourceFactory)
            .createMediaSource(Uri.parse("https://directsendwhats.xyz/background_music.mp3"))

        player.setMediaSource(mediaSource)
        player.prepare()
        player.playWhenReady = true
    }

    private fun displayLyrics() {
        scheduleLyricsUpdate()
    }

    private fun scheduleLyricsUpdate() {
        lyricsRunnable = Runnable {
            updateLyrics()
            lyricsHandler.postDelayed(lyricsRunnable, 1000) // جدولة التحديث كل ثانية
        }
        lyricsHandler.post(lyricsRunnable)
    }

    private fun updateLyrics() {
        val currentPosition = player.currentPosition
        // استخدم currentPosition لتحديد الجزء المناسب من كلمات الأغنية
        // وقم بتحديث lyricsTextView بناءً على ذلك
    }




    private fun requestAudioPermissionAndStartRecording() {
        if (ContextCompat.checkSelfPermission(
                this,
                android.Manifest.permission.RECORD_AUDIO
            ) != PackageManager.PERMISSION_GRANTED
        ) {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(android.Manifest.permission.RECORD_AUDIO),
                RECORD_AUDIO_REQUEST_CODE
            )
        } else {
            startRecording()
        }
    }

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<out String>,
        grantResults: IntArray
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == RECORD_AUDIO_REQUEST_CODE) {
            if (grantResults.isNotEmpty() && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                startRecording()
            } else {
                // الإذن مرفوض، يمكنك إظهار رسالة توضيحية هنا
            }
        }
    }

    private fun startRecording() {
        outputFilePath =
            "${getExternalFilesDir(Environment.DIRECTORY_MUSIC)?.absolutePath}/recording.3gp"

        mediaRecorder = MediaRecorder().apply {
            setAudioSource(MediaRecorder.AudioSource.MIC)
            setOutputFormat(MediaRecorder.OutputFormat.THREE_GPP)
            setOutputFile(outputFilePath)
            setAudioEncoder(MediaRecorder.AudioEncoder.AMR_NB)

            try {
                prepare()
            } catch (e: IOException) {
                e.printStackTrace()
            }
            start()
        }
    }

    private fun stopRecording() {
        mediaRecorder?.apply {
            stop()
            release()
        }
        mediaRecorder = null
    }

    override fun onStop() {
        super.onStop()
        lyricsHandler.removeCallbacks(lyricsRunnable)
        releasePlayer()
        mediaRecorder?.apply {
            stop()
            release()
        }
        mediaRecorder = null

        mediaPlayer?.apply {
            stop()
            release()
        }
        mediaPlayer = null
    }


    private fun releasePlayer() {
        if (::player.isInitialized) {
            player.release()
        }
    }

    companion object {
        private const val RECORD_AUDIO_REQUEST_CODE = 200
    }

    private fun playRecording() {
        if (outputFilePath.isNotEmpty()) {
            mediaPlayer = MediaPlayer().apply {
                try {
                    setDataSource(outputFilePath)
                    prepare()
                    start()
                } catch (e: IOException) {
                    e.printStackTrace()
                }
            }
        }
    }
