```
import javax.sound.midi.*;

public class MidiRecorder {

    public static void main(String[] args) throws MidiUnavailableException {

        // get default midi device
        MidiDevice device = MidiSystem.getDefaultMidiDevice();
        device.open();

        // create sequence for recording midi events
        Sequence sequence = new Sequence(Sequence.PPQ, 24);

        // create track for recording
        Track track = sequence.createTrack();

        // create midi event listener for recording
        MidiDeviceReceiver receiver = new MidiDeviceReceiver(device);
        receiver.setTrack(track);

        // create and start midi sequencer for playback
        Sequencer sequencer = MidiSystem.getSequencer();
        sequencer.setSequence(sequence);
        sequencer.open();

        // record midi events from keyboard
        device.getTransmitter().setReceiver(receiver);
        sequencer.recordEnable(track, -1);
        sequencer.startRecording();
        try {
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        sequencer.stopRecording();
        sequencer.recordDisable(track);

        // playback recorded midi events
        sequencer.setTickPosition(0);
        sequencer.start();
        while (sequencer.isRunning()) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        // close resources
        sequencer.stop();
        sequencer.close();
        device.close();
    }
}

class MidiDeviceReceiver implements Receiver {

    private MidiDevice device;
    private Track track;

    public MidiDeviceReceiver(MidiDevice device) {
        this.device = device;
    }

    public void setTrack(Track track) {
        this.track = track;
    }

    public void send(MidiMessage message, long timeStamp) {
        if (track != null) {
            track.add(new MidiEvent(message, timeStamp));
        }
        device.getReceiver().send(message, timeStamp);
    }

    public void close() {
        device.getReceiver().close();
    }
}
```

