    public static void main(String[] args) throws MidiUnavailableException, InterruptedException {

        // get default midi device
        MidiDevice device = MidiSystem.getDefaultMidiDevice();
        device.open();

        // create and open receiver for sending midi events
        Receiver receiver = device.getReceiver();

        // define the jazz harmony laws
        int[] chordIntervals = {3, 7, 10};    // seventh chords
        int[] tensions = {9, 11, 13};         // common chord extensions
        int[] chordTypes = {0, 1, 2, 3, 4, 7}; // chord types (major, minor, dominant, etc.)

        // generate 1000 random key events based on harmony laws
        int note = 60;  // start with middle C
        int velocity = 100;
        for (int i = 0; i < 1000; i++) {
            int[] chord = getRandomJazzChord(note, chordIntervals, tensions, chordTypes);
            int probability = (int) (Math.random() * 10);  // 0 to 9
            if (probability < 7) {   // 70% chance of chord tone
                int chordNote = chord[(int) (Math.random() * chord.length)];
                note = note + chordNote;
            } else {                  // 30% chance of passing note
                int passNote = (int) (Math.random() * 12);
                if (passNote == 3 || passNote == 10) {
                    passNote++;  // avoid minor third or minor seventh intervals
                }
                note = note + passNote;
            }
            if (note < 0) {    // avoid negative note values
                note = note + 12 * (Math.abs(note) / 12 + 1);
            } else if (note > 127) {  // avoid note values above 127
                note = note - 12 * ((note - 127) / 12 + 1);
            }
            // create and send midi event
            ShortMessage noteOn = new ShortMessage();
            try {
                noteOn.setMessage(ShortMessage.NOTE_ON, 0, note, velocity);
                receiver.send(noteOn, -1);
            } catch (InvalidMidiDataException e) {
                e.printStackTrace();
            }
            // random delay before next note
            Thread.sleep((int) (Math.random() * 50));
        }

        // close resources
        receiver.close();
        device.close();
    }

    private static int[] getRandomJazzChord(int note, int[] chordIntervals, int[] tensions, int[] chordTypes) {
        int[] chord = new int[chordIntervals.length + 1];
        int root = (note + 3 * (int) (Math.random() * 12)) % 12;  // choose a root note (randomly within 3 octaves)
        int chordType = chordTypes[(int) (Math.random() * chordTypes.length)];  // choose a chord type
        chord[0] = root;
        for (int i = 0; i < chordIntervals.length; i++) {
            int interval = chordIntervals[i];    // choose a chord interval
            int noteIndex = (root + interval) % 12;
            chord[i + 1] = noteIndex;
        }
        for (int i = 0; i < tensions.length; i++) {  // randomly add tensions to chord
            int probability = (int) (Math.random() * 10); // 0 to 9
            if (probability < 5) {  // 50% chance of adding tension
                int tensionIndex = (root + tensions[i]) % 12;
                for (int j = 0; j < chord.length; j++) {
                    if (tensionIndex == chord[j]) {
                        tensionIndex = (tensionIndex + 1) % 12;  // avoid duplication
                    }
                }
                int randomPos = (int) (Math.random() * (chord.length - 1)) + 1; // choose random position to insert tension
                for (int j = chord.length - 1; j >= randomPos; j--) {
                    chord[j] = chord[j - 1];
                }
                chord[randomPos] = tensionIndex;
            }
        }
        return chord;
    }
}
