template<typename T1 = void, typename T2 = void, typename T3 = void>
class ThreeMemberClass {
public:
    ThreeMemberClass() {}

    template<typename U1>
    ThreeMemberClass(U1 value1) : first(value1) {}

    template<typename U1, typename U2>
