    std::size_t nextPos;
    std::string prevIndex = "0";
    std::string currIndex;

    while ((nextPos = list.find(") ", currPos)) != std::string::npos)
    {
        std::size_t dotPos = list.find('.', currPos, nextPos - currPos);
        currIndex = list.substr(currPos, (dotPos == std::string::npos ? nextPos : dotPos) - currPos);
        while (getNextIndex(prevIndex) != currIndex)
        {
            prevIndex = getNextIndex(prevIndex);
            result += prevIndex + ") -";
            if (prevIndex.find('.') != std::string::npos)
                result += ".";
            result += " ";
