package it.polito.mas.courtreservation
import android.content.Context
import androidx.core.content.ContentProviderCompat.requireContext
import androidx.room.*
import java.util.*


@Database(
    entities = [
        Reservation::class,
        User::class,
        SportPlayground::class]

    , version = 1, exportSchema = false)

abstract class AppDatabase : RoomDatabase() {
    abstract fun reservationDao(): ReservationDao
    abstract fun userDao(): UserDao
    abstract fun sportPlaygroundDao(): SportPlaygroundDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getDatabase(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "reservation_database"
                ).build()
                INSTANCE = instance
                instance
            }
        }
    }

}

To use the `AppDatabase`, you should create a singleton inside the `App` class or in a separate singleton object that handles the database instance. Below is an example of creating a singleton for the `AppDatabase` inside the application class:

```kotlin
import android.app.Application
import it.polito.mas.courtreservation.AppDatabase

class CourtReservationApp : Application() {
    private val database: AppDatabase by lazy {
        AppDatabase.getDatabase(this)
    }

    val reservationDao by lazy { database.reservationDao() }
    val userDao by lazy { database.userDao() }
    val sportPlaygroundDao by lazy { database.sportPlaygroundDao() }

    companion object {
        private var INSTANCE: CourtReservationApp? = null

        fun getAppRepository(context: Context): CourtReservationApp {
            return INSTANCE ?: synchronized(this) {
                val instance = context.applicationContext as CourtReservationApp
                INSTANCE = instance
                instance
            }
        }
    }
}
```

Make sure to update your AndroidManifest.xml to use this Application class:

```xml
<application
    ...
    android:name=".CourtReservationApp">
    ...
</application>
```

To use your `AppDatabase` instance within a fragment or any other class, you should retrieve the Dao objects through the `CourtReservationApp` singleton class like this:

```kotlin
val userDao = CourtReservationApp.getAppRepository(context).userDao
val reservationDao = CourtReservationApp.getAppRepository(context).reservationDao
val sportPlaygroundDao = CourtReservationApp.getAppRepository(context).sportPlaygroundDao
```

