```cpp
#include <iostream>
#include <Windows.h>
#include <sddl.h>
#include <Wtsapi32.h>

int main() {

    HANDLE hProcess = NULL;
    HANDLE hToken = NULL;
    int status = 0;
    hProcess = GetCurrentProcess();
    DWORD dwSize = 0;
    PTOKEN_OWNER tokenOwner = NULL;
    PTOKEN_GROUPS tokenGroups = NULL;
    PTOKEN_PRIVILEGES tokenPrivileges = NULL;
    DWORD sessionId = 0;
    LPSTR tokenOwnerSID = NULL;

    if (!hProcess) {
        printf("[ERROR] Cannot GetCurrentProcess \n");
        status = -1;
        goto CLEANUP;
    }

    if (!OpenProcessToken(hProcess, MAXIMUM_ALLOWED, &hToken)) {
        printf("[ERROR] OpenProcessToken: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    // Obtention et affichage de l'Owner.
    GetTokenInformation(hToken, TokenOwner, NULL, 0, &dwSize);
    tokenOwner = (PTOKEN_OWNER)malloc(dwSize);
    if (!tokenOwner) {
        printf("[ERROR] allocation memory\n");
        status = -1;
        goto CLEANUP;
    }

    if (!GetTokenInformation(hToken, TokenOwner, tokenOwner, dwSize, &dwSize)) {
        printf("[ERROR] GetTokenInformation: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    if (!ConvertSidToStringSidA(tokenOwner->Owner, &tokenOwnerSID)) {
        printf("[ERROR] ConvertSidToStringSidA: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    printf("- Owner: %s\n", tokenOwnerSID);

    // Obtention et affichage des Groupes.
    GetTokenInformation(hToken, TokenGroups, NULL, 0, &dwSize);
    tokenGroups = (PTOKEN_GROUPS)malloc(dwSize);
    if (!tokenGroups) {
        printf("[ERROR] allocation memory\n");
        status = -1;
        goto CLEANUP;
    }

    if (!GetTokenInformation(hToken, TokenGroups, tokenGroups, dwSize, &dwSize)) {
        printf("[ERROR] GetTokenInformation: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    printf("- Groups:\n");
    for (DWORD i = 0; i < tokenGroups->GroupCount; i++) {
        LPSTR groupSID;
        if (ConvertSidToStringSidA(tokenGroups->Groups[i].Sid, &groupSID)) {
            printf("  * %s\n", groupSID);
            LocalFree(groupSID);
        }
    }

    // Obtention et affichage des Privilèges.
    GetTokenInformation(hToken, TokenPrivileges, NULL, 0, &dwSize);
    tokenPrivileges = (PTOKEN_PRIVILEGES)malloc(dwSize);
    if (!tokenPrivileges) {
        printf("[ERROR] allocation memory\n");
        status = -1;
        goto CLEANUP;
    }

    if (!GetTokenInformation(hToken, TokenPrivileges, tokenPrivileges, dwSize, &dwSize)) {
        printf("[ERROR] GetTokenInformation: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    printf("- Privileges:\n");
    for (DWORD i = 0; i < tokenPrivileges->PrivilegeCount; i++) {
        CHAR privilegeName[MAX_PATH];
        DWORD nameSize = MAX_PATH;
        LUID privilegeLUID = tokenPrivileges->Privileges[i].Luid;
        LookupPrivilegeNameA(NULL, &privilegeLUID, privilegeName, &nameSize);
        printf("  * %s\n", privilegeName);
    }

    // Obtention et affichage de SessionID.
    WTSQuerySessionInformation(WTS_CURRENT_SERVER_HANDLE, WTSGetActiveConsoleSessionId(), WTSSessionId, (LPSTR *)&sessionId, &dwSize);
    printf("- Session ID: %d\n", sessionId);

CLEANUP:
    if (hProcess)
        CloseHandle(hProcess);
    if (hToken)
        CloseHandle(hToken);
    if (tokenOwner)
        free(tokenOwner);
    if (tokenGroups)
        free(tokenGroups);
    if (tokenPrivileges)
        free(tokenPrivileges);
    if (tokenOwnerSID)
        LocalFree(tokenOwnerSID);

    return status;
}
