std::string base64_encode(std::string const& s) {
    constexpr char base64_chars[] =
          "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
          "abcdefghijklmnopqrstuvwxyz"
          "0123456789+/";

    std::string result;
    int count = 0;
    int val = 0;
    for (char c : s) {
      val = (val << 8) + static_cast<unsigned char>(c);
      count += 8;
      while (count >= 6) {
        result.push_back(base64_chars[(val >> (count - 6)) & 0x3F]);
        count -= 6;
      }
