    private func updateMoveIndicators() {
        let size = squareSize
        for i in 0 ..< 8 {
            for j in 0 ..< 8 {
                let position = Position(x: j, y: i)
                let view = moveIndicators[i * 8 + j]
                view.frame = frame(x: j, y: i, size: size)
                view.layer.cornerRadius = size.width / 2
