```swift
import SwiftUI

class GameViewModel: ObservableObject {
    @Published var board: Board
    @Published var selection: Position?
    @Published var moves: [Position] = []

    private var gameLogic: GameLogic

    init() {
        board = Board()
        gameLogic = GameLogic(board: board) 
    }

    func boardViewDidTap(_ position: Position) {
        if let selectedPosition = selection {
            if gameLogic.isValidMove(from: selectedPosition, to: position) {
                gameLogic.performMove(from: selectedPosition, to: position)
                board.update() // Aggiorna la board dopo aver eseguito la mossa
                selection = nil
                moves.removeAll()
            } else {
                selection = nil
            }
        } else {
            selection = position
            moves = gameLogic.availableMoves(at: position)
        }
    }
}
```

In questo esempio, ho assunto che `GameLogic` abbia i seguenti metodi:

- `init(board: Board)`: inizializza il gameLogic con la board fornita
- `isValidMove(from: Position, to: Position) -> Bool`: restituisce `true` se la mossa è valida, altrimenti `false`
- `performMove(from: Position, to: Position)`: esegue la mossa sulla board e aggiorna la posizione delle piece
- `availableMoves(at: Position) -> [Position]`: restituisce un array di mosse disponibili per la posizione data 

