```cpp
template <typename ValueType>
void PriorityQueue<ValueType>::enqueue(ValueType value, double priority) {
    enqueueHeap(value, priority);
    count++;
}

template <typename ValueType>
ValueType PriorityQueue<ValueType>::dequeue() {
    ValueType value = dequeueHeap();
    count--;
    return value;
}

template <typename ValueType>
ValueType PriorityQueue<ValueType>::peek() const {
    return heap.front().value;
}

template <typename ValueType>
double PriorityQueue<ValueType>::peekPriority() const {
    return heap.front().priority;
}

template <typename ValueType>
void enqueueHeap(ValueType & value, double priority) {
    HeapEntry entry;
    entry.value = value;
    entry.priority = priority;

    heap.push_back(entry);
    int child = heap.size() - 1;
    int parent = (child - 1) / 2;

    while (child > 0 && takesPriority(child, parent)) {
        swapHeapEntries(child, parent);
        child = parent;
        parent = (child - 1) / 2;
    }
}

template <typename ValueType>
ValueType dequeueHeap(){
    ValueType result = heap.front().value;

    if (heap.size() > 1) {
        swapHeapEntries(0, heap.size() - 1);
    }

    heap.pop_back();

    int parent = 0;
    while (true) {
        int leftChild = 2 * parent + 1;
        int rightChild = leftChild + 1;
        int maxChild = -1;

        if (leftChild < (int)heap.size()) {
            maxChild = rightChild >= (int)heap.size() || takesPriority(leftChild, rightChild) ? leftChild : rightChild;
        }

        if (maxChild >= 0 && takesPriority(maxChild, parent)) {
            swapHeapEntries(maxChild, parent);
            parent = maxChild;
        } else {
            break;
        }
    }

    return result;
}

template <typename ValueType>
bool PriorityQueue<ValueType>::takesPriority(int i1, int i2) {
    return heap[i1].priority < heap[i2].priority;
}

template <typename ValueType>
void PriorityQueue<ValueType>::swapHeapEntries(int i1, int i2) {
    swap(heap[i1], heap[i2]);
}

template <typename ValueType>
std::string PriorityQueue<ValueType>::toString() {
    std::ostringstream oss;

    for (const HeapEntry & entry : heap) {
        oss << "{" << entry.value << ", " << entry.priority << "} ";
    }

    return oss.str();
}

template <typename ValueType>
std::ostream & operator<<(std::ostream & os, const PriorityQueue<ValueType> & pq) {
    return os << pq.toString();
}
