{
    class Program
    {
        private static int magicNumber;

        static void Main(string[] args)
        {
            ResetMagicNumber();
            MainMenu();
        }

        private static void MainMenu()
        {
            while (true)
            {
                Console.Clear();
                Console.WriteLine("Guessing game\n1. Reset magic number\n2. Play\n3. Quit");
                Console.Write("Enter choice: ");
                int choice = Convert.ToInt32(Console.ReadLine());

                switch (choice)
                {
                    case 1:
                        ResetMagicNumber();
                        break;
                    case 2:
                        Play();
                        break;
                    case 3:
                        Console.WriteLine("bye");
                        Environment.Exit(0);
                        break;
                    default:
                        Console.WriteLine("Invalid choice. Please try again.");
                        break;
                }
            }
        }

        private static void ResetMagicNumber()
        {
            Random random = new Random();
            magicNumber = random.Next(1, 11); // 1 to 10
