Here's an implementation of a C++ function that takes a 2D array of integers and converts it to an array of hashmaps with value keys that map to sets of the indexes of the values:

```cpp
#include <iostream>
#include <unordered_map>
#include <unordered_set>
#include <vector>

std::vector<std::unordered_map<int, std::unordered_set<std::pair<int, int>>>> convert2DArrayToHashMaps(int arr[][4], int rows, int cols) {
  std::vector<std::unordered_map<int, std::unordered_set<std::pair<int, int>>>> resultMap;

  for (int i = 0; i < rows; i++) {
    std::unordered_map<int, std::unordered_set<std::pair<int, int>>> map;
    for (int j = 0; j < cols; j++) {
      if (map.find(arr[i][j]) == map.end()) {
        map[arr[i][j]] = std::unordered_set<std::pair<int, int>>{{i, j}};
      } else {
        map[arr[i][j]].insert({i, j});
      }
    }
    resultMap.push_back(map);
  }

  return resultMap;
}

int main() {
  int arr[][4] = {{1, 2, 3, 4},
                  {2, 4, 2, 8},
                  {3, 6, 1, 2}};

  std::vector<std::unordered_map<int, std::unordered_set<std::pair<int, int>>>> result = convert2DArrayToHashMaps(arr, 3, 4);

  for (const auto& row : result) {
    for (const auto& [key, value] : row) {
      std::cout << key << ": ";
      for (const auto& index : value) {
        std::cout << "(" << index.first << ", " << index.second << ") ";
      }
      std::cout << std::endl;
    }
    std::cout << "--------------" << std::endl;
  }

  return 0;
}
```

