#include <vector>

// converts a 2D array into an array of hashmaps
std::vector<std::unordered_map<int, std::vector<int>>> convert_to_hashmaps(const std::vector<std::vector<int>>& arr)
{
    std::vector<std::unordered_map<int, std::vector<int>>> hashmaps;

    // for each array in the 2D array, create a hashmap
    for (const std::vector<int>& sub_arr : arr)
    {
        std::unordered_map<int, std::vector<int>> hashmap;

        // for each value in the array, add it to the hashmap
        for (int i = 0; i < sub_arr.size(); i++)
        {
            const int value = sub_arr[i];
            hashmap[value].push_back(i);
        }

        hashmaps.push_back(hashmap);
    }

    return hashmaps;
}

int main()
{
    const std::vector<std::vector<int>> arr{{1, 2, 5, 3}, {9, 3, 3, 9}};
    const auto hashmaps = convert_to_hashmaps(arr);

    // print each hashmap in the resulting array
    for (const auto& hashmap : hashmaps)
    {
        for (const auto& kvp : hashmap)
        {
            std::cout << kvp.first << ": [";

            const std::vector<int>& indices = kvp.second;
            for (int i = 0; i < indices.size(); i++)
            {
                std::cout << indices[i];
                if (i < indices.size() - 1)
