  let radius = size * (progress % 1);

  push();
  rotate((TWO_PI / spiralCount) * floor(progress));
  translate((size * floor(progress)) / spiralCount, 0);
  let x = (radius + random(-randomMovement, randomMovement)) * cos(angle * (progress % 1));
  let y = (radius + random(-randomMovement, randomMovement)) * sin(angle * (progress % 1));
  fill(0, 0, 255);
  stroke(255, 255, 255, 50);
  strokeWeight(20);
  ellipse(x, y, 10, 10);
  pop();
}

function checkForDrag() {
  const minDist = sizeSlider.value() * spiralSlider.value() / 2;
  if (
    mouseX > sliderArea.x &&
    mouseX < sliderArea.x + sliderArea.width &&
    mouseY > sliderArea.y &&
    mouseY < sliderArea.y + sliderArea.height
  ) {
    dragging = false;
    cursor('default');
  } else if (dist(mouseX, mouseY, shapeCenter.x, shapeCenter.y) < minDist) {
    cursor('grab');
    if (mouseIsPressed) {
      dragging = true;
      cursor('grabbing');
    }
  } else {
    dragging = false;
    cursor('default');
  }
}

function mouseReleased() {
  dragging = false;
  cursor('default');
}

