function draw() {
  background(240);

  // Update shape position when dragging
  if (dragging) {
    shapeCenter.x = mouseX;
    shapeCenter.y = mouseY;
  }

  let sides = sidesSlider.value();
  let size = sizeSlider.value();
  translate(shapeCenter.x, shapeCenter.y);
  strokeWeight(4);
  stroke(50);
  fill(200);
  drawShape(sides, size);

  // Draw and move the blue ball
  stroke(0, 0, 255);
  fill(0, 0, 255);
  drawBall(sides, size, angleOffset);
  angleOffset += 0.007; // Adjust this value to change the smoothness of the ball movement

  checkForDrag();
}

function drawShape(sides, radius) {
  let angle = TWO_PI / sides;
  beginShape();
  for (let i = 0; i < sides; i++) {
    let x = radius * cos(angle * i);
    let y = radius * sin(angle * i);
    vertex(x, y);
  }
  endShape(CLOSE);
}

function drawBall(sides, radius, offset) {
  let angle = TWO_PI / sides;
  let currentOffset = (offset % 1) * sides;
  let prevOffset = ((currentOffset + sides - 1) % sides);
  let nextOffset = ((currentOffset + 1) % sides);

  let prevX = radius * cos(angle * prevOffset);
  let prevY = radius * sin(angle * prevOffset);
  let nextX = radius * cos(angle * nextOffset);
  let nextY = radius * sin(angle * nextOffset);

  let t = offset - floor(offset);
  let x = lerp(prevX, nextX, t);
  let y = lerp(prevY, nextY, t);
  ellipse(x, y, 20, 20);
}

function checkForDrag() {
  const minDist = sizeSlider.value();
  // Check if user is clicking within the shape
  if (dist(mouseX, mouseY, shapeCenter.x, shapeCenter.y) < minDist) {
    cursor('grab');
    if (mouseIsPressed) {
      dragging = true;
      cursor('grabbing');
    }
  } else {
    dragging = false;
    cursor('default');
  }
}

function mouseReleased() {
  dragging = false;
  cursor('default');
}
```

The ball should now move smoothly from one point to the next. The smoothness of the ball movement can be controlled by adjusting the value added to `angleOffset` in the `draw()` function.

