Here `Element` class is used to store the element and its priority. A simple queue implementation is used which retrieves the highest priority element on dequeueing. `enqueue` and `dequeue` functions are provided for inserting elements and extracting out elements (with or without deleting).

Here's an implementation in C++.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

class Element {
public:
    int priority;
    int value;
    Element(int p, int v) : priority(p), value(v) {}
};

class PriorityQueue {
private:
    std::vector<Element> elements;

    int getHighestPriorityIndex() {
        int highestIndex = 0;
        for (int i = 1; i < elements.size(); i++) {
            if (elements[highestIndex].priority < elements[i].priority) {
                highestIndex = i;
            }
        }
        return highestIndex;
    }

public:
    void enqueue(int priority, int value) {
        elements.emplace_back(priority, value);
    }

    Element dequeue(bool remove = true) {
        if (elements.empty()) {
            throw std::runtime_error("Queue is empty");
        }

        int highestIndex = getHighestPriorityIndex();
        Element result = elements[highestIndex];

        if (remove) {
            elements.erase(elements.begin() + highestIndex);
        }
        return result;
    }

    bool isEmpty() {
        return elements.empty();
    }
};

int main() {
    PriorityQueue queue;

    queue.enqueue(1, 10);
    queue.enqueue(3, 30);
    queue.enqueue(2, 20);
    queue.enqueue(4, 40);

    while (!queue.isEmpty()) {
        Element highestPriorityElement = queue.dequeue();
        std::cout << "Priority: " << highestPriorityElement.priority
                  << " , Value: " << highestPriorityElement.value << std::endl;
    }

    return 0;
}
```

This implementation uses the `std::vector` container to store elements and their priorities, and custom functions to manage the addition and removal of elements. The `main()` function demonstrates enqueueing elements, and then dequeueing them while printing out the results.

