const handleCheckboxChange = (event: CheckboxOnChangeEventType, txnId: number) => {
  const isChecked = event.target.checked;
  const currentRow = creditTableLines.filter((x) => x.txnId === txnId)[0];
  const value = isChecked ? currentRow.openBalance : '';

  const creditNeeded = (totalOfChargesTable > totalOfCreditsTable)
    ? Math.abs(totalOfChargesTable - totalOfCreditsTable)
    : 0;

  const linkedPaymentAmount = (creditNeeded <= value) ? creditNeeded.toString() : value.toString();
  onPaymentFieldUpdate(txnId, {
    linkedPaymentAmount: isChecked ? linkedPaymentAmount : '',
    isLinkedPaymentAmount: isChecked,
  });
};
