Here's an example of using emersion/go-imap with OAuth and Office 365 without using go-sasl:

1. Install the required packages:

```sh
go get github.com/emersion/go-imap
go get golang.org/x/oauth2
```

2. Create a file called `main.go` and add the following code:

```go
package main

import (
	"fmt"
	"log"

	"github.com/emersion/go-imap"
	"github.com/emersion/go-imap/client"
	"golang.org/x/oauth2"
)

func main() {
	accessToken, err := getAccessToken() // Replace this function with your own OAuth2 flow
	if err != nil {
		log.Fatalf("Failed to get access token: %v", err)
	}

	serverName := "outlook.office365.com:993"

	tlsConfig := &tls.Config{
		InsecureSkipVerify: false,
		ServerName:         serverName,
	}

	conn, err := tls.Dial("tcp", serverName, tlsConfig)
	if err != nil {
		log.Fatalf("Failed to dial: %v", err)
	}

	client, err := client.New(conn)
	if err != nil {
		log.Fatalf("Failed to create client: %v", err)
	}

	auth := &imap.OAuth2{
		Token:       accessToken,
		AuthHandler: handleAuth,
	}

	if err := client.Auth(auth); err != nil {
		log.Fatal("Error:", err)
	}

	// Connection is now authenticated and can be used to interact with the IMAP server
	// ...
}

func getAccessToken() (string, error) {
	// Replace this dummy token with a real OAuth2 token obtained for Office 365 IMAP access
	return "your-access-token", nil
}

func handleAuth(ir *imap.Resp) (imap.Literal, error) {
	resp := ir.String()

	if resp == "USER" {
		return imap.NewLiteral("your-email@your-domain.com"), nil
	}

	return nil, fmt.Errorf("unexpected server response: %s", resp)
}
```

Note: `getAccessToken()` function should be replaced with your actual OAuth2 flow, such as using the golang.org/x/oauth2 library, to acquire an access token from Office 365.

This example authenticates to the IMAP server with the OAuth access token, which should allow connecting without using go-sasl.

