To get the text around an image, you can use the `Node` and `Element` APIs to traverse through the sibling and parent elements. Here's a function that covers most scenarios:

```javascript
function getTextAroundImage(imgElement) {
  const maxSearchDepth = 3;

  const getText = (element) => {
    let text = '';
    if (element.nodeType === Node.TEXT_NODE) {
      text += element.textContent.trim();
    } else if (element.nodeType === Node.ELEMENT_NODE) {
      text += element.tagName === "IMG" ? "" : element.innerText.trim();
    }
    return text;
  };

  const searchSiblings = (element, depth) => {
    if (!element || depth > maxSearchDepth) {
      return '';
    }
    let text = '';
    text += searchSiblings(element.previousSibling, depth + 1);
    text += ' ' + getText(element);
    text += ' ' + searchSiblings(element.nextSibling, depth + 1);
    return text;
  };

  const searchParents = (element) => {
    if (!element || element.tagName === 'BODY') {
      return '';
    }
    let text = '';
    text += searchSiblings(element.previousSibling, 0);
    text += ' ' + searchParents(element.parentElement);
    text += ' ' + searchSiblings(element.nextSibling, 0);
    return text;
  };

  return searchParents(imgElement);
}

// Usage:
const imgElement = document.querySelector('img'); // or any other way to get the img element
const text = getTextAroundImage(imgElement);
console.log(text);
```

This function will search for text nodes and non-image element siblings of the image element, as well as the siblings of its parent elements up to the specified `maxSearchDepth`. This should cover most cases where text is surrounding an image.

Keep in mind that this is not a perfect solution, and you might need to adjust the `maxSearchDepth` parameter or modify the code based on the actual structure of the web page you're working with.

