    const pillar1Rect = pillar1.getBoundingClientRect();
    const pillarGap1Rect = pillarGap1.getBoundingClientRect();
    const pillar2Rect = pillar2.getBoundingClientRect();
    const pillarGap2Rect = pillarGap2.getBoundingClientRect();

