#include <iostream>

using namespace std;

class Element {
public:
    int priority;
    int value;
};

class queue {
private:
    Element* elements;
    int size = 0;
    int capacity = 10;

    int highestpriority() {
        int highest = 0;
        for (int i = 1; i < size; i++) {
            if (elements[highest].priority < elements[i].priority) {
                highest = i;
            }
        }
        return highest;
    }

public:
    queue() {
        elements = new Element[capacity];
    }

    ~queue() {
        delete[] elements;
    }

    void enqueue(int priority, int value) {
        Element newel;
        newel.priority = priority;
        newel.value = value;
        int buffv, buffp, flag = 0;

        if (size + 1 > capacity) {
            capacity *= 2;
            Element* newElements = new Element[capacity];
            for (int i = 0; i < size; i++) {
                newElements[i] = elements[i];
            }
            delete[] elements;
            elements = newElements;
        }

