JavaScript (script.js):
```javascript
const playButton = document.getElementById("playButton");

playButton.addEventListener("click", () => {
  playRandomRobotSound();
});

function playRandomRobotSound() {
  const context = new AudioContext();

  const oscillator = context.createOscillator();
  const gainNode = context.createGain();
  oscillator.connect(gainNode);
  gainNode.connect(context.destination);

  const frequency = Math.random() * 500 + 200;
  oscillator.frequency.setValueAtTime(frequency, context.currentTime);

  const duration = 2;
  gainNode.gain.setValueAtTime(1, context.currentTime);
  gainNode.gain.exponentialRampToValueAtTime(0.001, context.currentTime + duration);

  oscillator.start();
  oscillator.stop(context.currentTime + duration);
}
```

The JavaScript code above creates a function called `playRandomRobotSound()` that generates a random robot sound using the Web Audio API. The HTML includes a `Play Random Robot Sound` button that, when clicked, triggers the playback of the randomized robot sound for 2 seconds.

OpenSSL库使用C语言编写，提供了一个用于协商SSL/TLS版本的API。以下是一个简单的C语言示例代码，展示如何使用OpenSSL与服务器进行SSL/TLS版本协商。本例中，我们主要关注了协商版本的流程。

为了运行这个示例代码，你需要在你的开发环境中安装OpenSSL库及其相关头文件。请确保在编译时使用适当的OpenSSL库标志，例如：
```
gcc -o ssl_version ssl_version.c -lssl -lcrypto
```

示例代码 `ssl_version.c`:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <openssl/err.h>
#include <openssl/ssl.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <address> <port>\n", argv[0]);
        return 1;
    }

    const char *address = argv[1];
    int port = atoi(argv[2]);

    // Initialize OpenSSL
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();

    // Create a new SSL context with the desired protocol version
    const SSL_METHOD *method = SSLv23_client_method(); // Negotiate highest version supported by client and server
    SSL_CTX *ctx = SSL_CTX_new(method);
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        return 2;
    }

    // Create a TCP/IP socket
    int sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sockfd < 0) {
        perror("socket");
        SSL_CTX_free(ctx);
        return 3;
    }

    // Connect the socket to the remote server
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, address, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        SSL_CTX_free(ctx);
        return 4;
    }

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sockfd);
        SSL_CTX_free(ctx);
        return 5;
    }

    // Create the SSL connection and perform the handshake
    SSL *ssl = SSL_new(ctx);
    if (!ssl) {
        ERR_print_errors_fp(stderr);
        close(sockfd);
        SSL_CTX_free(ctx);
        return 6;
    }

    SSL_set_fd(ssl, sockfd);
    if (SSL_connect(ssl) != 1) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        close(sockfd);
        SSL_CTX_free(ctx);
        return 7;
    }

    // Get the negotiated SSL/TLS version
    printf("Negotiated SSL/TLS version: %s\n", SSL_get_version(ssl));

    // Cleanup
    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(sockfd);
    SSL_CTX_free(ctx);
    ERR_free_strings();

    return 0;
}
```

请注意，此示例代码可能不完整或不适用于生产环境。在实际情况中，您需要确保错误处理充分的以及程序遵循安全的编程实践。此外，您还需要根据您的应用程序的需求添加其他与之相关的逻辑。

