        function stopSequence() {
            clearInterval(interval);
            interval = null;
        }

        // This function creates a simple synthesized drum sound using an oscillator and noise source, and plays it
        function playSynthDrum() {
            const audioContext = new AudioContext();

            // Create an oscillator
            const oscillator = audioContext.createOscillator();
            oscillator.frequency.setValueAtTime(150, audioContext.currentTime);
            oscillator.frequency.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.1);

            // Create a noise source for the 'snare' part of the drum sound
            const noiseSource = audioContext.createBufferSource();
            const noiseBuffer = audioContext.createBuffer(1, audioContext.sampleRate * 0.2, audioContext.sampleRate);
            const noiseBufferData = noiseBuffer.getChannelData(0);
            // Fill the noise buffer with random values to create white noise
            for (let i = 0; i < audioContext.sampleRate * 0.2; i++) {
                noiseBufferData[i] = (Math.random() * 2) - 1;
