class Solution {
    public int solution(int[][] targets) {
        int answer = 0;

        // Sort the targets by starting point (s) and then by the ending point (e) in descending order
        Arrays.sort(targets, new Comparator<int[]>() {
            public int compare(int[] o1, int[] o2) {
                if(o1[0] == o2[0]) {
                    return o2[1] - o1[1];
                }
                return o1[0] - o2[0];
            }
        });

        // Initialize the minEnds array and a variable to keep track of how many interceptor missiles are needed
        int[] minEnds = new int[targets.length];
        int numberOfMissiles = 0;

        for(int[] target : targets) {
            int idx = Arrays.binarySearch(minEnds, 0, numberOfMissiles, target[1]);

            if(idx < 0) {
                idx = -idx - 1;
            }

            minEnds[idx] = target[1];

            if(idx >= numberOfMissiles) {
                numberOfMissiles++;
            }
        }

        return numberOfMissiles;
    }
}

