void printSpiral(int end) {
    int start = 0, i;
    int n = end + 1;
    int a[n][n];

    while (start < end) {
        // Initialize the value to be printed
        int num = start;

        // Traverse right
        for (i = start; i <= end; i++) {
            a[start][i] = num % 10;
            num--;
        }

        // Traverse down
        for (i = start + 1; i <= end; i++) {
            a[i][end] = num % 10;
            num--;
