        for (i = end - 1; i >= start; i--) {
            a[end][i] = num % 10;
            num--;
        }

        // Traverse up
        for (i = end - 1; i > start; i--) {
            a[i][start] = num % 10;
            num--;
        }

        // Update the start and end
        start++;
        end--;
    }

