// Utility function to print the matrix
void printMatrix(int n, int a[][n]) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            printf("%2d ", a[i][j]);
        }
        printf("\n");
    }
}

// Function to create a spiral
void fillSpiral(int n) {
    int a[n][n];
    int value = 9;
    int start = 0, end = n - 1;

    while (start <= end) {
        // Traverse right
        for (int j = start; j <= end; j++) {
            a[start][j] = value;
            value = (value - 1) % 10;
        }

        // Traverse down
        for (int i = start + 1; i <= end; i++) {
            a[i][end] = value;
            value = (value - 1) % 10;
        }

        // Traverse left
        for (int j = end - 1; j >= start; j--) {
            a[end][j] = value;
            value = (value - 1) % 10;
        }

        // Traverse up
        for (int i = end - 1; i > start; i--) {
            a[i][start] = value;
            value = (value - 1) % 10;
        }

        start++;
        end--;
    }

    // Print the spiral
    printMatrix(n, a);
} 

int main() {
    // Create a spiral from 9 to 0
    int n = 10;  
    fillSpiral(n);
    return 0;
}
