    pid_t pid;
    unsigned int freq[128] = {0};
    char *in_file = argv[1];
    char *out_file = argv[2];

    if (pipe(freq_pipe) == -1) {
        fprintf(stderr, "Error: frequency pipe failed\n");
        return 1;
    }
    if (pipe(encode_pipe) == -1) {
        fprintf(stderr, "Error: encoding pipe failed\n");
        return 1;
    }
    if (pipe(decode_pipe) == -1) {
        fprintf(stderr, "Error: decoding pipe failed\n");
        return 1;
    }

    pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Error: fork failed\n");
        return 1;
    } else if (pid == 0) { // child process
        close(freq_pipe[WRITE_END]); // close unused write end
        import_file(fopen(in_file, "r"), freq, freq_pipe); // calculate frequencies and send data to parent process
        close(encode_pipe[READ_END]); // close unused read end
        encode(fopen(in_file, "r"), fdopen(encode_pipe[WRITE_END], "w"), freq); // encode file and send data to parent process
        close(decode_pipe[WRITE_END]); // close unused write end
        decode(fdopen(decode_pipe[READ_END], "r"), fdopen(fopen(out_file, "w"), "w"), freq); // decode file and save to output file
        return 0;
    } else { // parent process
        close(freq_pipe[READ_END]); // close unused read end
        close(encode_pipe[WRITE_END]); // close unused write end
        close(decode_pipe[READ_END]); // close unused read end

