static ssize_t proc_relate_read(struct file *file, char __user * out,size_t size, loff_t * off) {
	struct proc_info *buf = file->private_data;
	struct task_struct *task = &init_task;
	int i;

	// 遍历进程的tasks链表并填充到buf中
	i = 0;
	do {
		buf[i].pid = task->pid;
		strncpy(buf[i].name, task->comm, 16);
		i++;
		if (i >= 30) {
			break;
		}
		task = next_task(task);
	} while (task != &init_task);

	// 将刚刚填充的buf信息拷贝到用户空间
	if (size > i * sizeof(struct proc_info)) {
		size = i * sizeof(struct proc_info);
	}
	if (copy_to_user(out, buf, size)) {
		return -EFAULT;
	}
	return size;
}
