```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;

public class Admin {
    private static final String ADMIN_FILENAME = "admin.txt";
    private static final String PLAYERS_FILENAME = "players.bin";

    private String adminPassword;
    private ArrayList<Player> players;

    public Admin() {
        players = new ArrayList<>();
        loadAdminPassword();
        loadPlayers();
    }

    private void loadAdminPassword() {
        try {
            adminPassword = Files.readAllLines(Paths.get(ADMIN_FILENAME)).get(0).trim();
        } catch (IOException ex) {
            System.out.println("Failed to load admin password");
        }
    }

    private void loadPlayers() {
        try {
            FileInputStream fis = new FileInputStream(PLAYERS_FILENAME);
            ObjectInputStream ois = new ObjectInputStream(fis);
            players = (ArrayList<Player>) ois.readObject();
            ois.close();
            fis.close();
        } catch (FileNotFoundException ex) {
            System.out.println("No players file found, creating a new one...");
            savePlayers();
        } catch (IOException | ClassNotFoundException ex) {
            System.out.println("Failed to load players.");
            ex.printStackTrace();
        }
    }

    private void savePlayers() {
        try {
            FileOutputStream fos = new FileOutputStream(PLAYERS_FILENAME);
            ObjectOutputStream oos = new ObjectOutputStream(fos);
            oos.writeObject(players);
            oos.close();
            fos.close();
        } catch (IOException ex) {
            System.out.println("Failed to save players.");
            ex.printStackTrace();
        }
    }

    private void displayPlayers() {
        int index = 1;
        for (Player player : players) {
            System.out.print("[" + (index++) + "] ");
            player.display();
        }
    }

    private void createNewPlayer() {
        String loginName = Keyboard.readString("Enter player login name > ");
        String password = Keyboard.readString("Enter player password > ");
        int chips = Keyboard.readInt("Enter player chips > ");
        Player player = new Player(loginName, password, chips);

        players.add(player);
        savePlayers();
    }

    private void deletePlayer() {
        int playerIndex = Keyboard.readInt("Enter player index to delete > ");
        if (playerIndex > 0 && playerIndex <= players.size()) {
            players.remove(playerIndex - 1);
            savePlayers();
        } else {
            System.out.println("Invalid player index.");
        }
    }

    private void issueMoreChips() {
        int playerIndex = Keyboard.readInt("Enter player index to issue more chips > ");
        if (playerIndex > 0 && playerIndex <= players.size()) {
            int chips = Keyboard.readInt("Enter number of chips to issue > ");
            players.get(playerIndex - 1).addChips(chips);
            savePlayers();
        } else {
            System.out.println("Invalid player index.");
        }
    }

    private void resetPlayerPassword() {
        int playerIndex = Keyboard.readInt("Enter player index to reset password > ");
        if (playerIndex > 0 && playerIndex <= players.size()) {
            String newPassword = Keyboard.readString("Enter new password for player > ");
            players.get(playerIndex - 1).setPassword(newPassword);
            savePlayers();
        } else {
            System.out.println("Invalid player index.");
        }
    }

    private void changeAdminPassword() {
        String oldPassword = Keyboard.readString("Enter old admin password > ");
        if (Utility.getHash(oldPassword).equals(adminPassword)) {
            String newPassword = Keyboard.readString("Enter new admin password > ");
            adminPassword = Utility.getHash(newPassword);
            try {
                Files.write(Paths.get(ADMIN_FILENAME), adminPassword.getBytes());
            } catch (IOException ex) {
                System.out.println("Failed to save new admin password");
                ex.printStackTrace();
            }
        } else {
            System.out.println("Incorrect old password.");
        }
    }

    public void run() {
        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.println("\n--- ADMINISTRATION MENU ---");
            System.out.println("1. Create player");
            System.out.println("2. Delete player");
            System.out.println("3. View all players");
            System.out.println("4. Issue more chips to player");
            System.out.println("5. Reset player's password");
            System.out.println("6. Change administrator's password");
            System.out.println("7. Logout");

            int choice = Keyboard.readInt("Enter choice > ");

            switch (choice) {
                case 1:
                    createNewPlayer();
                    break;
                case 2:
                    displayPlayers();
                    deletePlayer();
                    break;
                case 3:
                    displayPlayers();
                    break;
                case 4:
                    displayPlayers();
                    issueMoreChips();
                    break;
                case 5:
                    displayPlayers();
                    resetPlayerPassword();
                    break;
                case 6:
                    changeAdminPassword();
                    break;
                case 7:
                    System.out.println("Logging out...");
                    return;
                default:
                    System.out.println("Invalid choice. Please try again.");
            }
        }
    }

    public static void main(String[] args) {
        Admin admin = new Admin();
        admin.run();
    }
}
