To achieve your desired functionality, you can add a function called `checkAndClearMatches()` that will search for matches of 4 or more same-colored rectangles in a row or column and set the background color of those rectangles to white.

Add the following function to your `<script>` section:

```javascript
function checkAndClearMatches() {
  const rectangles = document.getElementsByClassName('rectangle');
  const matches = [];

  // Check rows for matches
  for (let row = 0; row < boardHeight; row++) {
    let matchCount = 1;
    for (let col = 1; col < boardWidth; col++) {
      const currentIndex = row * boardWidth + col;
      const prevIndex = row * boardWidth + col - 1;
      const currentColor = rectangles[currentIndex].style.backgroundColor;
      const prevColor = rectangles[prevIndex].style.backgroundColor;

      if (currentColor !== '' && currentColor === prevColor) {
        matchCount++;
      } else {
        if (matchCount >= 4) {
          for (let i = 0; i < matchCount; i++) {
            matches.push(row * boardWidth + col - 1 - i);
          }
        }
        matchCount = 1;
      }
    }
    if (matchCount >= 4) {
      for (let i = 0; i < matchCount; i++) {
        matches.push(row * boardWidth + boardWidth - 1 - i);
      }
    }
  }

  // Check columns for matches
  for (let col = 0; col < boardWidth; col++) {
    let matchCount = 1;
    for (let row = 1; row < boardHeight; row++) {
      const currentIndex = row * boardWidth + col;
      const prevIndex = (row - 1) * boardWidth + col;
      const currentColor = rectangles[currentIndex].style.backgroundColor;
      const prevColor = rectangles[prevIndex].style.backgroundColor;

      if (currentColor !== '' && currentColor === prevColor) {
        matchCount++;
      } else {
        if (matchCount >= 4) {
          for (let i = 0; i < matchCount; i++) {
            matches.push((row - 1) * boardWidth + col - i * boardWidth);
          }
        }
        matchCount = 1;
      }
    }
    if (matchCount >= 4) {
      for (let i = 0; i < matchCount; i++) {
        matches.push((boardHeight - 1) * boardWidth + col - i * boardWidth);
      }
    }
  }

  // Set background color of matched rectangles to white
  for (const index of matches) {
    rectangles[index].style.backgroundColor = 'white';
  }
}
```

