/* Utility macros */
#define MARK(room)		( SET_BIT( (room)->room_flags_3, BFS_MARK ) )
#define UNMARK(room)	( REMOVE_BIT( (room)->room_flags_3, BFS_MARK ) )
#define IS_MARKED(room)	( IS_SET( (room)->room_flags_3, BFS_MARK ) )

#define BFS_ERROR			-1
#define BFS_ALREADY_THERE	-2
#define BFS_NO_PATH			-3

bool valid_edge( EXIT_DATA *pexit )
{
	if( pexit->to_room && !IS_MARKED( pexit->to_room ) )
		return TRUE;
	else
		return FALSE;
}

void bfs_enqueue( ROOM_INDEX_DATA * room, char dir )
{
	BFS_DATA *curr;

	curr = ( BFS_DATA * ) malloc( sizeof( BFS_DATA ) );
	curr->room = room;
	curr->dir = dir;
	curr->next = NULL;

	if( queue_tail )
	{
		queue_tail->next = curr;
		queue_tail = curr;
	}
	else
		queue_head = queue_tail = curr;
}

void bfs_dequeue( void )
{
	BFS_DATA *curr;

	curr = queue_head;
	if( !( queue_head = queue_head->next ) )
		queue_tail = NULL;
	free( curr );
}


