{
	BFS_DATA *curr;

	curr = ( BFS_DATA * ) malloc( sizeof( BFS_DATA ) );
	curr->room = room;
	curr->next = room_queue;

	room_queue = curr;
}

void clean_room_queue( void )
{
	BFS_DATA *curr, *curr_next;

	for( curr = room_queue; curr; curr = curr_next )
