Sure! Here's the implementation for the `is_visited`, `mark_visited`, and `clear_visited` functions using a linked list to store the visited room `vnum`s:

```c
typedef struct bfs_visited_struct BFS_VISITED;
struct bfs_visited_struct
{
    int vnum;
    BFS_VISITED *next;
};

static BFS_VISITED *visited_head = NULL;

bool is_visited(int vnum)
{
    BFS_VISITED *curr;

    for (curr = visited_head; curr != NULL; curr = curr->next)
    {
        if (curr->vnum == vnum)
            return TRUE;
    }

    return FALSE;
}

void mark_visited(int vnum)
{
    BFS_VISITED *new_visited;

    if (!is_visited(vnum))
    {
        new_visited = (BFS_VISITED *)malloc(sizeof(BFS_VISITED));
        new_visited->vnum = vnum;
        new_visited->next = visited_head;
        visited_head = new_visited;
    }
}

void clear_visited()
{
    BFS_VISITED *curr, *next;

    for (curr = visited_head; curr != NULL; curr = next)
    {
        next = curr->next;
        free(curr);
    }
    visited_head = NULL;
}
```

With these functions, you can track if a room `vnum` is visited, mark a room `vnum` as visited, and clear the visited list.

