```javascript
function addRowToTop() {
  const gameBoard = document.getElementById("game-board");
  const newDivRow = document.createElement("div");
  newDivRow.classList.add("row");

  // Shift all rows down by 1
  for (let row = boardHeight - 1; row >= 0; row--) {
    for (let col = 0; col < boardWidth; col++) {
      const index = row * boardWidth + col;
      const rectangle = gameBoard.getElementsByClassName("rectangle")[index];

      if (row < boardHeight - 1) {
        const bottomIndex = (row + 1) * boardWidth + col;
        const bottomRectangle = gameBoard.getElementsByClassName("rectangle")[bottomIndex];
        rectangle.style.backgroundColor = bottomRectangle.style.backgroundColor;
      } else {
        rectangle.style.backgroundColor = "";
      }
    }
  }

  // Fill the last row (now the first row) with colored rectangles
  for (let col = 0; col < boardWidth; col++) {
