}
```

3. Create message classes (SampleMessage.cs):

```csharp
namespace SagaExample.Messages
{
    public interface SampleMessage
    {
        Guid Id { get; }
        string Content { get; }
    }
}
```

4. Create a Saga state machine (SampleStateMachine.cs):

```csharp
using System;
using Automatonymous;
using SagaExample.Messages;

namespace SagaExample.StateMachines
{
    public class SampleStateMachine : MassTransitStateMachine<SampleState>
    {
        public SampleStateMachine()
        {
            Event(() => SampleMessageReceived, x => x.CorrelateById(m => m.Message.Id));

            InstanceState(x => x.CurrentState);

            Initially(
                When(SampleMessageReceived)
                    .Then(context =>
                    {
                        context.Instance.ReceivedDateTime = DateTime.UtcNow;
                    })
                    .TransitionTo(Active));

            During(Active,
                When(SampleMessageReceived)
                    .Then(context =>
                    {
                        context.Instance.ReceivedDateTime = DateTime.UtcNow;
                    }));

            SetCompletedWhenFinalized();
        }

        public State Active { get; private set; }

        public Event<SampleMessage> SampleMessageReceived { get; private set; }
    }
}
```

5. Create a Saga state (SampleState.cs):

```csharp
using System;
using Automatonymous;

namespace SagaExample.StateMachines
{
    public class SampleState : SagaStateMachineInstance
    {
        public Guid CorrelationId { get; set; }
        public string CurrentState { get; set; }
        public DateTime? ReceivedDateTime { get; set; }
    }
}
```

