  console.log('New client connected');

  // Send latest flight information to client on connection
  connection.query(query, (error, results) => {
    if (error) throw error;
    socket.emit('flightData', results);
  });

  // Send updated flight information to client when database changes
  connection.on('change', () => {
    connection.query(query, (error, results) => {
      if (error) throw error;
      socket.emit('flightData', results);
    });
  });
});

// Set up route to render flight information using EJS template
