function createDynamicForm() {
  const container = document.getElementById("form-container");

  const form = document.createElement("form");
  form.setAttribute("class", "form");
  form.setAttribute("style", "display: flex; flex-direction: column;");

  config.forEach((field) => {
    let elementDiv;
    switch (field.type) {
      case "text":
      case "number":
        elementDiv = createInputDiv(field.id, field.type, field.labelText, field.value);
        break;
      case "select":
        elementDiv = createSelectDiv(field.id, field.labelText, field.options);
        break;
      case "checkbox":
        elementDiv = createInputDiv(field.id, field.type, field.labelText, field.value, field.checked);
        break;
      default:
        break;
    }
    form.appendChild(elementDiv);
  });

  container.appendChild(form);
}

function createInputDiv(id, type, labelText, value, checked) {
  const div = document.createElement("div");

  const inputLabel = document.createElement("label");
  inputLabel.setAttribute("for", id);
  inputLabel.innerText = labelText;
  div.appendChild(inputLabel);

  const input = document.createElement("input");
  input.setAttribute("type", type);
  input.setAttribute("name", id);
  input.setAttribute("id", id);
  input.setAttribute("value", value);
  if (checked) {
    input.setAttribute("checked", true);
  }
  div.appendChild(input);

  return div;
}

function createSelectDiv(id, labelText, options) {
  const div = document.createElement("div");

  const selectLabel = document.createElement("label");
  selectLabel.setAttribute("for", id);
  selectLabel.innerText = labelText;
  div.appendChild(selectLabel);

  const select = document.createElement("select");
  select.setAttribute("name", id);
  select.setAttribute("id", id);

  options.forEach((option) => {
    const opt = document.createElement("option");
    opt.setAttribute("value", option.value);
    opt.innerText = option.text;
    select.appendChild(opt);
  });

  div.appendChild(select);

  return div;
}
