In the latest version of Niagara, the process for listening to particle collision or death events via a custom gameplay ability in GAS is quite similar. However, OnParticleCollide and OnParticleDeath events have been deprecated. Instead, you'll need to use a Niagara System instance and its associated Niagara Data Interface (NDI) for collision or death events. Follow these steps:

1. First, create a custom subclass of UGameplayAbility (e.g., UMyNiagaraCollisionAbility).

2. In your custom ability class, override the ActivateAbility function. In this function, you'll want to spawn a Niagara System instance and keep a reference to its associated Niagara Data Interface.

Here's an example of how you might implement the ActivateAbility function:

```cpp
void UMyNiagaraCollisionAbility::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo *ActorInfo, const FGameplayTagContainer *SourceTags, const FGameplayEventData *EventData)
{
    Super::ActivateAbility(Handle, ActorInfo, SourceTags, EventData);

    // Get the owning character
    ACharacter *Character = Cast<ACharacter>(GetAvatarActorFromActorInfo());

    if (Character)
    {
        // Spawn the Niagara System at the character's location
        UNiagaraSystem* NiagaraSystem = LoadObject<UNiagaraSystem>(NULL, TEXT("NiagaraSystem'/Game/Path/To/ParticleSystem.ParticleSystem'"));
        FTransform SpawnTransform = Character->GetActorTransform();
        UNiagaraComponent* NiagaraComponent = UNiagaraFunctionLibrary::SpawnSystemAtLocation(Character->GetWorld(), NiagaraSystem, SpawnTransform);

        if (NiagaraComponent)
        {
            // Get the Data Interface from the Niagara system
            FNiagaraDataInterfaceProxy* DataInterfaceProxy = NiagaraComponent->GetDataInterfaceProxy(TEXT("PathToNDI"));
            if (DataInterfaceProxy)
            {
                // Handle collision events: You'll need to create a custom FNiagaraDataInterfaceProxyCollision class and cast it.
                UMyNiagaraDataInterfaceProxyCollision* CollisionDI = Cast<UMyNiagaraDataInterfaceProxyCollision>(DataInterfaceProxy);

                if (CollisionDI)
                {
                    CollisionDI->CollisionEvent.BindUFunction(this, "OnNiagaraCollision");
                }

                // Handle death events: You'll need to create a custom FNiagaraDataInterfaceProxyDeath class and cast it.
                UMyNiagaraDataInterfaceProxyDeath* DeathDI = Cast<UMyNiagaraDataInterfaceProxyDeath>(DataInterfaceProxy);

                if (DeathDI)
                {
                    DeathDI->DeathEvent.BindUFunction(this, "OnNiagaraDeath");
                }
            }
        }
    }
}
```

