To replicate Niagara particles to all clients from the server, you can follow these steps:

1. Spawn the Niagara component on the server when needed, such as during ability activation, and make sure it's set to replicate.

```cpp
void UMyReplicatedNiagaraAbility::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo *ActorInfo, const FGameplayTagContainer *SourceTags, const FGameplayEventData *EventData)
{
    Super::ActivateAbility(Handle, ActorInfo, SourceTags, EventData);

    // Get the owning character for the ability
    ACharacter *Character = Cast<ACharacter>(GetAvatarActorFromActorInfo());
    if (Character && Character->HasAuthority())  // Only spawn on the server
    {
        UNiagaraSystem* NiagaraSystem = LoadObject<UNiagaraSystem>(NULL, TEXT("NiagaraSystem'/Game/Path/To/ParticleSystem.ParticleSystem'"));

        // Spawn position, rotation and scale as needed
        FTransform SpawnTransform = Character->GetActorTransform();

        // Spawn the Niagara System at the character's location
        UNiagaraComponent* NiagaraComponent = UNiagaraFunctionLibrary::SpawnSystemAtLocation(Character->GetWorld(), NiagaraSystem, SpawnTransform);

        // Set NiagaraComponent to replicate
        NiagaraComponent->SetIsReplicated(true);
        NiagaraComponent->SetNetAddressable();
        NiagaraComponent->SetOnlyOwnerSee(false);

        // Attach the Niagara Component to the character or desired component
        NiagaraComponent->AttachToComponent(Character->GetRootComponent(), FAttachmentTransformRules::KeepWorldTransform);
    }
}
```

