#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "ADT_binary_search_tree.h"

// Helper function to generate a random integer between min and max
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Shuffle function to randomize the order of `packet_seq`
void shuffle(TipoItem *packet_seq, int len) {
    for (int i = 0; i < len; i++) {
        int random_idx = random_int(i, len - 1);
        TipoItem temp = packet_seq[i];
        packet_seq[i] = packet_seq[random_idx];
        packet_seq[random_idx] = temp;
    }
}

int main() {
    char original_message[100];
    TipoCelula *tree;
    TipoItem packet_seq[1000];
    int total_packets = 0;

    // Seed random number generator
    srand(time(0));

