    for (int i = 0; original_message[i] != '\n' && original_message[i] != '\0'; i++) {
        // 4 - generate a random int between 1 and 10 to determine the replication count
        int replication_count = random_int(1, 10);

        // Add packets to packet_seq
        for (int j = 0; j < replication_count; j++) {
            packet_seq[total_packets].chave = i;
            packet_seq[total_packets].pacote = original_message[i];
            total_packets++;
        }
    }

    // 5 - generate a new sequence of packets with both original and replicated packets scrambled
    shuffle(packet_seq, total_packets);

