                int numPizza = Integer.parseInt(NumPizza.getText());
                double toppingPrice = getPriceFromChoice((String) ChoixTopping.getSelectedItem());
                int numTopping = Integer.parseInt(NumTopping.getText());
                double breuvagePrice = getBreuvagePriceFromChoice((String) ChoixBreuvage.getSelectedItem());
                int numBreuvage = Integer.parseInt(NumBreuvage.getText());

                totalPrice += (pizzaPrice * numPizza) + (toppingPrice * numTopping) + (breuvagePrice * numBreuvage);
            }
