```cpp
#include <ArduinoMqttClient.h>
#include <WiFiNINA.h>
#include <DallasTemperature.h>

#define ONE_WIRE_BUS A5
#define FIRST_P_Pin  10
#define SECOND_P     12
#define STARTER_Pin  11
#define IMMO         9
#define K5           8
#define Lock_Pin     6
#define Unlock_Pin   7
#define LED_Pin      13
#define STOP_Pin     A0
#define PSO_Pin      A1
#define PSO_F        A2
#define RESET_Pin    A3
#define BAT_Pin      A7
#define Feedback_Pin A6

OneWire oneWire(ONE_WIRE_BUS);
DallasTemperature sensors(&oneWire);

const char MQTT_user[10] = "drive2ru";
const char MQTT_pass[15] = "martinhool221";
const char MQTT_type[15] = "MQIsdp";
const char MQTT_CID[15] = "CITROEN";
const char* ssid = "your_wifi_ssid";
const char* pass = "your_wifi_pass";

// Replace with your own MQTT broker and port
const char* MQTT_SERVER = "m54.cloudmqtt.com";
int PORT = 10077;

float Vstart = 13.20;
String pin = "";
float TempDS[11];
float Vbat, V_min;
float m = 68.01;
unsigned long Time1, Time2 = 0;
int Timer, inDS, count, error_CF, error_C;
int interval = 4;
bool heating = false;
bool ring = false;
bool broker = false;
bool Security = false;

int status = WL_IDLE_STATUS;

WiFiClient net;
MqttClient mqtt(net);

void setup() {
    pinMode(FIRST_P_Pin, OUTPUT);
    pinMode(SECOND_P, OUTPUT);
    pinMode(STARTER_Pin, OUTPUT);
    pinMode(Lock_Pin, OUTPUT);
    pinMode(Unlock_Pin, OUTPUT);
    pinMode(LED_Pin, OUTPUT);
    pinMode(IMMO, OUTPUT);
    pinMode(K5, OUTPUT);

    pinMode(3, INPUT_PULLUP);
    pinMode(2, INPUT_PULLUP);

    delay(100);
    Serial.begin(9600);

    while (status != WL_CONNECTED) {
        Serial.print("Attempting to connect to WiFi SSID: ");
        Serial.println(ssid);
        status = WiFi.begin(ssid, pass);
        delay(10000);
    }

    Serial.print("Connected to: ");
    Serial.print(ssid);
    Serial.print(" with IP address: ");
    Serial.println(WiFi.localIP());

    mqtt.setId(MQTT_CID);
    mqtt.setHost(MQTT_SERVER, PORT);
    mqtt.setUserPassword(MQTT_user, MQTT_pass);

    connectMqtt();
}

void loop() {
    if (!mqtt.connected()) {
        connectMqtt();
    }
    mqtt.poll();

    if (millis() > Time2 + 60000) {
        Time2 = millis();
        if (Timer > 0) {
            Timer--;
            Serial.print("Тм:");
            Serial.println(Timer);
        }
    }

    if (millis() > Time1 + 10000) {
        Time1 = millis();
        detection();
    }
    if (heating == true && digitalRead(STOP_Pin) == 1) {
        heatingstop();
    }
}

void onMqttMessage(int messageSize) {
    String topic = mqtt.lastReadTopic();
    String message;
    for (int i = 0; i < messageSize; i++) {
        message += (char)mqtt.read();
    }

    // Handle received MQTT messages here
    // For example:
    if (topic == "C5/comandstart") {
        enginestart();
    }
}

void connectMqtt() {
    Serial.print("Connecting to MQTT broker...");
    while (!mqtt.connect()) {
        Serial.print(".");
        delay(1000);
    }
    Serial.println("");

    mqtt.onMessage(onMqttMessage);
    mqtt.subscribe("C5/comand");
    mqtt.subscribe("C5/settimer");

    mqtt.beginMessage("C5/status");
    mqtt.print("Подключено");
    mqtt.endMessage();
}

void enginestart() {
    Serial.println("E-start");
    Timer = 5;
    digitalWrite(IMMO, HIGH);
    delay(100);
    if (analogRead(Feedback_Pin) < 30) {
        int StTime = map(TempDS[0], 20, -15, 700, 5000);

        StTime = constrain(StTime, 700, 6000);
        Serial.println("Еgnition. ON");
        digitalWrite(FIRST_P_Pin, HIGH);
        delay(1000);
        digitalWrite(SECOND_P, HIGH);
        delay(4000);

        if (TempDS[0] < -20) {
            digitalWrite(SECOND_P, LOW);
            delay(2000);
            digitalWrite(SECOND_P, HIGH);
            delay(8000);
        }

        if (digitalRead(STOP_Pin) == LOW) {
            Serial.println("ST. ON");
            digitalWrite(STARTER_Pin, HIGH);
            delay(StTime);
            digitalWrite(STARTER_Pin, LOW);
            Serial.println("ST. OFF");
            delay(6000);
        }
    }
    if (VoltRead() > Vstart) {
        Serial.println("VBAT OK");
        heating = true;
    } else {
        heatingstop();
    }

    Serial.println("OUT");
    interval = 1;
}

float VoltRead() {
    float ADCC = analogRead(BAT_Pin);
    ADCC = ADCC / m;
    Serial.print("АКБ: ");
    Serial.print(ADCC);
    Serial.println("V");
    if (ADCC < V_min) {
        V_min = ADCC;
    }
    return (ADCC);
}

void heatingstop() {
    digitalWrite(SECOND_P, LOW);
    delay(100);
    digitalWrite(FIRST_P_Pin, LOW);
    delay(100);
    digitalWrite(IMMO, LOW);
    delay(100);
    digitalWrite(K5, LOW);
    digitalWrite(13, LOW);
    heating = false;
    Timer = 0;
    Serial.println("All OFF");
}

void detection() {
    Vbat = VoltRead();
    Serial.print("Инт:");
    Serial.println(interval);
    inDS = 0;
    sensors.requestTemperatures();
    while (inDS < 10) {
        TempDS[inDS] = sensors.getTempCByIndex(inDS);
        if (TempDS[inDS] == -127.00) {
            TempDS[inDS] = 80;
            break;
        }
        inDS++;
    }

    for (int i = 0; i < inDS; i++) {
        Serial.print("Temp");
        Serial.print(i);
        Serial.print("= ");
        Serial.println(TempDS[i]);
    }
    Serial.println("");

    if (heating == true && Timer < 1) {
        heatingstop();
    }

    interval--;
    if (interval < 1) {
        interval = 6; // Poll timer
    }
}

void blocking(bool st) {
    digitalWrite(st ? Lock_Pin : Unlock_Pin, HIGH);
    delay(500);
    digitalWrite(st ? Lock_Pin : Unlock_Pin, LOW);
    Security = st;
    Serial.println(st ? "На охране" : "Открыто");
}
