            // Calculate the enemy's movement using similar logic to the player
            let dx = CGFloat.random(in: -tileSize...tileSize)
            let dy = CGFloat.random(in: -tileSize...tileSize)

            let destination = CGPoint(
                x: enemy.position.x + dx,
                y: enemy.position.y + dy
            )

