        // Calculate the horizontal and vertical distances relative to the enemy's current position
        let dx = destination.x - enemy.position.x
        let dy = destination.y - enemy.position.y
        let horizontalDistance = abs(dx)
        let verticalDistance = abs(dy)

        // Calculate the duration of the movement action based on the enemy's speed
        let distance = sqrt(dx*dx) + sqrt(dy*dy)
        let duration = TimeInterval(distance / enemySpeed)

        // Create separate actions for horizontal and vertical movement
        var actions: [SKAction] = []
        if horizontalDistance > 0 {
