  for (let i = 0; i < OBSTACLE_COUNT; i++) {
    const obstacleWidth = 100;
    const obstacleHeight = 10;
    const obstacleX = Math.random() * (canvas.width - obstacleWidth);
    const obstacleY = Math.random() * (canvas.height - obstacleHeight);

    obstacles.push({ x: obstacleX, y: obstacleY, width: obstacleWidth, height: obstacleHeight });
  }
}

function checkEnemyDeath() {
  if (
    isPlayerAlive &&
    playerSpeedY >= 0 &&
    playerY + PLAYER_RADIUS * 2 > enemyY - ENEMY_RADIUS &&
    playerX + PLAYER_RADIUS * 2 > enemyX - ENEMY_RADIUS &&
    playerX < enemyX + ENEMY_RADIUS
  ) {
    playerSpeedY = -20;
    playerIsOnGround = false;
    enemyY = -100;
    enemyX = -100;
    setTimeout(spawnNewEnemy, 1000);
    enemyMultiplier++;
  }
}

function spawnNewEnemy() {
  enemyX = Math.random() * (canvas.width - ENEMY_RADIUS * 2);
  enemyY = Math.random() * (canvas.height - ENEMY_RADIUS * 2);

  for (let i = 0; i < enemyMultiplier - 1; i++) {
    shootLaser();
  }
}

function draw() {
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "black";
  context.fillRect(0, 0, canvas.width, canvas.height);

  applyGravity();
  applyTraction();
  movePlayer();
  moveEnemy();
  moveLasers();
  checkCollision();
  drawLasers();
  drawObstacles();
  checkEnemyDeath();
  requestAnimationFrame(draw);
}

createObstacles();
draw();

document.addEventListener("keydown", (event) => {
  if (event.code === "KeyA") {
    playerSpeedX = -5;
  }
  if (event.code === "KeyD") {
    playerSpeedX = 5;
  }
  if (event.code === "KeyW" && playerIsOnGround) {
    playerSpeedY = -20;
    playerIsOnGround = false;
  }
});

document.addEventListener("keyup", (event) => {
  if (event.code === "KeyA" || event.code === "KeyD") {
    playerSpeedX = 0;
  }
});
