type CaseDetails struct {
	CaseID          string `json:"case_id"`
	CaseName        string `json:"case_name"`
	CaseType        string `json:"case_type"`
	CaseDescription string `json:"case_description"`
	CaseStatus      string `json:"case_status"`
	CaseDate        string `json:"case_date"`
	CaseTime        string `json:"case_time"`
	CaseLocation    string `json:"case_location"`
	CaseIPFSHash    string `json:"case_ipfs_hash"`
}

type CaseChaincode struct {
}

func (t *CaseChaincode) Init(stub shim.ChaincodeStubInterface) peer.Response {
	return shim.Success(nil)
}

func (t *CaseChaincode) Invoke(stub shim.ChaincodeStubInterface) peer.Response {
	function, args := stub.GetFunctionAndParameters()

	if function == "addCase" {
		return t.addCase(stub, args)
	} else if function == "queryCase" {
		return t.queryCase(stub, args)
	} else if function == "queryCasesByParams" {
		return t.queryCasesByParams(stub, args)
	}

