#include <iostream>
#include <vector>

using namespace std;

const int BOARD_SIZE = 8;

enum PieceType { EMPTY, PAWN, ROOK, KNIGHT, BISHOP, QUEEN, KING };
enum PieceColor { NONE, WHITE, BLACK };

struct Piece {
    PieceType type;
    PieceColor color;
};

typedef vector<vector<Piece>> Board;

void print_board(const Board& board);
bool is_valid_move(const Board& board, int src_x, int src_y, int dest_x, int dest_y);
bool move_piece(Board& board, int src_x, int src_y, int dest_x, int dest_y);
