            move_piece(board, src_x, src_y, dest_x, dest_y);
        }
        else {
            cout << "Invalid move! Please try again." << endl;
        }
    }

    return 0;
}

void print_board(const Board& board) {
    for (int i = 0; i < BOARD_SIZE; ++i) {
        for (int j = 0; j < BOARD_SIZE; ++j) {
            // You can customize the appearance of different pieces here.
            // For simplicity, I am using P, R, N, B, Q, and K for white pieces.
            // For black pieces, I'm using the same letters in lower case.
            char piece_char = '.';
            switch (board[i][j].type) {
            case PAWN:
                piece_char = board[i][j].color == WHITE ? 'P' : 'p';
                break;
            case ROOK:
                piece_char = board[i][j].color == WHITE ? 'R' : 'r';
                break;
            case KNIGHT:
                piece_char = board[i][j].color == WHITE ? 'N' : 'n';
                break;
            case BISHOP:
                piece_char = board[i][j].color == WHITE ? 'B' : 'b';
                break;
            case QUEEN:
                piece_char = board[i][j].color == WHITE ? 'Q' : 'q';
                break;
            case KING:
                piece_char = board[i][j].color == WHITE ? 'K' : 'k';
                break;
            default:
                break;
            }
            cout << piece_char << ' ';
        }
        cout << endl;
    }
}

bool is_valid_move(const Board& board, int src_x, int src_y, int dest_x, int dest_y) {
    // Check if coordinates are within the board
    if (src_x < 0 || src_x >= BOARD_SIZE ||
        src_y < 0 || src_y >= BOARD_SIZE ||
        dest_x < 0 || dest_x >= BOARD_SIZE ||
        dest_y < 0 || dest_y >= BOARD_SIZE) {
        return false;
    }

    // Check if the source and destination squares have different colors
    if (board[src_x][src_y].color == board[dest_x][dest_y].color) {
        return false;
    }

    // TODO: Add other move validation logic (e.g. piece-specific movement rules)
    // For instance, you could have a separate function for each piece type
    // that returns a boolean based on its unique movement capabilities.

    return true;
}

bool move_piece(Board& board, int src_x, int src_y, int dest_x, int dest_y) {
    // Only move the piece if the move is valid
    if (is_valid_move(board, src_x, src_y, dest_x, dest_y)) {
        // Move the piece
        board[dest_x][dest_y] = board[src_x][src_y];
        // Clear the source square
        board[src_x][src_y].type = EMPTY;
        board[src_x][src_y].color = NONE;
        return true;
    }
    return false;
}

Board create_board() {
    Board board(BOARD_SIZE, vector<Piece>(BOARD_SIZE, { EMPTY, NONE }));

    for (int i = 0; i < BOARD_SIZE; ++i) {
        // Add pawns
        board[1][i] = { PAWN, BLACK };
        board[6][i] = { PAWN, WHITE };

        // Add other pieces
        PieceType black_pieces[8] = { ROOK, KNIGHT, BISHOP, QUEEN, KING, BISHOP, KNIGHT, ROOK };
        PieceType white_pieces[8] = { ROOK, KNIGHT, BISHOP, KING, QUEEN, BISHOP, KNIGHT, ROOK };
        board[0][i] = { black_pieces[i], BLACK };
        board[7][i] = { white_pieces[i], WHITE };
    }

    return board;
}
