    async login(username, password) {
      const response = await api.post("/login", { username, password }, { withCredentials: true });
      const { access_token } = response.data;

      localStorage.setItem("token", access_token);
      this.token = access_token;

      const decoded = jwtDecode(access_token);
      const user = await api.get(`/users/${decoded.sub}`);
      this.user = user.data;
    },
    async logout() {
      await api.post("/logout", null, { withCredentials: true });
      localStorage.removeItem("token");
      this.token = null;
      this.user = null;
    },
  },
});

export default authStore;
```

The `login` action makes a POST request to the `/login` endpoint with the username and password of the user. In the request options, we set `withCredentials` to true to allow the browser to include the JWT cookie in the request. The `login` action then stores the token in the localStorage and updates the `token` and `user` state in the Pinia store based on the decoded JWT token.

The `logout` action makes a POST request to the `/logout` endpoint to clear the server's cookies keeping the user logged in, removes the token from the localStorage, and updates the `token` and `user` state in the Pinia store to null.

