```cpp
#include "Renderer.h"

Renderer::Renderer(Window& window)
    : window_(window) {}

Renderer::~Renderer()
{
    if (initialized_)
    {
        cleanup();
    }
}

bool Renderer::initialize()
{
    if (!pipeline_.initialize(window_))
    {
        return false;
    }
    if (!swapchain_.initialize(window_, pipeline_))
    {
        return false;
    }
    if (!resourceLoader_.initialize(window_))
    {
        return false;
    }
    if (!camera_.initialize(window_))
    {
        return false;
    }

    createCommandBuffers();
    createSyncObjects();

    initialized_ = true;
    return true;
}

void Renderer::renderScene(const std::vector<GameObject>& objects)
{
    // Update camera and any other necessary per-frame updates
    camera_.update();

    // Wait for any in-flight frames using this frame's resources to complete
    vkWaitForFences(window_.device, 1, &inFlightFences_[currentFrame_], VK_TRUE, UINT64_MAX);

    // Acquire image and record command buffers
    uint32_t imageIndex = swapchain_.acquireNextImage(imageAvailableSemaphores_[currentFrame_]);
    recordCommandBuffers(objects, imageIndex);

    // Submit render commands and present frame
    swapchain_.submitRenderCommandsAndWait(renderFinishedSemaphores_[currentFrame_], inFlightFences_[currentFrame_]);
    swapchain_.present(imageIndex, renderFinishedSemaphores_[currentFrame_]);

    // Move on to next frame
    currentFrame_ = (currentFrame_ + 1) % maxFramesInFlight_;
}

void Renderer::cleanup()
{
    vkDeviceWaitIdle(window_.device);

    cleanUpSyncObjects();
    freeCommandBuffers();

    resourceLoader_.cleanup();
    swapchain_.cleanup();
    pipeline_.cleanup();

    initialized_ = false;
}

// ... Implement private helper functions for command buffer and sync object creation/destruction

