      .setTitle(prize)
      .setDescription(`React with ?? to enter!\nTime: ${time} seconds`)
      .setTimestamp(new Date(Date.now() + time * 1000))
      .setFooter('Ends at');
    const giveawayMessage = await message.channel.send({ embeds: [embed] });

    // Add ?? reaction
    giveawayMessage.react('??');

    // Wait for giveaway to end
    setTimeout(async () => {
      // Get all users who reacted
      const { users } = await giveawayMessage.reactions.cache.first().fetch();
      const usersArr = users.cache.array().filter(user => !user.bot);

      if (usersArr.length === 0) {
        return message.channel.send('Nobody participated in the giveaway.');
      }

      // Choose a random winner
      const winner = usersArr[Math.floor(Math.random() * usersArr.length)];

      message.channel.send(`Congratulations ${winner.toString()}, you won the giveaway!`);
    }, time * 1000);
  }
});

