        int maxFlow = 0;
        totalCost = 0;
        int[] parent = new int[vertexList.size()];

        while (bellmanFord(source, sink, parent)) {

            int pathFlow = Integer.MAX_VALUE;
            int pathCost = 0;

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                Edge e = this.vertexList.get(u).getOutputEdge(v);
                pathFlow = Math.min(pathFlow, e.getCapacity() - e.getFlow());
                pathCost += e.getCost();
            }

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                Edge e = this.vertexList.get(u).getOutputEdge(v);
                e.addFlow(pathFlow);
            }
            maxFlow += pathFlow;
            totalCost += pathCost;
        }

        System.out.println(String.format("Output [source, sink, max-flow, min-cost]: %d, %d, %d, %d", source, sink, maxFlow, totalCost));
    }

    private boolean bellmanFord(int source, int sink, int[] parent) {

        int[] dist = new int[vertexList.size()];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;

        for (int i = 0; i < vertexList.size() - 1; i++) {
            for (Edge e : this.edgeList) {
                int u = e.getA();
                int v = e.getB();
                if (e.getCapacity() > e.getFlow() && dist[u] != Integer.MAX_VALUE && dist[u] + e.getCost() < dist[v]) {
                    dist[v] = dist[u] + e.getCost();
                    parent[v] = u;
                }
            }
        }

        return dist[sink] != Integer.MAX_VALUE;
    }
}
