aws.secret_access_key=YOUR_AWS_SECRET_ACCESS_KEY
```

3. Create a method in your Spring Boot application to generate a pre-signed URL:

```java
import com.amazonaws.HttpMethod;
import com.amazonaws.SdkClientException;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.model.GeneratePresignedUrlRequest;

import java.net.URL;
import java.util.Date;
// ...

@Autowired
private AmazonS3 s3Client;

public URL generatePresignedUrl(String bucketName, String objectKey) {
    try {
        Date expiration = new Date();
        long expTimeMillis = expiration.getTime();
        expTimeMillis += 1000 * 60 * 60; // valid for 1 hour
        expiration.setTime(expTimeMillis);

        GeneratePresignedUrlRequest generatePresignedUrlRequest = new GeneratePresignedUrlRequest(bucketName, objectKey)
            .withMethod(HttpMethod.PUT)
            .withExpiration(expiration);

        return s3Client.generatePresignedUrl(generatePresignedUrlRequest);
    } catch (SdkClientException e) {
        e.printStackTrace();
        return null;
    }
}
```

4. Use the method above to create a REST endpoint that returns a pre-signed URL:

```java
@RestController
@RequestMapping("/presigned-url")
public class PresignedUrlController {

    // ...generatePresignedUrl method

    @GetMapping
    public ResponseEntity<?> getPresignedUrl(@RequestParam("filename") String filename) {
        String bucketName = "YOUR_BUCKET_NAME";
        URL url = generatePresignedUrl(bucketName, filename);

        if (url == null)
            return new ResponseEntity<>(HttpStatus.INTERNAL_SERVER_ERROR);

        return new ResponseEntity<>(url, HttpStatus.OK);
    }
}
```

5. In your Angular SPA, call this REST endpoint and then use the returned pre-signed URL to upload the file. You can use the axios library or the built-in HttpClient module:

```typescript
import { HttpClient } from '@angular/common/http';

@Injectable()
export class UploadService {
  constructor(private http: HttpClient) {}

  async uploadFile(file: File) {
    const response = await this.http.get<{url: string}>('http://your-backend-url/presigned-url', {params: {filename: file.name}}).toPromise();
    const presignedUrl = response.url;

    const uploadResult = await this.http.put(presignedUrl, file).toPromise();
    return uploadResult;
  }
}
```

With these steps, you can now generate a pre-signed URL in your Spring Boot backend and upload files directly to Amazon S3 from your Angular SPA.

