    if (!glfwInit()) {
        throw std::runtime_error("Failed to initialize GLFW");
    }

    glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);

    windowHandle = glfwCreateWindow(width, height, title.c_str(), nullptr, nullptr);
