Order.java

```java
import java.util.ArrayList;
import java.util.List;

public class Order {

    private List<TShirt> items;

    public Order() {
        items = new ArrayList<>();
    }

    public void addItem(TShirt item) {
        items.add(item);
    }

    public void clearItems() {
        items.clear();
    }

    public List<TShirt> getItems() {
        return items;
    }

    public double getTotalPrice() {
        double totalPrice = 0;
        for (TShirt item : items) {
            totalPrice += item.getTotalPrice();
        }
        return totalPrice;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (TShirt item : items) {
            sb.append(item).append("\n");
        }
        sb.append(String.format("Total price: %.2f", getTotalPrice()));
        return sb.toString();
    }
}
```

This class represents an order with a list of T-shirt items, as well as methods for adding and clearing items, calculating total price, and generating a string representation of the order.

