import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class FileManager {

    public static Map<String, Double> readPricesFromFile(File file) throws IOException {
        Map<String, Double> prices = new HashMap<>();
        FileReader fileReader = new FileReader(file);
        BufferedReader bufferedReader = new BufferedReader(fileReader);
        String line;
        while ((line = bufferedReader.readLine()) != null) {
            String[] tokens = line.split(",");
            String size = tokens[0];
            Double price = Double.valueOf(tokens[1]);
            prices.put(size, price);
        }
        bufferedReader.close();
        return prices;
    }
}
```

This class provides a utility method for reading T-shirt prices from a CSV file into a map with size keys and price values. It uses a FileReader and BufferedReader to read and parse the file data.

