class Course {
    String courseId;
    String courseName;
    int maxStudents;
    List<Student> students = new ArrayList<>();

    public Course(String courseId, String courseName, int maxStudents) {
        this.courseId = courseId;
        this.courseName = courseName;
        this.maxStudents = maxStudents;
    }
}

class Student extends Course {
    String studentId;
    String studentName;
    HashMap<String, Integer> courseMarks = new HashMap<>();

    public Student(String studentId, String studentName, Course course) {
        super(course.courseId, course.courseName, course.maxStudents);
        this.studentId = studentId;
        this.studentName = studentName;
    }

    public boolean addCourse(Course course) {
        if (students.size() < maxStudents && !students.contains(this)) {
            students.add(this);
            return true;
        }
        return false;
    }

    public boolean dropCourse(Course course) {
        if (students.contains(this) && !courseMarks.containsKey(courseId)) {
            students.remove(this);
            return true;
        }
        return false;
    }
}

class Teacher extends Course {
    String teacherId;
    String teacherName;

    public Teacher(String teacherId, String teacherName, Course course) {
        super(course.courseId, course.courseName, course.maxStudents);
        this.teacherId = teacherId;
        this.teacherName = teacherName;
    }

    public void assignMarks(Student student, int marks) {
        if (students.contains(student)) {
            student.courseMarks.put(courseId, marks);
        }
    }

    public List<Student> getStudentsList() {
        return students;
    }
}

public class CourseManagementSystem {
