  "192.168.0.2": "Template2",
  ...
}
```

Then, in your `server.js` file, read this JSON and create a middleware to check the IP address and set the appropriate template before serving the request:

```javascript
const ipToTemplate = require('./ipToTemplate.json');

app.use((req, res, next) => {
  const clientIP = req.ip;
  req.template = ipToTemplate[clientIP] || 'Template1';
  next();
});
```

In your React components, you can then render the correct component based on the `template` prop.

**Step 4: Update the content of the served page using server-sent events**

To work with server-sent events, first create an Express route for the events in your `server.js` file:

```javascript
app.get('/events', (req, res) => {
