```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;

public class Grid {
    private static final int BLOCK_SIZE = 20;   // Width and height of each block
    private static final int GRID_WIDTH = 60;   // Number of blocks in each row of the grid
    private static final int GRID_HEIGHT = 60;  // Number of blocks in each column of the grid

    // Tile states: false = white, true = black
    private boolean[][] grid = new boolean[GRID_WIDTH][GRID_HEIGHT];

    private class GridPanel extends JPanel {
        private int lastRow = -1;
        private int lastCol = -1;

        public GridPanel() {
            setPreferredSize(new Dimension(GRID_WIDTH * BLOCK_SIZE, GRID_HEIGHT * BLOCK_SIZE));

            addMouseListener(new MouseAdapter() {
                @Override
                public void mousePressed(MouseEvent e) {
                    lastRow = e.getY() / BLOCK_SIZE;
                    lastCol = e.getX() / BLOCK_SIZE;
                    toggleBlock(lastRow, lastCol);
                    repaint();
                }
            });

            addMouseMotionListener(new MouseMotionAdapter() {
                @Override
                public void mouseDragged(MouseEvent e) {
                    int row = e.getY() / BLOCK_SIZE;
                    int col = e.getX() / BLOCK_SIZE;
                    if (row != lastRow || col != lastCol) {
                        toggleBlock(row, col);
                        lastRow = row;
                        lastCol = col;
                        repaint();
                    }
                }
            });
        }

        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);

            // Draw the grid
            for (int row = 0; row < GRID_HEIGHT; row++) {
                for (int col = 0; col < GRID_WIDTH; col++) {
                    if (grid[col][row]) {
                        // Block is black
                        g.setColor(Color.BLACK);
                    } else {
                        // Block is white
                        g.setColor(Color.WHITE);
                    }

                    int x = col * BLOCK_SIZE;
                    int y = row * BLOCK_SIZE;
                    g.fillRect(x, y, BLOCK_SIZE, BLOCK_SIZE);
                }
            }

            // Draw grid lines
            g.setColor(Color.GRAY);
            for (int i = 0; i <= GRID_WIDTH; i++) {
                g.drawLine(i * BLOCK_SIZE, 0, i * BLOCK_SIZE, getHeight());
            }
            for (int i = 0; i <= GRID_HEIGHT; i++) {
                g.drawLine(0, i * BLOCK_SIZE, getWidth(), i * BLOCK_SIZE);
            }
        }
    }

    public Grid() {
        JFrame frame = new JFrame("Grid");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setResizable(false);
        frame.add(new GridPanel());
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

    // Toggle the state of the block at the given row and column
    private void toggleBlock(int row, int col) {
        grid[col][row] = !grid[col][row];
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            public void run() {
                new Grid();
            }
        });
    }
}
