        .collect();

    // Parse and unwrap the WETH address
    let weth_address = &WETH_ADDRESS.parse::<Address>().unwrap();

    // Initialize an empty vector for token pairs
    let mut pairs: Vec<[H160; 3]> = vec![];
    // Iterate through the factories and get the market pairs
    for factory in factories {
        let market_pairs = factory
            .get_markets()
            .await
            .into_iter()
            .collect::<Vec<[H160; 3]>>();

        // Add the market pairs to the pairs vector
        for pair in market_pairs {
            pairs.push(pair.to_owned());
        }
    }

    // Group the token pairs by their associated token and filter out those with less than two pairs
    let grouped_pairs: Vec<(H160, Vec<[H160; 3]>)> = pairs
        .into_iter()
        .filter(|pair| {
            pair[0].eq(weth_address) || pair[1].eq(weth_address)
        })
