            };
            let non_weth1 = if pair1[0].eq(weth_address) {
                pair1[1]
            } else {
                pair1[0]
            };
            non_weth1.cmp(&non_weth0)
        })
        .group_by(|pair| {
            if pair[0].eq(weth_address) {
                pair[1]
            } else {
                pair[0]
            }
        })
        .into_iter()
        .map(|(key, group)| {
