            (key, pairs)
        })
        .filter(|(_, pairs)| pairs.len() > (1_usize))
        .collect::<Vec<(H160, Vec<[H160; 3]>)>>();

    // Return the grouped pairs
    grouped_pairs
}

// Define the DexFactory struct, representing the factory of a DEX
pub struct DexFactory<'a, M> {
    factory_contract: IUniswapV2Factory<M>,
    flash_query_contract: &'a FlashBotsUniswapQuery<M>,
}

// Implement the methods for the DexFactory
impl<'a, M> DexFactory<'a, M>
where
    M: Middleware,
{
    // Create a new DexFactory instance, given a pair address, flash query contract, and client
    pub fn new(
        pair_address: Address,
        flash_query_contract: &'a FlashBotsUniswapQuery<M>,
        client: Arc<M>,
    ) -> Self {

        // Create a new IUniswapV2Factory instance with the given client
        let contract = IUniswapV2Factory::new(pair_address, client);

        // Return the DexFactory instance with the initialized factory contract and flash query contract
        Self {
            factory_contract: contract,
            flash_query_contract,
        }
    }

    // Define an async function to get markets from the DexFactory
    pub async fn get_markets(&self) -> Vec<[H160; 3]> {
        let batch_size = U256::from(1000u32);
        let mut start = U256::from(0u32);

        let batch_limit = 10;
        let mut count = 0;
        let mut markets: Vec<[H160; 3]> = vec![];

        // Loop through the batches of pairs to create a final list of markets
        loop {
            let stop = start + batch_size;

            // Query the pairs within the current batch from the flash_query_contract
            let pairs = self
                .flash_query_contract
                .get_pairs_by_index_range(self.factory_contract.address(), start, stop)
                .call()
                .await
                .unwrap();

            count += 1;
            start = stop;

            let pair_length = pairs.len();

            // Add the pairs to the markets vector
            markets.extend(pairs);

            // Exit the loop if there are no more pairs or the batch limit is reached
            if pair_length < batch_size.as_usize() || count > batch_limit {
                dbg!(markets.len());
                break;
            }
        }

        // Return the markets
        markets
    }
}
