Here's a C++ implementation of an s-order Markov chain for numerical sequences. This assumes s=1 for simplicity, and the example uses the numerical sequence `1, 2, 2, 3, 1, 1, 2, 3`. Feel free to modify the input sequence as needed.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>

using namespace std;

class MarkovChain {
    int numStates;
    unordered_map<int, unordered_map<int, int>> counts;
    unordered_map<int, int> stateCounts;

  public:
    MarkovChain(vector<int>& sequence) {
        for (int i = 0; i < sequence.size() - 1; ++i) {
            int currentState = sequence[i];
            int nextState = sequence[i + 1];
            counts[currentState][nextState]++;
            stateCounts[currentState]++;
            if (stateCounts.find(nextState) == stateCounts.end()) {
                stateCounts[nextState] = 0;
            }
        }
        numStates = stateCounts.size();
    }

    double transitionProbability(int from, int to) {
        return static_cast<double>(counts[from][to]) / stateCounts[from];
    }

    void printTransitionMatrix() {
        for (const auto& fromCount: stateCounts) {
            int fromState = fromCount.first;
            for (const auto& toCount: stateCounts) {
                int toState = toCount.first;
                cout << transitionProbability(fromState, toState) << " ";
            }
            cout << endl;
        }
    }
};

int main() {
    vector<int> sequence = {1, 2, 2, 3, 1, 1, 2, 3};
    MarkovChain markovChain(sequence);
    markovChain.printTransitionMatrix();
    return 0;
}
```

This program defines a `MarkovChain` class that constructs the 1st-order Markov chain for the given numerical sequence. The main function initializes the `sequence` vector with the input sequence and constructs the `MarkovChain` object. The `printTransitionMatrix()` function is then used to print the transition probabilities in a matrix format.

For higher-order Markov chains (s > 1), the code can be extended by considering the last s transitions as one state (e.g., storing a tuple of size `s` instead of single integers). Keep in mind that as `s` increases, the transition matrix size will increase exponentially (N^(2s)), which could consume a large amount of memory for even moderate values of `N` and `s`.

To consider high-order dependencies in random sequences, we can create an s-order Markov chain by encoding sequences of length `s` as states in our model. Here's how to extend our previous MarkovChain C++ class to support s-order Markov chains:

```cpp
#include <iostream>
#include <vector>
#include <deque>
#include <unordered_map>
#include <string>

using namespace std;

class MarkovChain {
    int numStates;
    unordered_map<string, unordered_map<string, int>> counts;
    unordered_map<string, int> stateCounts;

    int order;

    string stateToString(deque<int>& state) {
        string key = "";
        for (int& num : state) {
            key += to_string(num) + ",";
        }
        key.pop_back();
        return key;
    }

  public:
    MarkovChain(int s, vector<int>& sequence) {
        order = s;
        deque<int> currentState, nextState;
        for (int i = 0; i < order && i < sequence.size(); ++i) {
            currentState.push_back(sequence[i]);
        }

        for (int i = order; i < sequence.size(); ++i) {
            nextState = currentState;
            nextState.pop_front();
            nextState.push_back(sequence[i]);
            string currentStateStr = stateToString(currentState);
            string nextStateStr = stateToString(nextState);
            counts[currentStateStr][nextStateStr]++;
            stateCounts[currentStateStr]++;
            if (stateCounts.find(nextStateStr) == stateCounts.end()) {
                stateCounts[nextStateStr] = 0;
            }
            currentState = nextState;
        }
        numStates = stateCounts.size();
    }

    double transitionProbability(const string& from, const string& to) {
        return static_cast<double>(counts[from][to]) / stateCounts[from];
    }

    void printTransitionMatrix() {
        for (const auto& fromCount : stateCounts) {
            string fromState = fromCount.first;
            for (const auto& toCount : stateCounts) {
                string toState = toCount.first;
                cout << transitionProbability(fromState, toState) << " ";
            }
            cout << endl;
        }
    }
};

int main() {
    vector<int> sequence = {1, 1, 1, 2, 2, 2, 3, 3, 1, 2, 3};
    int order = 2;
    MarkovChain markovChain(order, sequence);
    markovChain.printTransitionMatrix();

    return 0;
}
```

The main change in this version is the replacement of single integers with `deque<int>` of size `s` to represent the high-order states. A `stateToString` function is introduced to convert these to unique strings to be used as keys in the `unordered_map`. The rest of the class construction and methods remain similar to the 1st-order Markov chain.

This code will now work for any `s`-order Markov chain. However, as the order `s` increases and the size of the input sequence grows, the resulting transition matrix can become very large, so be cautious when working with large values of `s` or long sequences.

