In this tutorial, I'll guide you through the whole process of setting up a Next.js 13 app with a Shopify store using Apollo Client to consume GraphQL queries. The idea of the tutorial is to create a simple Next.js app that fetches products from a Shopify store and displays them on the homepage.

Step 1: Set up a new Next.js project

First, make sure you have Node.js installed. We suggest using the latest LTS version. You can check your version by running:

```bash
node -v
```

To create a new Next.js app, run the following command:

```bash
npx create-next-app your-app-name
```

Then navigate to your new project folder:

```bash
cd your-app-name
```

Step 2: Install Apollo Client, graphql and additional dependencies

Run the following command to install the necessary packages:

```bash
npm install @apollo/client graphql
```

Step 3: Create `.env.local` file

Create a `.env.local` file in the root folder of your Next.js project and add your Shopify API Key and Store URL. To get your API Key, go to the Shopify Admin panel -> Apps -> Manage private apps -> Create a new private app.

```bash
SHOPIFY_API_KEY=your_shopify_api_key
SHOPIFY_STORE_URL=your_shopify_store_url
```

Step 4: Configure Apollo Client

Create a new folder called `lib` in the root folder, then create a file called `apollo.js` inside it. Add the following code:

```javascript
import { ApolloClient, InMemoryCache, HttpLink } from '@apollo/client';

const link = new HttpLink({
  uri: `${process.env.NEXT_PUBLIC_SHOPIFY_STORE_URL}/api/graphql`,
  headers: {
    'X-Shopify-Storefront-Access-Token': process.env.NEXT_PUBLIC_SHOPIFY_API_KEY,
  },
});

const client = new ApolloClient({
  link,
  cache: new InMemoryCache(),
});

export default client;
```

Step 5: Create a GraphQL query to fetch products

Create a new file `graphql.js` in the `lib` folder and add the following code:

```javascript
import { gql } from '@apollo/client';

export const FETCH_PRODUCTS = gql`
  query FetchProducts {
    products(first: 10) {
      edges {
        node {
          id
          title
          handle
        }
      }
    }
  }
`;
```

Step 6: Modify _app.js

Open the `_app.js` file in the `pages` folder and import the `ApolloProvider` component. Wrap your `Component` with the `ApolloProvider` and pass your client object to it. Your _app.js file should look like this:

```javascript
import { ApolloProvider } from '@apollo/client';
import client from '../lib/apollo';
import '../styles/globals.css';

function MyApp({ Component, pageProps }) {
  return (
    <ApolloProvider client={client}>
      <Component {...pageProps} />
    </ApolloProvider>
  );
}

export default MyApp;
```

Step 7: Fetch and display products in the index page

Open the `index.js` file in the `pages` folder and import the `useQuery` hook and the `FETCH_PRODUCTS` query from the `lib/graphql.js` file. In the `HomePage` component, replace `GetServerSideProps` with a call to `useQuery`:

```javascript
import { useQuery } from '@apollo/client';
import { FETCH_PRODUCTS } from '../lib/graphql';

export default function HomePage() {
  const { loading, data, error } = useQuery(FETCH_PRODUCTS);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  const { products } = data;

  return (
    <div>
      <h1>Products</h1>
      <ul>
        {products.edges.map((edge) => (
          <li key={edge.node.id}>{edge.node.title}</li>
        ))}
      </ul>
    </div>
  );
}
```

Now, if you run `npm run dev`, you should see a list of products from your Shopify store displayed on the homepage.

Your Next.js app is now set up to fetch product data from your Shopify store using GraphQL requests powered by Apollo Client. You can further expand your app by adding pages that display more in-depth product information, handle user authentication, or manage cart functionality.

Here's an example of how to render a table with 10,000 data points using JavaScript:

1. First, prepare your HTML file to have a container element where you will insert your table:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>JavaScript Table Rendering</title>
</head>
<body>
  <div id="table-container"></div>
  <script src="script.js"></script> <!-- Your JavaScript code -->
</body>
</html>
```

2. Next, create a JavaScript file (e.g. script.js) that will render and insert the table into the HTML file:

```javascript
// Generate and return a sample 2-dimensional array of data values
function generateSampleData(rows, cols) {
  const data = [];

  for (let i = 0; i < rows; i++) {
    const rowData = [];

    for (let j = 0; j < cols; j++) {
      rowData.push(`Data-${i}-${j}`);
    }
    data.push(rowData);
  }

  return data;
}

// Render a table element from the given data
function renderTable(data) {
  const table = document.createElement('table');
  table.style.borderCollapse = 'collapse';
  table.style.width = '100%';

  for (let i = 0; i < data.length; i++) {
    const row = document.createElement('tr');

    for (let j = 0; j < data[i].length; j++) {
      const cell = document.createElement('td');
      cell.textContent = data[i][j];

      // Set cell style
      cell.style.border = '1px solid #ccc';
      cell.style.padding = '8px';

      row.appendChild(cell);
    }

    table.appendChild(row);
  }

  return table;
}

// Create an the data, render a table, and insert it into the container
function createAndInsertTable() {
  const data = generateSampleData(100, 100); // (rows, cols)
  const table = renderTable(data);
  const container = document.getElementById('table-container');
  container.appendChild(table);
}

// Call the createAndInsertTable function once the DOM is loaded
document.addEventListener('DOMContentLoaded', createAndInsertTable);
```

In this example, a 2-dimensional array of 10,000 data points is generated by `generateSampleData(rows, cols)` function. 

The `renderTable(data)` function takes the data array as input and creates a table structure to display the data. 

Finally, the `createAndInsertTable` function is called when the DOM is ready, which generates the data, renders the table and inserts it into the `table-container` element in the HTML file. You can change the rows and cols value in createAndInsertTable function to generate the different number of data points.

Here's how you can implement lazy loading for a table with 10,000 data points using JavaScript:

1. Modify your HTML file to contain a container element where you will insert your table and additional wrappers for handling scroll behavior:

```html
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>JavaScript Lazy Loading Table</title>
    <style>
      #table-container {
        height: 500px;
        overflow-y: scroll;
      }
    </style>
  </head>
  <body>
    <div id="table-container">
      <div id="table-wrapper"></div>
    </div>
    <script src="script.js"></script>
  </body>
</html>
```

2. Update your JavaScript file (e.g., script.js) to implement lazy loading:

```javascript
const batchSize = 500; // Number of rows per batch
const totalRows = 10000; // Total number of rows
const columns = 10; // Number of columns

const tableWrapper = document.getElementById('table-wrapper');
const tableContainer = document.getElementById('table-container');

let currentRowIndex = 0;

function generateSampleDataRow(rowIndex) {
  const rowData = [];
  for (let i = 0; i < columns; i++) {
    rowData.push(`Data-${rowIndex}-${i}`);
  }
  return rowData;
}

function renderRow(data) {
  const row = document.createElement('tr');
  for (const cellData of data) {
    const cell = document.createElement('td');
    cell.textContent = cellData;
    cell.style.border = '1px solid #ccc';
    cell.style.padding = '8px';
    row.appendChild(cell);
  }
  return row;
}

function loadBatch() {
  const start = currentRowIndex;
  const end = Math.min(currentRowIndex + batchSize, totalRows);
  for (let i = start; i < end; i++) {
    const rowData = generateSampleDataRow(i);
    const row = renderRow(rowData);
    tableWrapper.appendChild(row);
  }
  currentRowIndex += batchSize;
}

function handleScroll(event) {
  const { scrollHeight, scrollTop, clientHeight } = event.target;
  if (scrollHeight - scrollTop === clientHeight && currentRowIndex < totalRows) {
    loadBatch();
  }
}

function init() {
  tableWrapper.style.display = 'table';
  tableWrapper.style.borderCollapse = 'collapse';
  tableWrapper.style.width = '100%';

  loadBatch();

  tableContainer.addEventListener('scroll', handleScroll);
}

init();
```

Now, the table will initially load `batchSize` number of rows, and whenever the user scrolls to the bottom of the table, another batch of rows will load until all rows are loaded.

The `generateSampleDataRow(rowIndex)` function generates a sample data row, and the `renderRow(data)` function renders a single table row.

The `loadBatch()` function is used to load a batch of rows in the table, starting at row index `currentRowIndex`. The `handleScroll(event)` function is triggered on the `scroll` event, and if the user scrolls to the bottom of the table, it calls `loadBatch()` to load more rows.

Finally, the `init()` function sets up the table and its event listeners on page load.

