public class SandwichGenerator {

    public static void main(String[] args) {

        // List of potential sandwich ingredients
        List<String> breadTypes = Arrays.asList("white bread", "whole wheat bread", "rye bread");
        List<String> meats = Arrays.asList("ham", "turkey", "roast beef", "salami");
        List<String> cheeses = Arrays.asList("cheddar", "swiss", "provolone", "mozzarella");
        List<String> veggies = Arrays.asList("lettuce", "tomato", "onion", "pickles");
        List<String> condiments = Arrays.asList("mayonnaise", "mustard", "ketchup", "ranch dressing");

        // Create a scanner object to get user input
        Scanner scanner = new Scanner(System.in);

        // Ask the user for their sandwich preferences
        System.out.println("Welcome to the sandwich generator. Please answer the following questions.");
        System.out.println("What type of bread would you like? (white, whole wheat, or rye)");
        String bread = scanner.nextLine();
        System.out.println("What type of meat would you like? (ham, turkey, roast beef, or salami)");
        String meat = scanner.nextLine();
        System.out.println("What type of cheese would you like? (cheddar, swiss, provolone, or mozzarella)");
        String cheese = scanner.nextLine();
        System.out.println("What type of veggies would you like? (lettuce, tomato, onion, or pickles)");
        String veggie1 = scanner.nextLine();
        System.out.println("Pick one more veggie from the same list");
        String veggie2 = scanner.nextLine();
        System.out.println("What type of condiment would you like? (mayonnaise, mustard, ketchup, or ranch dressing)");
        String condiment = scanner.nextLine();

        // Choose a random ingredient from each list based on user preferences
        if (!breadTypes.contains(bread)) {
            bread = breadTypes.get(new Random().nextInt(breadTypes.size()));
        }
        if (!meats.contains(meat)) {
            meat = meats.get(new Random().nextInt(meats.size()));
        }
        if (!cheeses.contains(cheese)) {
            cheese = cheeses.get(new Random().nextInt(cheeses.size()));
        }
        if (!veggies.contains(veggie1)) {
            veggie1 = veggies.get(new Random().nextInt(veggies.size()));
        }
        if (!veggies.contains(veggie2) || veggie1.equals(veggie2)) {
            veggie2 = veggies.get(new Random().nextInt(veggies.size()));
        }
        if (!condiments.contains(condiment)) {
            condiment = condiments.get(new Random().nextInt(condiments.size()));
        }

        // Print out the final ingredients
        System.out.println("Here's your " + bread + " bread sandwich with " + meat + ", " + cheese + ", " + veggie1 + ", " + veggie2 + ", and " + condiment + ".");
    }

}
