    int copiedSlow = CopyBuffer(SlowMAHandle, 0, 0, 2, slowMA);

    if (copiedFast == -1 || copiedSlow == -1) return;

    // Check for crossovers
    if (fastMA[0] > slowMA[0] && fastMA[1] < slowMA[1])
    {
        trade("BUY");
    }
    else if (fastMA[0] < slowMA[0] && fastMA[1] > slowMA[1])
    {
        trade("SELL");
    }
}

