    XBR1      = 0x40;
}

void Oscillator_Init()
{
    OSCICN    = 0x87;
}

// Initialization function for device,
// Call Init_Device() from your main program
void Init_Device(void)
{
    PCA_Init();
    Timer_Init();
    Port_IO_Init();
    Oscillator_Init();   
}

// Function to display a digit on a specific position of the 4-digit 7-segment display
void display_digit(unsigned char pos, unsigned char digit)
{
    P0 = 0x01 << pos;   // Set the position
    P1 = digit;         // Set the digit
}

void main(void)
{
    unsigned char min = 0, sec = 0;  // Store the current minute and second
    unsigned int count = 0;  // Counter for the delay

    Init_Device();  // Initialize the microcontroller
    ET1 = 1;  // Enable Timer 1 Interrupt
    EA = 1;   // Enable Interrupt
    TR1 = 1;  // Start the Timer

    while(1)
    {
        display_digit(0, min / 10); // Display the ten's position of minute
        for(count = 0; count < 250; count++); // delay
        display_digit(1, min % 10); // Display the one's position of minute
        for(count = 0; count < 250; count++); // delay

        display_digit(2, sec / 10); // Display the ten's position of second
        for(count = 0; count < 250; count++); // delay
        display_digit(3, sec % 10); // Display the one's position of second
        for(count = 0; count < 250; count++); // delay
    }
}

// Timer 1 Interrupt Service Routine
void Timer_ISR(void) interrupt 3
{
    static unsigned int count = 0;
    count++;  // Increment the counter

    // If 50,000 times reached (about a second),
    // update the minute and second accordingly
    if(count >= 50000)
    {
        count = 0;

        sec++;  // Increase second by 1
        if(sec >= 60)
        {
            sec = 0;
            min++; // Increase minute by 1
            if(min >= 60)
                min = 0;
        }
    }
}
