One possible approach to store the SMPP segments with a validity time deadline in Golang is to use a key-value store, such as Redis or Couchbase, and add an expiration time to each key. When the expiration time is reached, the key and its associated value would be automatically deleted from the store.

Here is an example implementation using Redis:

```go
package repository

import (
    "fmt"
    "time"

    "github.com/go-redis/redis/v8"
)

type SegmentRepository interface {
    Save(segment *Segment) error
    GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error)
}

type RedisSegmentRepository struct {
    client *redis.Client
}

func NewRedisSegmentRepository(addr, password string, db int) (*RedisSegmentRepository, error) {
    r := &RedisSegmentRepository{}

    r.client = redis.NewClient(&redis.Options{
        Addr:     addr,
        Password: password,
        DB:       db,
    })

    _, err := r.client.Ping(r.client.Context()).Result()
    if err != nil {
        return nil, fmt.Errorf("unable to connect to redis: %w", err)
    }

    return r, nil
}

func (r *RedisSegmentRepository) Save(segment *Segment) error {
    key := fmt.Sprintf("%s:%d", segment.SessionID, segment.ReferenceNum)

    err := r.client.Set(r.client.Context(), key, segment.Payload, segment.ValidityTime).Err()
    if err != nil {
        return fmt.Errorf("failed to save segment: %w", err)
    }

    return nil
}

func (r *RedisSegmentRepository) GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error) {
    key := fmt.Sprintf("%s:%d", sessionID, referenceNum)

    payload, err := r.client.Get(r.client.Context(), key).Bytes()
    if err != nil {
        return nil, fmt.Errorf("failed to retrieve segments: %w", err)
    }

    segments := make([]*Segment, 0)
    segments = append(segments, &Segment{
        SessionID:     sessionID,
        ReferenceNum:  referenceNum,
        Payload:       payload,
        ValidityTime:  time.Minute * 5, // example validity time
    })

    return segments, nil
}

type Segment struct {
    SessionID     string
    ReferenceNum  int
    Payload       []byte
    ValidityTime  time.Duration // segment expiration
}
```

In this example, we've defined a `SegmentRepository` interface that has two methods, `Save()` and `GetBySessionAndRefNum()`. `Save()` takes a `Segment` struct as an argument and stores it in the key-value store with the specific expiration time. `GetBySessionAndRefNum()` retrieves all segments with the given session ID and reference number.

We've also defined a `RedisSegmentRepository` that implements the `SegmentRepository` interface and uses the Redis driver to save and retrieve segments. The `ValidityTime` field of the `Segment` struct represents the duration until a segment is considered expired and automatically deleted from the store.

Note that this is just an example implementation and should be adjusted to your specific use case and requirements. Please let me know if you have any further questions!

To handle expired segments in the example implementation using Redis, we can use Redis' key expiration feature. 

The key expiration feature can be enabled by setting an expiration time when a key is added to the Redis store. Redis will automatically delete the key and its associated value once the expiration time has been reached.

In the example implementation code, the segment's validity time is specified as the key expiration time when it is saved to the Redis store. When a segment is fetched from the store, Redis will return the segment only if its expiration time has not been reached. If the expiration time has been reached, Redis will return a null value for the key.

To handle expired segments, the `GetBySessionAndRefNum()` method can check if the returned value is null. If it is null, the segment is expired and can be deleted or marked as expired in the database.

Here's an updated implementation of the `GetBySessionAndRefNum()` method that also handles expired segments:

```go
func (r *RedisSegmentRepository) GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error) {
    key := fmt.Sprintf("%s:%d", sessionID, referenceNum)

    payload, err := r.client.Get(r.client.Context(), key).Bytes()
    if err == redis.Nil {
        // Key has expired, segment is considered expired
        return nil, fmt.Errorf("segment with session %s and reference %d is expired", sessionID, referenceNum)
    }
    if err != nil {
        return nil, fmt.Errorf("failed to retrieve segments: %w", err)
    }

    segments := make([]*Segment, 0)
    segments = append(segments, &Segment{
        SessionID:     sessionID,
        ReferenceNum:  referenceNum,
        Payload:       payload,
        ValidityTime:  time.Minute * 5, // example validity time
    })

    return segments, nil
}
```

In this updated implementation, we check if the returned error is of type `redis.Nil`. If it is, we know that the key has expired and return an error indicating that the segment is considered expired.

This implementation allows us to handle expired segments transparently and ensure that only valid segments are returned.

In case we receive 3 out of 4 segments and their validity time expires before we receive the fourth segment, we can implement a solution that uses a combination of Redis and a separate storage system that allows us to keep the expired segments temporarily. This way, we can process the expired segments in our use case service.

Here's an updated implementation that handles this scenario:

```go
package repository

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/go-redis/redis/v8"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
	"go.mongodb.org/mongo-driver/mongo/readpref"
)

type SegmentRepository interface {
	Save(segment *Segment) error
	GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error)
	SearchExpired() ([]*Segment, error)
	DeleteExpired(segment *Segment) error
}

type RedisSegmentRepository struct {
	client *redis.Client
}

type MongoDBSegmentRepository struct {
	client  *mongo.Client
	ctx     context.Context
	timeout time.Duration
}

func NewRedisSegmentRepository(addr, password string, db int) (*RedisSegmentRepository, error) {
	r := &RedisSegmentRepository{}

	r.client = redis.NewClient(&redis.Options{
		Addr:     addr,
		Password: password,
		DB:       db,
	})

	_, err := r.client.Ping(context.Background()).Result()
	if err != nil {
		return nil, fmt.Errorf("unable to connect to redis: %w", err)
	}

	return r, nil
}

func NewMongoDBSegmentRepository(uri string, db string, connectTimeout time.Duration) (*MongoDBSegmentRepository, error) {
	m := &MongoDBSegmentRepository{
		timeout: connectTimeout,
	}

	ctx, cancel := context.WithTimeout(context.Background(), connectTimeout)
	defer cancel()

	client, err := mongo.Connect(ctx, options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}

	m.ctx = context.Background()
	m.client = client

	if err := m.Ping(); err != nil {
		return nil, err
	}

	return m, nil
}

func (m *MongoDBSegmentRepository) Ping() error {
	ctx, cancel := context.WithTimeout(context.Background(), m.timeout)
	defer cancel()

	err := m.client.Ping(ctx, readpref.Primary())
	if err != nil {
		return fmt.Errorf("unable to connect to mongo: %w", err)
	}
	return nil
}

func (r *RedisSegmentRepository) Save(segment *Segment) error {
	key := fmt.Sprintf("%s:%d", segment.SessionID, segment.ReferenceNum)

	err := r.client.Set(r.client.Context(), key, segment.Payload, segment.ValidityTime).Err()
	if err != nil {
		return fmt.Errorf("failed to save segment: %w", err)
	}

	return nil
}

func (r *RedisSegmentRepository) GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error) {
	key := fmt.Sprintf("%s:%d", sessionID, referenceNum)

	payload, err := r.client.Get(r.client.Context(), key).Bytes()
	if err == redis.Nil {
		// Key has expired, segment is considered expired
		segments, err := expiredSegmentRepository.SearchExpired()
		if err != nil {
			return nil, err
		}
		for _, segment := range segments {
			if segment.SessionID == sessionID && segment.ReferenceNum == referenceNum {
				return []*Segment{segment}, nil
			}
		}
		return nil, fmt.Errorf("segment with session %s and reference %d is not found", sessionID, referenceNum)
	}

	if err != nil {
		return nil, fmt.Errorf("failed to retrieve segments: %w", err)
	}

	segments := make([]*Segment, 0)
	segments = append(segments, &Segment{
		SessionID:    sessionID,
		ReferenceNum: referenceNum,
		Payload:      payload,
		ValidityTime: time.Minute * 5, // example validity time
	})

	return segments, nil
}

func (m *MongoDBSegmentRepository) Save(segment *Segment) error {
	collection := m.client.Database("segments").Collection("segments")

	_, err := collection.InsertOne(m.ctx, bson.M{
		"sessionId":    segment.SessionID,
		"referenceNum": segment.ReferenceNum,
		"payload":      segment.Payload,
		"validityTime": segment.ValidityTime,
		"createdAt":    time.Now(),
	})

	if err != nil {
		return err
	}

	return nil
}

func (m *MongoDBSegmentRepository) SearchExpired() ([]*Segment, error) {
	collection := m.client.Database("segments").Collection("segments")

	filter := bson.M{
		"$and": []bson.M{
			{"createdAt": bson.M{"$lte": time.Now().Add(-segmentValidityTime)}},
			{"processedAt": bson.M{"$eq": nil}},
		},
	}

	results, err := collection.Find(m.ctx, filter, options.Find().SetLimit(1000))

	if err == mongo.ErrNoDocuments {
		return []*Segment{}, nil
	}

	if err != nil {
		return nil, err
	}

	segments := []*Segment{}
	for results.Next(m.ctx) {
		var segment Segment
		err = results.Decode(&segment)
		if err != nil {
			return nil, err
		}

		segments = append(segments, &segment)
	}

	return segments, nil
}

func (m *MongoDBSegmentRepository) DeleteExpired(segment *Segment) error {
	collection := m.client.Database("segments").Collection("segments")

	filter := bson.M{
		"$and": []bson.M{
			{"sessionId": bson.M{"$eq": segment.SessionID}},
			{"referenceNum": bson.M{"$eq": segment.ReferenceNum}},
			{"createdAt": bson.M{"$lte": time.Now().Add(-segmentValidityTime)}},
			{"processedAt": bson.M{"$eq": nil}},
		},
	}

	update := bson.M{"$set": bson.M{"processedAt": time.Now()}}

	_, err := collection.UpdateOne(m.ctx, filter, update)
	if err != nil {
		return err
	}

	return nil
}

type Segment struct {
	SessionID    string
	ReferenceNum int
	Payload      []byte
	ValidityTime time.Duration
}

const segmentValidityTime = 10 * time.Minute // example validity time
var expiredSegmentRepository = NewMongoDBSegmentRepository("mongodb://localhost:27017", "segments", 2*time.Second)

