class CustomerImportProcessor extends EventEmitter {
  constructor() {
    super();
    this.queue = [];
    this.isProcessing = false;
    this.on('processNext', this.processNext.bind(this));
  }

  addToQueue(filePath, walletId, wallet, userEmail) {
    this.queue.push({ filePath, walletId, wallet, userEmail });
    if (!this.isProcessing) {
      this.processNext();
    }
  }

  async processNext() {
    if (this.queue.length === 0) {
      this.isProcessing = false;
      return;
    }

    this.isProcessing = true;
    const { filePath, walletId, wallet, userEmail } = this.queue.shift();

    try {
      const totalCustomers = await this.importCustomersFromFile(filePath, walletId, wallet);
      this.emit('processNext');

      // Send an email to the admin
      const subject = 'Customer import completed';
      const text = `The import of ${totalCustomers} customers from the CSV file has been completed.`;
      await sendAdminEmail(subject, text);

    } catch (error) {
      // Log the error and notify the admin about the import failure
      console.error('Error importing customers:', error);

      const subject = 'Customer import failed';
      const text = `An error occurred while importing customers from the CSV file: ${error.message}`;
      await sendAdminEmail(subject, text);

      this.emit('processNext');
    }
  }

  async importCustomersFromFile(filePath, walletId, wallet) {
    const readStream = fs.createReadStream(filePath, { encoding: 'utf8' });

    const { quantity } = await sms.getCreditQuantity(walletId);
    const customers = [];

    return new Promise((resolve, reject) => {
      Papa.parse(readStream, {
        header: true,
        delimiter: ';',
        step: async (results, parser) => {
          readStream.pause();
          customers.push(...results.data);

          if (customers.length >= CSV_CHUNK_SIZE) {
            parser.pause();
            await this.processCustomers(walletId, wallet, quantity, sendNotificationsToCustomers, customers.splice(0));
            readStream.resume();
            parser.resume();
          }

        },
        complete: async () => {
          if (customers.length > 0) {
            await this.processCustomers(walletId, wallet, quantity, sendNotificationsToCustomers, customers);
          }
          resolve(customers.length);
        },
        error: reject,
      });
    });
  }

  async processCustomers(walletId, wallet, quantity, sendNotificationsToCustomers, customers) {
    const chunks = chunkArray(customers, WORKER_POOL_SIZE);

    const results = await asyncPool(WORKER_POOL_SIZE, chunks, async (chunk) => {
      return new Promise((resolve, reject) => {
        const worker = new Worker('./customerWorker.js', {
          workerData: { chunk, walletId, wallet, quantity, sendNotificationsToCustomers },
        });

        worker.once('message', resolve);
        worker.once('error', reject);
      });
    });

    return results.reduce((count, res) => count + res.addedClients, 0);
  }
}

function chunkArray(array, size) {
