    for (uint32_t i = 0; i < queueFamilyCount; ++i)
    {
        if (queueFamilies[i].queueFlags & VK_QUEUE_GRAPHICS_BIT)
        {
            indices.graphicsFamily = i;
            break;
        }
    }

    return indices;
}
```

With this implementation, your `CreateCommandPool` method will properly create a command pool, using the correct queue family index for graphics operations in the selected Vulkan physical device. Then, it will proceed to call the `CreateCommandBuffers` method.

