// Define a region of interest for Java Island, Indonesia.
var roi = ee.Geometry.Polygon([[[105.147,-8.732], [114.711,-8.732], [114.711,-6.069], [105.147,-6.069], [105.147,-8.732]]]);

// Load the MOD11A1 dataset from Google Earth Engine.
