const chatForm = document.getElementById("chat-form");
const chatMessages = document.getElementById("chat-messages");
const inputMessage = document.getElementById("input-message");

let questions = [
    "What's your favorite color?",
    "What's your favorite movie?",
    "What's your favorite food?",
];
let askedQuestons = 0;
let userName = "";
let waiting = false;

const addMessage = (text, className) => {
    const message = document.createElement("div");
    message.classList.add("chat-message", className);
    message.innerText = text;
    chatMessages.appendChild(message);
};

const botReply = (message) => {
    setTimeout(() => {
        addMessage(message, "bot");
    }, 1000);
};

chatForm.addEventListener("submit", (event) => {
    event.preventDefault();

    if (inputMessage.value.trim() === "") return;

    // User Message
    addMessage(inputMessage.value, "user");
    chatMessages.scrollTop = chatMessages.scrollHeight;

    const responseToUser = (message) => {
        botReply(message);
        chatMessages.scrollTop = chatMessages.scrollHeight;
        inputMessage.value = "";
        waiting = false;
    };

    if (!userName) {
        // Store the user's name and send the first question
        userName = inputMessage.value;
        responseToUser(`Hi ${userName}, ${questions[askedQuestons]}`);
        askedQuestons++;
        inputMessage.value = "";
    } else if (!waiting && askedQuestons < questions.length) {
        // Ask the next question after 3 seconds
        waiting = true;
        setTimeout(
            () => responseToUser(questions[askedQuestons++]),
            3000
        );
    } else {
        inputMessage.value = "";
    }
});
```

This code creates a simple chatbot interface, where the user can type their name and answers to questions. Note that this example may not cover all real-world scenarios for advanced chatbots, but can be used as a starting point to build more complex chatbots.

