        })
        if err != nil {
            dialog.ShowError(fmt.Errorf("Failed to invoke code: %v", err), a)
        }
    })

    // Create a new window and set its content to a vertical box containing
    // the label and button widgets
    w := a.NewWindow("QR Code Scanner")
