        resultLabel,
        scanButton,
    ))

    // Listen for Android window lifecycle events
    a.Driver().Mobile().SetOnLifecycleChanged(func(event lifecycle.Event) {
        switch event.State {
        case lifecycle.StageVisible:
            // The window is visible, start rendering
            w.Canvas().(gl.Context).Enable(gl.BLEND)
            w.Canvas().(gl.Context).BlendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)
            w.Canvas().(gl.Context).Clear(gl.COLOR_BUFFER_BIT)
            w.Canvas().(gl.Context).Finish()
        case lifecycle.StageHidden:
            // The window is hidden, stop rendering
            w.Canvas().(gl.Context).Disable(gl.BLEND)
            w.Canvas().(gl.Context).Clear(gl.COLOR_BUFFER_BIT)
            w.Canvas().(gl.Context).Finish()
        }
    })

    // Listen for Android window events
    w.Canvas().(event.Queue).Post(event.Event{})

    // Show the window and start the app
    w.ShowAndRun()
}
