};

ResizableArray::ResizableArray() {
    // Constructor - no initialization required
}

void ResizableArray::add(int value) {
    array.push_back(value);
}

int ResizableArray::get(int index) {
    return array[index];
}

void ResizableArray::resize(int newSize) {
    array.resize(newSize);
}

int ResizableArray::size() {
    return array.size();
}

int main() {
    ResizableArray arr;

    // Add some elements to the array
    arr.add(10);
    arr.add(20);
    arr.add(30);

