```csharp
using System;
using System.Runtime.InteropServices;

public class PaperScanner
{
    // Constants

    private const uint WIA_DEVICE_LIST_ALL_DEVICES = 0x01;
    private const uint WIA_INTENT_IMAGE_TYPE_COLOR = 0x00000001;
    private const uint WIA_IMG_FORMAT_JPEG = 4;
    private const uint WIA_PROPERTY_ID_STREAM_NAME = 3102;
    private const uint WIA_PROPERTY_ID_FORMAT = 6146;
    private const uint WIA_IPS_CUR_INTENT = 6147;
    private const uint WIA_IPS_XRES = 6148;
    private const uint WIA_IPS_YRES = 6149;
    private const uint WIA_IPS_XEXTENT = 6150;
    private const uint WIA_IPS_YEXTENT = 6151;

    // Enums

    private enum STI_DEVICE_TYPE
    {
        StiDeviceTypeDefault = 0,
        StiDeviceTypeScanner = 1,
        StiDeviceTypeDigitalCamera = 2,
        StiDeviceTypeStreamingVideo = 3
    }

    private enum WIA_DATA_TYPE
    {
        Unspecified = 0,
        Binary = 1,
        ASCII = 2,
        Short = 3,
        Long = 4,
        Rational = 5,
        Byte = 6,
        Undefined = 7,
        FileType = 8,
        MultiByte = 9,
        Complex = 10
    }

    // Structs

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    private struct STI_DEVICE_INFORMATION
    {
        public int dwSize;
        public string pszDeviceName;
        public string pszPortName;
        public string pszPropProvider;
        public STI_DEVICE_TYPE DeviceType;
        public Guid guid;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct WIA_DEV_INFO
    {
        public uint dwSize;
        public Guid guid;
        [MarshalAs(UnmanagedType.LPWStr)]
        public string wszVendorDescription;
        public uint ulFlags;
        [MarshalAs(UnmanagedType.LPWStr)]
        public string wszVendorDriverVersion;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct PROPVARIANT
    {
        public short vt;
        public short reserved1;
        public short reserved2;
        public short reserved3;
        public IntPtr pointerValue;
    }

    // P/Invoke functions

    [DllImport("sti.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
    private static extern int StiCreateInstance(IntPtr hinst, uint dwVer, out IStillImage ppSti, IntPtr punkOuter);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
    private static extern uint GetLastError();

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    private static extern int MessageBox(IntPtr hWnd, string text, string caption, uint type);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern IntPtr FindWindow(string className, string windowName);

    // Interfaces

    [ComImport, Guid("B123F57D-9D04-469d-9CF7-FC60AEF0B6D6")]
    private interface IStillImage
    {
        int EnumDevices(uint dwType, IntPtr pInterface, out IEnumWIA_DEV_INFO ppIEnum);
    }

    [ComImport, Guid("5e38b83c-8cf1-11d1-bf92-0060081ed811"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    private interface IEnumWIA_DEV_INFO
    {
        [PreserveSig]
        int Next(uint celt, out IntPtr rgelt, out uint pceltFetched);
    }

    [ComImport, Guid("4db1ad10-3391-11d2-9a33-00c04fa36145")]
    private class WIA
    {
    }

    // Public methods

    public static void Scan()
    {
        try
        {
            IStillImage sti;
            int result = StiCreateInstance(IntPtr.Zero, 1, out sti, IntPtr.Zero);

            if (result != 0)
            {
                uint error = GetLastError();
                MessageBox(IntPtr.Zero, "Failed to create Sti instance.", "Error", 0);
                return;
            }

            IEnumWIA_DEV_INFO devEnum;
            result = sti.EnumDevices(1, IntPtr.Zero, out devEnum);

            if (result != 0)
            {
                MessageBox(IntPtr.Zero, "Failed to enumerate WIA devices.", "Error", 0);
                return;
            }

            IntPtr deviceInfoPointer;
            uint count;
            result = devEnum.Next(1, out deviceInfoPointer, out count);

            if (result != 0 || count == 0)
            {
                MessageBox(IntPtr.Zero, "Failed to get device info.", "Error", 0);
                return;
            }

            WIA_DEV_INFO deviceInfo = (WIA_DEV_INFO)Marshal.PtrToStructure(deviceInfoPointer, typeof(WIA_DEV_INFO));
            Marshal.FreeCoTaskMem(deviceInfoPointer);

            object wia = new WIA();
            object device = wia.GetType().InvokeMember("Create", System.Reflection.BindingFlags.InvokeMethod, null, wia, new object[] { deviceInfo.guid });

            if (device == null)
            {
                MessageBox(IntPtr.Zero, "Failed to create WIA device.", "Error", 0);
                return;
            }

            object items = device.GetType().InvokeMember("Items", System.Reflection.BindingFlags.GetProperty, null, device, null);
            object item = items.GetType().InvokeMember("Item", System.Reflection.BindingFlags.InvokeMethod, null, items, new object[] { 1 });

            if (item == null)
            {
                MessageBox(IntPtr.Zero, "Failed to get item.", "Error", 0);
                return;
            }

            object properties = item.GetType().InvokeMember("Properties", System.Reflection.BindingFlags.GetProperty, null, item, null);

            SetProperty(properties, WIA_IPS_CUR_INTENT, WIA_INTENT_IMAGE_TYPE_COLOR);
            SetProperty(properties, WIA_IPS_XRES, 150);
            SetProperty(properties, WIA_IPS_YRES, 150);
            SetProperty(properties, WIA_IPS_XEXTENT, 2550);
            SetProperty(properties, WIA_IPS_YEXTENT, 3300);
            SetProperty(properties, WIA_PROPERTY_ID_STREAM_NAME, "test.jpg");
            SetProperty(properties, WIA_PROPERTY_ID_FORMAT, WIA_IMG_FORMAT_JPEG);

            object imageFile = item.GetType().InvokeMember("Transfer", System.Reflection.BindingFlags.InvokeMethod, null, item, null);
            string fileName = (string)GetProperty(imageFile, WIA_PROPERTY_ID_STREAM_NAME);

            MessageBox(IntPtr.Zero, "File saved to " + fileName, "Success", 0);
        }
        catch (Exception ex)
        {
            MessageBox(IntPtr.Zero, "Exception: " + ex.Message, "Error", 0);
        }
    }

    // Private methods

    private static void SetProperty(object properties, uint propertyId, object value)
    {
        object property = properties.GetType().InvokeMember("Item", System.Reflection.BindingFlags.GetProperty, null, properties, new object[] { propertyId });
        property.GetType().InvokeMember("set_Value", System.Reflection.BindingFlags.InvokeMethod, null, property, new object[] { value });
    }

    private static object GetProperty(object properties, uint propertyId)
    {
        object property = properties.GetType().InvokeMember("Item", System.Reflection.BindingFlags.GetProperty, null, properties, new object[] { propertyId });
        return property.GetType().InvokeMember("get_Value", System.Reflection.BindingFlags.InvokeMethod, null, property, null);
    }
}
