using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Threading;

namespace RFC2217Example
{
    public class RFC2217 : IDisposable
    {
        private readonly TcpClient _tcpClient;
        private readonly NetworkStream _networkStream;
        private readonly StreamReader _streamReader;
        private readonly StreamWriter _streamWriter;
        private Thread _readThread;
        private byte _optionCode;
        private byte[] _optionData;
        private byte[] _buffer;
        private int _bufferIndex;
        private int _bufferCount;
        private bool _connected;

        public RFC2217(string ipAddress, int port)
        {
            _tcpClient = new TcpClient();
            _tcpClient.Connect(ipAddress, port);

            _networkStream = _tcpClient.GetStream();
            _streamReader = new StreamReader(_networkStream);
            _streamWriter = new StreamWriter(_networkStream);

            _connected = true;

            _readThread = new Thread(() =>
            {
                while (_connected)
                {
                    try
                    {
                        ParseData();
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error in read thread: {ex.Message}");
                        Dispose();
                    }
                }
            });
            _readThread.Start();
        }

        private void ParseData()
        {
            if (_bufferCount == 0)
            {
                _bufferIndex = 0;
                _buffer = new byte[1024];
                _bufferCount = _networkStream.Read(_buffer, 0, _buffer.Length);
            }

            if (_bufferCount == 0)
            {
                Dispose();
            }

            for (var i = 0; i < _bufferCount; i++)
            {
                byte b = _buffer[i];

                if (_optionCode != 0)
                {
                    switch (_optionCode)
                    {
                        case 1:
                            if (_optionData.Length == 1 && _optionData[0] == 0)
                            {
                                _streamWriter.Write(_optionData);
                                _streamWriter.Flush();
                            }
                            break;

                        default:
                            break;
                    }
                    _optionCode = 0;
                    _optionData = null;
                }
                else if (b == 255)
                {
                    _optionData = new byte[0];
                    _optionCode = 255;
                }
                else
                {
                    _streamWriter.Write(b);
                    _streamWriter.Flush();
                }
            }

            _bufferCount = 0;
        }

        public void WriteLine(string s)
        {
            byte[] bytes = System.Text.Encoding.ASCII.GetBytes(s);
            Write(bytes);
            Write(new byte[] { 13, 10 });
        }

        public void Write(byte[] bytes)
        {
            byte[] optionData = new byte[bytes.Length];
            bytes.CopyTo(optionData, 0);

            var optionBytes = new byte[]
            {
                255, // IAC
                250, // SB
                0,   // Option 0
                0,   // Value
            };

            optionBytes[3] = _optionCode;
            optionBytes = optionBytes.Concat(optionData).ToArray();
            optionBytes = optionBytes.Concat(new byte[] { 255, 240 }).ToArray();

            _networkStream.Write(optionBytes, 0, optionBytes.Length);
            _networkStream.Flush();
        }

        public void Dispose()
        {
            _connected = false;
            _streamReader?.Dispose();
            _streamWriter?.Dispose();
            _tcpClient?.Close();
        }
    }
}
```

