  const textHeight = Jimp.measureTextHeight(font, text, textWidth); // measure the height of the text

  const textImage = new Jimp(textWidth, textHeight, 0x00000000); // create a new transparent image for the text
  textImage.print(font, 0, 0, {
    text: text,
    alignmentX: Jimp.HORIZONTAL_ALIGN_CENTER, // center the text horizontally
    alignmentY: Jimp.VERTICAL_ALIGN_MIDDLE, // center the text vertically
    maxWidth: textWidth, // wrap the text to multiple lines if it exceeds the image width
  }); // add the text to the text image

  image.composite(textImage, (imageWidth - textWidth) / 2, (imageHeight - textHeight) / 2, {
    mode: Jimp.BLEND_SOURCE_OVER, // blend the text image over the background image
  }); // composite the text image over the background image

