```kotlin
package com.example.musicapp.Interface

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.runtime.Composable
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.compose.NavType
import androidx.navigation.compose.navArgument
import com.example.musicapp.Data.Category
import com.example.musicapp.ViewModel.CategoriesViewModel


class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            val navController = rememberNavController()
            NavHost(navController, startDestination = "categories") {
                composable("categories") { CategoriesScreen(navController) }
                composable("category/{id}", arguments = listOf(navArgument("id") { type = NavType.IntType })) { backStackEntry ->
                    val categoryId = backStackEntry.arguments?.getInt("id")
                    categoryId?.let {
                        val viewModel: CategoriesViewModel = viewModel()
                        val category = viewModel.categories.value.find { it.id == categoryId }
                        if (category != null) {
                            ArtistDetailScreen(category) {
                                navController.popBackStack()
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun CategoriesScreen(navController: NavController) {
  val categoriesViewModel: CategoriesViewModel = viewModel()
  val categories by categoriesViewModel.categories.collectAsState()
  Scaffold(
      topBar = { TopBar("Categories") }
  ) {
    // Update onClick of category item
    MusicCategoriesScreen(categories = categories, onClick = { category ->
      navController.navigate("category/${category.id}")
    })
  }
}
```

With these changes:

- `MusicCategoriesScreen` composable now accepts an `onClick` lambda, which will be triggered when the category item is clicked. It'll navigate to the `ArtistsDetailScreen`.
- `MainActivity` is updated to use NavigationCompose and define the navigation paths ("categories" and "category/{id}").

