IEnumerator ClimbStep(Vector3 targetOffset)
{
    isClimbing = true;

    // 获取移动目标点
    Vector3 targetPosition = transform.position + transform.TransformDirection(targetOffset);

    // 在当前位置和目标位置之间创建一个BoxCast检查是否有障碍物
    RaycastHit hit;
    bool hasObstacle = Physics.BoxCast(transform.position, GetComponent<CapsuleCollider>().size / 2, targetOffset.normalized, out hit, transform.rotation, targetOffset.magnitude);

    if (!hasObstacle)
    {
        // 创建一个循环使玩家移动到目标位置
        float startTime = Time.time;
        float journeyLength = Vector3.Distance(transform.position, targetPosition);
        float speed = journeyLength / 0.2f; // 每次移动的时间为0.2秒

        while (Vector3.Distance(transform.position, targetPosition) > 0.001f)
        {
            float distCovered = (Time.time - startTime) * speed;
            float fractionOfJourney = distCovered / journeyLength;
            transform.position = Vector3.Lerp(transform.position, targetPosition, fractionOfJourney);
            yield return null;
        }

        // 将位置设置为目标位置，以防移动过程中出现误差
        transform.position = targetPosition;
    }

    isClimbing = false;
}
```

这个方法使用了协程（Coroutine），在按下上楼键或下楼键时平滑地移动玩家位置。使用 BoxCast 检测玩家前方是否有障碍物来避免穿越墙壁。

