            return targetDirection.scl(1.0f / Gdx.graphics.getDeltaTime());
        } else {
            // Find the velocity needed to reach the target position smoothly
            float targetSpeed = maxSpeed * interpolation.apply(distance / maxDistancePerStep);
            Vector2 targetVelocity = targetDirection.nor().scl(targetSpeed);

            // Compute the exact velocity needed to reach the target position in one step
            Vector2 velocityForExactPosition = targetDirection.scl(1.0f / PhysicsSystem.STEP_FREQUENCY);

            // Smoothly interpolate between current velocity and the target velocity using the interpolation function
            Vector2 finalVelocity = body.getLinearVelocity().cpy().interpolate(targetVelocity, Gdx.graphics.getDeltaTime(), interpolation);

            // Check if the interpolated velocity will overshoot the position in the next frame, and limit the velocity if necessary
            if (finalVelocity.len2() > velocityForExactPosition.len2()) {
                finalVelocity = velocityForExactPosition;
            }

            return finalVelocity;
        }
