@Composable
fun MusicCategories(navController: NavController) {
    val categoryNavController = rememberNavController()

    Column {
        TopBar(title = "Music Categories")

        NavHost(categoryNavController, startDestination = "categories") {
            composable("categories") {
                val categoriesViewModel: CategoriesViewModel = viewModel()
                val categories by categoriesViewModel.categories.collectAsState()

                MusicCategoriesScreen(
                    categories = categories,
                    onCategorySelected = { category ->
                        categoryNavController.navigate("artistsDetail/${category.id}")
                    }
                )
            }
            composable("artistsDetail/{categoryId}") { backStackEntry ->
                val categoryId = backStackEntry.arguments?.getString("categoryId")?.toIntOrNull()
                if (categoryId != null) {
                    ArtistsDetailScreen(categoryId)
                }
            }
        }
