Add the following code to fix the issue:

```javascript
function handlePlayerCollision(obstacle) {
  const prevLeft = playerX - PLAYER_RADIUS * 2;
  const prevRight = playerX;
  const prevTop = playerY - PLAYER_RADIUS * 2;
  const prevBottom = playerY;

  const currLeft = playerX;
  const currRight = playerX + PLAYER_RADIUS * 2;
  const currTop = playerY;
  const currBottom = playerY + PLAYER_RADIUS * 2;

  const obstacleLeft = obstacle.x;
  const obstacleRight = obstacle.x + obstacle.width;
  const obstacleTop = obstacle.y;
  const obstacleBottom = obstacle.y + obstacle.height;

  if (prevBottom <= obstacleTop && currBottom > obstacleTop) {
    playerY = obstacleTop - PLAYER_RADIUS * 2;
    playerSpeedY = 0;
    return true;
  } else if (prevTop >= obstacleBottom && currTop < obstacleBottom) {
    playerY = obstacleBottom;
    playerSpeedY = 0;
    return true;
  } else if (prevLeft >= obstacleRight && currLeft < obstacleRight) {
    playerX = obstacleRight;
    playerSpeedX = 0;
    return true;
  } else if (prevRight <= obstacleLeft && currRight > obstacleLeft) {
    playerX = obstacleLeft - PLAYER_RADIUS * 2;
    playerSpeedX = 0;
    return true;
  }

  return false;
}

function isColliding(x, y, width, height) {
  for (const obstacle of obstacles) {
    if (obstacle && x < obstacle.x + obstacle.width && x + width > obstacle.x && y < obstacle.y + obstacle.height && y + height > obstacle.y) {
      return obstacle;
    }
  }
  return null;
}

function detectObstacleCollision() {
  const obstacle = isColliding(playerX, playerY, PLAYER_RADIUS * 2, PLAYER_RADIUS * 2);
  if (obstacle) {
    handlePlayerCollision(obstacle);
  } else {
    playerIsOnGround = false;
  }
}
