const TRACTION = 0.9;
const maxFallSpeed = 10;

function applyGravity() {
  if (!playerIsOnGround) {
    playerSpeedY += GRAVITY / 60;

    if (playerSpeedY > maxFallSpeed) { // limit falling speed
      playerSpeedY = maxFallSpeed;
    }
  }
}

function applyTraction() {
  if (playerIsOnGround) {
    playerSpeedX *= TRACTION;
  }
}

function handlePlayerCollision(obstacle, axis) {
  if (axis === "horizontal") {
    if (playerSpeedX > 0) { // moving right, hit left edge
      playerX = obstacle.x - PLAYER_RADIUS * 2 - 1;
    } else { // moving left, hit right edge
      playerX = obstacle.x + obstacle.width + 1;
    }
    playerSpeedX = 0;
  } else {
    if (playerSpeedY > 0) { // falling, hit top edge
      playerY = obstacle.y - PLAYER_RADIUS * 2 - 1;
      playerSpeedY = 0;
      playerIsOnGround = true;
    } else { // moving up, hit bottom edge
      playerY = obstacle.y + obstacle.height + 1;
      playerSpeedY = 0;
    }
  }
}

function detectObstacleCollision() {
  const obstacleHorizontal = isColliding(playerX + playerSpeedX, playerY, PLAYER_RADIUS * 2, PLAYER_RADIUS * 2);
  const obstacleVertical = isColliding(playerX, playerY + playerSpeedY, PLAYER_RADIUS * 2, PLAYER_RADIUS * 2);

  if (obstacleHorizontal) {
    handlePlayerCollision(obstacleHorizontal, 'horizontal');
  }

  if (obstacleVertical) {
    handlePlayerCollision(obstacleVertical, 'vertical');
  } else {
    playerIsOnGround = false;
  }
}

function jump() {
  if (playerIsOnGround) {
    playerSpeedY = -20;
    playerIsOnGround = false;
  }
}

