class Platform {
    // ...

    resolveCollision(playerPolygon, normal) {
        const aabbPlatform = this.geometry.getAABB();
        const aabbPlayer = playerPolygon.getAABB();

        const overlapX = Math.min(aabbPlatform.maxX - aabbPlayer.minX, aabbPlayer.maxX - aabbPlatform.minX);
        const overlapY = Math.min(aabbPlatform.maxY - aabbPlayer.minY, aabbPlayer.maxY - aabbPlatform.minY);

        if (overlapX < overlapY) {
            // Move player in X direction
            if (aabbPlayer.maxX < aabbPlatform.maxX) {
                // Move to the left
                for (let i = 0; i < playerPolygon.vertices.length; i++) {
                    playerPolygon.vertices[i][0] -= overlapX;
                }
                normal[0] = -1;
            } else {
                // Move to the right
                for (let i = 0; i < playerPolygon.vertices.length; i++) {
                    playerPolygon.vertices[i][0] += overlapX;
                }
                normal[0] = 1;
            }
            normal[1] = 0;
        } else {
            // Move player in Y direction
            if (aabbPlayer.maxY < aabbPlatform.maxY) {
                // Move up
                for (let i = 0; i < playerPolygon.vertices.length; i++) {
                    playerPolygon.vertices[i][1] -= overlapY;
                }
                normal[1] = -1;
            } else {
                // Move down
                for (let i = 0; i < playerPolygon.vertices.length; i++) {
                    playerPolygon.vertices[i][1] += overlapY;
                }
                normal[1] = 1;
            }
            normal[0] = 0;
        }
    }
}
