class Polygon {
    constructor(vertices) {
        this.vertices = vertices;
    }

    getNormals() {
        const normals = [];
        for (let i = 0; i < this.vertices.length - 1; i++) {
            normals.push([
                this.vertices[i + 1][1] - this.vertices[i][1],
                -(this.vertices[i + 1][0] - this.vertices[i][0]),
            ]);
        }

        // Last vertex
        normals.push([
            this.vertices[0][1] - this.vertices[this.vertices.length - 1][1],
            -(this.vertices[0][0] - this.vertices[this.vertices.length - 1][0]),
        ]);

        // Normalize normals
        for (const normal of normals) {
            const length = Math.sqrt(normal[0] ** 2 + normal[1] ** 2);
            normal[0] /= length;
            normal[1] /= length;
        }

        return normals;
    }

    project(normal) {
        let min = this.vertices[0][0] * normal[0] + this.vertices[0][1] * normal[1];
        let max = min;

        for (const vertex of this.vertices.slice(1)) {
            const dotProduct = vertex[0] * normal[0] + vertex[1] * normal[1];
            min = Math.min(min, dotProduct);
            max = Math.max(max, dotProduct);
        }

        return [min, max];
    }
}

