class Polygon {
  constructor(vertices) {
    this.vertices = vertices; // List of [x, y] vectors representing the points of the polygon
  }

  get edges() {
    let result = [];
    for (let i = 0; i < this.vertices.length; i++) {
      let j = i + 1 < this.vertices.length ? i + 1 : 0;
      result.push([this.vertices[j][0] - this.vertices[i][0], this.vertices[j][1] - this.vertices[i][1]]);
    }
    return result;
  }

  project(axis) {
    let lo = Infinity;
    let hi = -Infinity;
    for (let vertex of this.vertices) {
      let dot = vertex[0] * axis[0] + vertex[1] * axis[1];
      if (dot < lo) lo = dot;
      if (dot > hi) hi = dot;
    }
    return [lo, hi];
  }
}

class Platform {
  constructor(geometry) {
    this.geometry = geometry; // A Polygon object representing the hitbox of the platform
  }

  collidesWith(playerPolygon) {
    // Check if the platforms hitbox and player object hitbox polygons intersect
    // using a collision detection algorithm such as Separating Axis Theorem
    let axes = [].concat(this.geometry.edges, playerPolygon.edges);
    for (let axis of axes) {
      let axis_normal = [-axis[1], axis[0]];
      let projectionA = this.geometry.project(axis_normal);
      let projectionB = playerPolygon.project(axis_normal);

      if (projectionA[1] < projectionB[0] || projectionB[1] < projectionA[0]) {
        return false;
      }
    }
    return true;
  }

