class Polygon {
  constructor(vertices) {
    this.vertices = vertices; // List of [x, y] vectors representing the points of the polygon
  }
}

class Platform {
  constructor(geometry) {
    this.geometry = geometry; // A Polygon object representing the hitbox of the platform
  }

  collidesWith(playerPolygon) {
    // Check if the platforms hitbox and player object hitbox polygons intersect
    // using a collision detection algorithm such as Separating Axis Theorem
    let collider = new SAT.Polygon(new SAT.Vector(0, 0), this.geometry.vertices.map(vertex => new SAT.Vector(vertex[0], vertex[1])));
    let collidee = new SAT.Polygon(new SAT.Vector(0, 0), playerPolygon.vertices.map(vertex => new SAT.Vector(vertex[0], vertex[1])));

    return SAT.testPolygonPolygon(collider, collidee);
  }

  resolveCollision(playerPolygon, normal) {
    // Calculate the appropriate physical forces to apply to the player based on the
    // normal vector of the intersection area and the player’s velocity
    const normalForce = Math.max(0, normal.dot(playerPolygon.velocity));
    return playerPolygon.velocity.sub(normal.mulScalar(normalForce));
  }
}

class Player {
  constructor(geometry, velocity) {
    this.geometry = geometry; // A Polygon object representing the hitbox of the player
    this.velocity = new SAT.Vector(velocity[0], velocity[1]); // A [x, y] vector representing the current velocity of the player
