    this.x += this.vx;
    this.y += this.vy;

    if (this.x < 0 || this.x + this.w > canvas.width || this.y < 0 || this.y + this.h > canvas.height) {
      return false;
    }
    return true;
  }

  collidesWith(obj) {
    return !(obj.x > this.x + this.w || obj.x + obj.w < this.x || obj.y > this.y + this.h || obj.y + obj.h < this.y);
  }
}

