        return true;
    });

    // Add more gates for each service
}
```

6. Check permissions in GatewayController

In the 'GatewayController', check if a user is authorized for a given service using the gates:

```php
public function handleService1(Request $request)
{
    if (Gate::denies('access-service1')) {
        abort(403, 'Access denied');
    }

    // Continue handling the request
}

public function handleService2(Request $request)
{
