#include <Keypad.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

const byte ROWS = 4;
const byte COLS = 4;
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {9, 8, 7, 6};
byte colPins[COLS] = {5, 4, 3, 2};

Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);
LiquidCrystal_I2C lcd(0x27, 20, 4);

int currentMenu = 0;
int subMenuValue = 0;
String inputBuffer = "";

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.print("Menu: A B C D");
}

void loop() {
  char key = keypad.getKey();
  if (key) {
    if (currentMenu == 0) {
      handleMainMenu(key);
    } else {
      handleSubMenu(key);
    }
  }
}

void handleMainMenu(char key) {
  if (key == 'A' || key == 'B' || key == 'C' || key == 'D') {
    currentMenu = key;
    lcd.clear();
    lcd.print("Submenu ");
    lcd.print(key);
    lcd.setCursor(0, 1);
    lcd.print("Value: ");
  }
}

void handleSubMenu(char key) {
  if (key >= '0' && key <= '9') {
    if (inputBuffer.length() < 3) {
      inputBuffer += key;
      lcd.setCursor(7, 1);
      lcd.print(inputBuffer);
    }
  } else if (key == 'A') {
    // Confirm value
    subMenuValue = inputBuffer.toInt();
    lcd.setCursor(0, 2);
    lcd.print("Confirmed: ");
    lcd.println(subMenuValue);
    inputBuffer = "";
  } else if (key == 'B') {
    // Correct value
    if (inputBuffer.length() > 0) {
      inputBuffer = inputBuffer.substring(0, inputBuffer.length() - 1);
      lcd.setCursor(7, 1);
      lcd.print(inputBuffer);
      lcd.print("   ");
    }
  } else if (key == 'D') {
    // Exit submenu
    currentMenu = 0;
    inputBuffer = "";
    lcd.clear();
    lcd.print("Menu: A B C D");
  }
}
```

This code initializes the keypad and LCD screen, then waits for input. When a key is pressed in the main menu, it changes to the appropriate sub-menu. Then, it takes input for the desired value, confirms with the "A" key, corrects with the "B" key, and exits the submenu with the "D" key.

