@Composable
fun AlbumDetailItem(song: Song, navController: NavController) {
    val context = LocalContext.current
    val (player, setPlayer) = rememberSaveable { mutableStateOf<SimpleExoPlayer?>(null) }
    DisposableEffect(Unit) {
        onDispose {
            player?.stop()
            player?.release()
        }
    }
    Row(
        modifier = Modifier
            .padding(horizontal = 16.dp, vertical = 8.dp)
            .background(
                color = Color.Black.copy(alpha = 0.5f),
                shape = RoundedCornerShape(8.dp)
            )
            .border(
                width = 1.dp,
                color = Color.LightGray,
                shape = RoundedCornerShape(8.dp)
            )
            .clickable(onClick = {
                playPreview(context, song.preview, onPlayerCreated = { createdPlayer ->
                    setPlayer(createdPlayer)
                })
            })
    ) {
        Column(
            modifier = Modifier
                .weight(1f)
                .padding(start = 16.dp)
                .align(Alignment.CenterVertically)
        ) {
            Text(
                text = song.title ?: "Unknown title",
            style = MaterialTheme.typography.subtitle1,
            color = Color.White
            )
            Text(
                text = "${song.duration}" ?: "Unknown duration",
            style = MaterialTheme.typography.caption,
            color = Color.White
            )
        }
    }
}

private fun playPreview(
    context: Context,
    previewUrl: String,
    onPlayerCreated: (SimpleExoPlayer) -> Unit
) {
    val player = SimpleExoPlayer.Builder(context).build()
    val mediaItem = MediaItem.fromUri(previewUrl)
    player.setMediaItem(mediaItem)
    player.prepare()
    player.playWhenReady = true
    onPlayerCreated(player)

    // Stop playing after 30 seconds
    player.seekTo(30000)
    player.addListener(object : Player.Listener {
        override fun onPositionDiscontinuity(
            oldPosition: Player.PositionInfo,
            newPosition: Player.PositionInfo,
            reason: Int
        ) {
            if (newPosition.windowIndex != oldPosition.windowIndex) {
                player.stop()
            }
        }
    })
