Here's the updated `relayMenu()` function with the changes you requested:

```cpp
void relaysMenu() {
  int relay = 0;
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Enter relay #");

  // Collect relay number (1-12)
  do {
    char key = keypad.waitForKey();
    if (key >= '1' && key <= '9' && relay * 10 + (key - '0') <= 12) {
      relay = relay * 10 + (key - '0');
      lcd.print(key);
    }
  } while (relay == 0);

  relay--; // Adjust the relay index (0-11)

  lcd.setCursor(0, 1);
  lcd.print("A:ON/OFF B:TIMER ");
  lcd.setCursor(0, 2);
  lcd.print("C:Program D:Exit ");

  bool exit = false;
  while (!exit) {
    char key = keypad.waitForKey();
    int value;

    switch (key) {
      case 'A':
        relayStates[relay] = !relayStates[relay];
        break;

      case 'B':
        value = getKeypadValue(0, 999);
        if (value > -1) {
          relayStates[relay] = 1;
          timer[relay] = value;
        }
        break;

      case 'C':
        value = getKeypadValue(0, 24);
        if (value > -1) {
          hour[relay] = value;
          value = getKeypadValue(0, 60);
          if (value > -1) {
            min[relay] = value;
            relayStates[relay] = 1;
            timer[relay] = getKeypadValue(1, 999);
          }
        }
        break;

      case 'D':
        exit = true;
        lcd.clear();
        lcd.noBacklight();
        break;
    }
  }
}

int getKeypadValue(int minVal, int maxVal) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Enter value (");
  lcd.print(minVal);
  lcd.print("-");
  lcd.print(maxVal);
  lcd.print("):");

  int value = 0;
  bool exit = false;
  while (!exit) {
    char key = keypad.waitForKey();

    if (key >= '0' && key <= '9') {
      int newVal = value * 10 + (key - '0');
      if (newVal >= minVal && newVal <= maxVal) {
        value = newVal;
        lcd.print(key);
      }
    } else if (key == '*') {
      return -1; // Cancel entry
    } else if (key == '#') {
      exit = true;
    }
  }

  return value;
}
```

I added a new helper function `getKeypadValue()`, which accepts the minimum and maximum expected input values, and then collects the input from the keypad. It's used to collect the values for timer, hour, and minute in cases 'B' and 'C'. The function returns `-1` if the input was canceled. The relay ON/OFF status is toggled in case 'A'. The display shuts down in case 'D'.

