import com.google.android.exoplayer2.MediaItem
import com.google.android.exoplayer2.SimpleExoPlayer

class PlayerViewModel : ViewModel() {
    val currentPlayer = mutableStateOf<SimpleExoPlayer?>(null)

    fun playSong(player: SimpleExoPlayer) {
        currentPlayer.value?.let {
            if (it != player) {
                it.pause()
            }
        }
        if (player.playbackState == ExoPlayer.STATE_ENDED) {
            player.seekToDefaultPosition()
        }
        player.play()
        currentPlayer.value = player
    }

    fun pauseSong() {
        currentPlayer.value?.pause()
    }

    override fun onCleared() {
        super.onCleared()
        currentPlayer.value?.release()
    }
}
