import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.physics.box2d.Body;

public class PhysicsUtils {

    public static Vector2 velocityToPosition(Body body, Vector2 target, float maxSpeed) {
        // Calculate the difference between the desired position and the body position.
        Vector2 diff = target.cpy().sub(body.getPosition());

        // Calculate the required velocity to reach the target in the next time step.
        Vector2 requiredVelocity = diff.scl(PhysicsSystem.STEP_FREQUENCY);

        // Cap the speed of the required velocity to maxSpeed.
        if (requiredVelocity.len2() > maxSpeed * maxSpeed) {
            requiredVelocity.nor().scl(maxSpeed);
        }

        // Calculate the change in velocity needed.
        Vector2 changeInVelocity = requiredVelocity.cpy().sub(body.getLinearVelocity());

        // Check if the change in velocity would cause overshooting in the next time step.
        if (changeInVelocity.len2() > diff.len2() * PhysicsSystem.STEP_FREQUENCY * PhysicsSystem.STEP_FREQUENCY) {
            // Set the change in velocity to smoothly reach the target without overshooting.
            changeInVelocity = diff.scl(PhysicsSystem.STEP_FREQUENCY * PhysicsSystem.STEP_FREQUENCY);
        }

        // Return the new velocity to be applied to the body.
        return body.getLinearVelocity().add(changeInVelocity);
    }
}
