import java.util.Random;

public class Generator {
    double[][] weights;

    public Generator(int inputSize, int outputSize) {
        weights = new double[inputSize][outputSize];
        initializeWeights();
    }

    private void initializeWeights() {
        Random rand = new Random();
        for (int i = 0; i < weights.length; i++) {
            for (int j = 0; j < weights[i].length; j++) {
                weights[i][j] = rand.nextDouble() * 2 - 1;
            }
        }
    }

    public double[][] generate(double[] input) {
        double[][] output = new double[input.length][weights[0].length];
        for (int i = 0; i < input.length; i++) {
            for (int j = 0; j < weights[i].length; j++) {
                output[i][j] = input[i] * weights[i][j];
            }
        }
        return output;
    }
}
```

2. Discriminator class:

```java
public class Discriminator {
    double[][] weights;

    public Discriminator(int inputSize, int outputSize) {
        weights = new double[inputSize][outputSize];
        initializeWeights();
    }

    private void initializeWeights() {
        Random rand = new Random();
        for (int i = 0; i < weights.length; i++) {
            for (int j = 0; j < weights[i].length; j++) {
                weights[i][j] = rand.nextDouble() * 2 - 1;
            }
        }
    }

    public double[] evaluate(double[][] input) {
        double[] output = new double[input.length];
        for (int i = 0; i < input.length; i++) {
            for (int j = 0; j < input[i].length; j++) {
                output[i] += input[i][j] * weights[i][j];
            }
            output[i] = sigmoid(output[i]);
        }
        return output;
    }

    private double sigmoid(double x) {
        return 1 / (1 + Math.exp(-x));
    }
}
