class Entity {
  constructor() {
    this.x = canvas.width;
    this.y = Math.random() * canvas.height;
    this.vx = -1 - Math.random() * 3;
    this.vy = -2 + Math.random() * 4;
    this.projectiles = [];
    this.color = "blue";
    this.jumping = false;
  }

  update(player, platforms) {
    this.x += this.vx;
    this.y += this.vy;

    platforms.forEach((platform) => {
      if (platform.collidesWith(this)) {
        this.jumping = false;
      }
    });

    if (!this.jumping) {
      this.vy = -20;
      this.jumping = true;
    } else {
      this.vy += 1;
    }

    const dx = player.x - this.x;
    const dy = player.y - this.y;
    const direction = Math.atan2(dy, dx); // calculate the angle between the entity and the player

    if (Math.random() < 0.01) {
      const speed = 4;
      const vx = Math.cos(direction) * speed;
      const vy = Math.sin(direction) * speed;
      this.projectiles.push(new Projectile(this.x, this.y, vx, vy));
    }

    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].update();
      if (
        this.projectiles[i].x < 0 ||
        this.projectiles[i].y < 0 ||
        this.projectiles[i].x > canvas.width ||
        this.projectiles[i].y > canvas.height
      ) {
        this.projectiles.splice(i, 1);
        i--;
      }
    }
  }

  draw(ctx) {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, 20, 20);
    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].draw(ctx);
    }
  }
}

