        size_t num_states = (1 << order); // 2^order
        transition_matrix_.resize(num_states, std::vector<double>(2, 0.0));
        generate_transition_matrix();
    }

    void parse_partial_links(const std::string& partial_links) {
        for (char link : partial_links) {
            if (link >= '1' && link <= '9') {
                partial_links_mask_ |= (1 << (link - '1'));
            }
        }
    }

