        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);
        for (size_t state = 0; state < transition_matrix_.size(); ++state) {
            double p = dis(gen);
            transition_matrix_[state][0] = p;
            transition_matrix_[state][1] = 1.0 - p;
        }
    }

    void print_transition_matrix() {
        std::cout << std::fixed << std::setprecision(2);
        for (size_t state = 0; state < transition_matrix_.size(); ++state) {
            std::cout << "State " << state << ": "
                      << "0 -> " << transition_matrix_[state][0] << ", "
                      << "1 -> " << transition_matrix_[state][1] << std::endl;
        }
    }

    std::vector<int> generate_data(size_t length) {
        std::vector<int> data;
        data.reserve(length);
        size_t current_state = 0;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);
        for (size_t i = 0; i < length; ++i) {
            double random_value = dis(gen);
            int next_bit = random_value < transition_matrix_[current_state][0] ? 0 : 1;
            data.push_back(next_bit);
            current_state = ((current_state << 1) | next_bit) & ((1 << order_) - 1);
            size_t masked_state = current_state & partial_links_mask_;
            current_state = masked_state;
        }
        return data;
    }

    std::vector<std::vector<double>> estimate_transition_matrix(const std::vector<int>& data) {
        std::vector<std::vector<double>> estimated_matrix(transition_matrix_.size(), std::vector<double>(2, 0.0));
        std::vector<int> state_counts(transition_matrix_.size(), 0);
        size_t current_state = 0;

        for (size_t i = 0; i < data.size() - 1; ++i) {
            int next_bit = data[i + 1];
            estimated_matrix[current_state][next_bit]++;
            state_counts[current_state]++;
            current_state = ((current_state << 1) | data[i]) & ((1 << order_) - 1);
            size_t masked_state = current_state & partial_links_mask_;
            current_state = masked_state;
        }

        for (size_t state = 0; state < estimated_matrix.size(); ++state) {
            if (state_counts[state] > 0) {
                estimated_matrix[state][0] /= state_counts[state];
                estimated_matrix[state][1] /= state_counts[state];
            }
        }

        return estimated_matrix;
    }

    void print_estimated_matrix(const std::vector<std::vector<double>>& estimated_matrix) {
        std::cout << std::fixed << std::setprecision(2);
        for (size_t state = 0; state < estimated_matrix.size(); ++state) {
            std::cout << "State " << state << ": "
                      << "0 -> " << estimated_matrix[state][0] << ", "
                      << "1 -> " << estimated_matrix[state][1] << std::endl;
        }
    }

private:
    size_t order_;
    size_t partial_links_mask_ = 0;
    std::vector<std::vector<double>> transition_matrix_;
};

