    _favorites = _favorites.value.toMutableList().apply { add(song) }
    saveFavorites() // Don't forget to save the updated list
}

fun removeFavoriteSong(song: Song) {
    _favorites = _favorites.value.toMutableList().apply { remove(song) }
    saveFavorites() // Don't forget to save the updated list
