    const gty = 1;
    this.vx = frc;
    this.vy += gty;
    this.x += this.vx;
    this.y += this.vy;
    let t = performance.now() / 1000;
    let wave = Math.sin((t * Math.PI) / this.varPeriod);
    this.vx = lerp(this.maxVx, this.minVx, (wave + 1) / 2);
    if (Math.random() < 0.01) {
      this.projs.push(new Proj(this.x, this.y, -2 - Math.random() * 6, -2 + Math.random() * 8));
    }
    for (let i = 0; i < this.projs.length; i++) {
      this.projs[i].update();
      if (
        this.projs[i].x < 0 ||
        this.projs[i].y < 0 ||
        this.projs[i].x > canvas.width ||
        this.projs[i].y > canvas.height
      ) {
