      this.pfms[i].collidesWith(this.plyr);
      this.pfms[i].x -= this.scrSpd;
    }
    for (let i = 0; i < this.ents.length; i++) {
      if (this.ents[i]) {
        this.ents[i].update(this.pfms);
        if (this.ents[i].x < 0) {
          this.ents.splice(i, 1);
