    if (this.pfms[this.pfms.length - 1].x < this.canvas.width - 200) {
      this.createRandomPfm();
    }
    this.entSpawnTmr++;
    if (this.entSpawnTmr >= 60 / this.entSpawnRate) {
      this.entSpawnTmr = 0;
      this.ents.push(new Ent());
      this.entSpawnRate += 0.001;
      this.entIncFactor += 0.001;
      this.entIncFactor = Math.min(this.entIncFactor, 0.001);
    }
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    for (let i = 0; i < this.pfms.length; i++) {
      let p = this.pfms[i];
      this.ctx.fillRect(p.x, p.y, p.w, p.h);
    }
    for (let i = 0; i < this.ents.length; i++) {
      this.ents[i].draw(this.ctx);
    }
    this.ctx.fillRect(this.plyr.x, this.plyr.y, this.plyr.w, this.plyr.h);
    requestAnimationFrame(this.update.bind(this));
  }
}

