2. Next, create the `main.js` file and set up an IndexedDB database and object store:

```javascript
let db;

function initializeIndexedDB() {
    const indexedDB = window.indexedDB || window.mozIndexedDB || window.webkitIndexedDB || window.msIndexedDB;
    const request = indexedDB.open("MyDatabase", 1);

    request.onerror = function(event) {
        console.error("Error opening IndexedDB:", event);
    };

    request.onsuccess = function(event) {
        db = event.target.result;
        console.log("IndexedDB opened successfully");

        loadDataFromIndexedDB();
    };

    request.onupgradeneeded = function(event) {
        db = event.target.result;
        db.createObjectStore("Users", { keyPath: "username" });
    };
}

function saveDataToIndexedDB(username) {
    const transaction = db.transaction(["Users"], "readwrite");
    const store = transaction.objectStore("Users");
    const userObj = { username: username };

    store.add(userObj);

    transaction.oncomplete = function() {
        alert("Your data has been saved.");
    };

    transaction.onerror = function() {
        alert("There was an error saving your data.");
    };
}

function loadDataFromIndexedDB() {
    const transaction = db.transaction(["Users"], "readonly");
    const store = transaction.objectStore("Users");
    const getRequest = store.getAll();

    getRequest.onsuccess = function(event) {
        const users = event.target.result;

        if (users.length > 0) {
            let greeting = document.createElement("p");
            greeting.innerHTML = "Welcome back, " + users[0].username + "!";
            document.body.appendChild(greeting);
        }
    };
}

document.addEventListener("DOMContentLoaded", initializeIndexedDB);

document.getElementById("dataForm").addEventListener("submit", function(event) {
    event.preventDefault();

    let username = document.getElementById("username").value;
    saveDataToIndexedDB(username);
});
```

In this example, we're using IndexedDB to store and retrieve the user's entered username just like in the previous example. The main difference is that we're using a more advanced API that allows for scalable data storage and retrieval.

Remember that IndexedDB data is stored on the client-side and may not be completely secure. As with Local Storage, do not use IndexedDB to store sensitive user information. For secure, long-term data persistence, consider using server-side technologies and databases.

