A Single Page Application (SPA) router enables navigation in your application without having to reload the page. Here's a simple SPA router using JavaScript:

1. First, create a basic HTML file with a `div` element that serves as the container for rendering your views:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>My SPA</title>
</head>
<body>
    <div id="root"></div>
    <script src="spa-router.js"></script>
</body>
</html>
```

2. Create a `spa-router.js` file that contains your routing configuration and the logic for managing routes, rendering views, and handling route changes:

```javascript
// Define routes.
const routes = [
    {
        path: '/',
        view: () => 'Home Page',
    },
    {
        path: '/about',
        view: () => 'About Page',
    },
    {
        path: '/contact',
        view: () => 'Contact Page',
    },
    {
        path: '*',
        view: () => '404 - Page Not Found',
    },
];

// Get the current path.
function getCurrentPath() {
    return window.location.pathname || '/';
}

// Find the route corresponding to the current path.
function findRouteByPath(path) {
    return (
        routes.find((route) => route.path === path) ||
        routes.find((route) => route.path === '*')
    );
}

// Render the view associated with the route.
function renderView(route) {
    const root = document.getElementById('root');
    if (!root) return;

    root.innerHTML = route.view();
}

// Set up a simple router that handles navigation.
function setupRouter() {
    window.addEventListener('popstate', () => {
        const currentPath = getCurrentPath();
        const currentRoute = findRouteByPath(currentPath);
        renderView(currentRoute);
    });
}

// Initialize the router and render the view for the first time.
function initRouter() {
    setupRouter();
    const currentPath = getCurrentPath();
    const currentRoute = findRouteByPath(currentPath);
    renderView(currentRoute);
}

// Start the router.
initRouter();
```

Now, you have a basic SPA router in place. It uses the browser history API to handle navigation without page reloads. To add new routes, simply add new route objects to the `routes` array and define their views.

To update your navigation links, you can use the following method:

```javascript
function navigateTo(path) {
    window.history.pushState(null, '', path);
    const route = findRouteByPath(path);
    renderView(route);
}
```

In your HTML, use the `navigateTo()` method for navigation:

```html
<a href="javascript:void(0);" onclick="navigateTo('/')">Home</a>
<a href="javascript:void(0);" onclick="navigateTo('/about')">About</a>
<a href="javascript:void(0);" onclick="navigateTo('/contact')">Contact</a>
```

Now, you have a simple SPA router set up using JavaScript.

To expand upon the SPA router, you can integrate dynamic routes, create view components, and handle more complex route configurations. Here's an example of how to create a more advanced SPA router:

1. Update the `routes` array to include a dynamic route with a URL parameter (e.g., '/post/:id'):

```javascript
const routes = [
    //... other routes
    {
        path: '/post/:id',
        view: ({ id }) => `Post Page: ${id}`,
    },
];
```

2. Modify the `findRouteByPath()` function to support URL parameters:

```javascript
function findRouteByPath(path) {
    for (const route of routes) {
        const paramKeys = [];
        const pattern = route.path
            .replace(/([:*])(\w+)/g, (_, type, key) => {
                paramKeys.push(key);
                return type === ':' ? '([^/]+)' : '(.+)';
            })
            .concat('/?');
        const regex = new RegExp(`^${pattern}$`, 'i');
        const paramValues = path.match(regex);
        if (paramValues) {
            const params = paramKeys.reduce(
                (acc, key, index) => ({ ...acc, [key]: paramValues[index + 1] }),
                {}
            );
            return { ...route, params };
        }
    }
    return routes.find((route) => route.path === '*');
}
```

3. Update the `renderView()` function to pass route parameters to the view:

```javascript
function renderView(route) {
    const root = document.getElementById('root');
    if (!root) return;

    root.innerHTML = route.view(route.params || {});
}
```

4. Create a new function `createLink()` to simplify creating navigation links:

```javascript
function createLink(path, text) {
    const link = document.createElement('a');
    link.href = 'javascript:void(0);';
    link.onclick = () => navigateTo(path);
    link.textContent = text;
    return link;
}
```

5. Use the `createLink()` function to dynamically generate navigation links in your HTML:

```javascript
const nav = document.getElementById('nav');
nav.appendChild(createLink('/', 'Home'));
nav.appendChild(createLink('/about', 'About'));
nav.appendChild(createLink('/contact', 'Contact'));
```

6. Replace the view functions in the `routes` array with functions that return HTML elements:

```javascript
const routes = [
    {
        path: '/',
        view: () => {
            const container = document.createElement('div');
            container.textContent = 'Home Page';
            return container;
        },
    },
    {
        path: '/about',
        view: () => {
            const container = document.createElement('div');
