Here's a C++ implementation of a program that calculates the global clustering coefficient for an undirected graph given its adjacency matrix. The program uses the boost library for handling the adjacency matrix and applying the required operations. You can install the boost library and link it to your compiler by following the instructions here: https://www.boost.org/doc/libs/1_77_0/more/getting_started/windows.html

```cpp
#include <iostream>
#include <vector>
#include <boost/numeric/ublas/matrix.hpp>
#include <boost/numeric/ublas/io.hpp>

using namespace std;
using namespace boost::numeric::ublas;

// Helper function for matrix multiplication
matrix<int> multiply_matrix(const matrix<int>& A, const matrix<int>& B) {
    assert(A.size2() == B.size1());
    matrix<int> C(A.size1(), B.size2());

    for (size_t i = 0; i < A.size1(); ++i)
        for (size_t j = 0; j < B.size2(); ++j)
            for (size_t k = 0; k < A.size2(); ++k)
                C(i, j) += A(i, k) * B(k, j);

    return C;
}

double global_clustering_coefficient(const matrix<int>& adjacency_matrix) {
    int total_triangles = 0;
    int total_connected_triples = 0;
    int n_nodes = adjacency_matrix.size1();

    // Calculate adjacency_matrix^3
    matrix<int> A3 = multiply_matrix(multiply_matrix(adjacency_matrix, adjacency_matrix), adjacency_matrix);

    // Count triangles
    for (size_t i = 0; i < n_nodes; i++) {
        total_triangles += A3(i, i);
    }
    total_triangles /= 6;

    // Count connected triples
    for (size_t i = 0; i < n_nodes; i++) {
        int degree = 0;
        for (size_t j = 0; j < n_nodes; j++) {
            degree += adjacency_matrix(i, j);
        }

        total_connected_triples += (degree * (degree - 1)) / 2;
    }
    total_connected_triples -= 3 * total_triangles;

    if (total_connected_triples == 0) {
        return 0.0;
    }

    return 3.0 * total_triangles / total_connected_triples;
}

int main() {
    // Example adjacency matrix for an undirected graph
    matrix<int> adjacency_matrix(5, 5);
    adjacency_matrix(0, 1) = 1; adjacency_matrix(1, 0) = 1;
    adjacency_matrix(1, 2) = 1; adjacency_matrix(2, 1) = 1;
    adjacency_matrix(1, 3) = 1; adjacency_matrix(3, 1) = 1;
    adjacency_matrix(2, 3) = 1; adjacency_matrix(3, 2) = 1;
    adjacency_matrix(2, 4) = 1; adjacency_matrix(4, 2) = 1;
    adjacency_matrix(3, 4) = 1; adjacency_matrix(4, 3) = 1;

    double gcc = global_clustering_coefficient(adjacency_matrix);
    cout << "Global Clustering Coefficient: " << gcc << endl;

    return 0;
}
```

You can modify the adjacency_matrix variable to match your input network. The program calculates the global clustering coefficient for the given undirected graph and displays its value in the output.

Note that this code assumes that the graph is undirected and there are no self-loops or multiple edges between nodes. Ensure that the boost library is properly installed and linked to compile and run the code.

