```

Sign up for a Stripe account (if you don't have one) and obtain your API key from the dashboard.

Create a Stripe service `src/stripe/stripe.service.ts`:

```typescript
import { Injectable } from '@nestjs/common';
import Stripe from 'stripe';

@Injectable()
export class StripeService {
  private stripe: Stripe;

  constructor() {
    this.stripe = new Stripe('your_stripe_secret_key', {
      apiVersion: '2020-08-27',
    });
  }

  async createCheckoutSession(
    lineItems: Stripe.Checkout.SessionCreateParams.LineItem[],
  ): Promise<Stripe.Checkout.Session> {
    const session = await this.stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: lineItems,
      mode: 'payment',
      success_url: 'https://your-success-url',
      cancel_url: 'https://your-cancel-url',
    });

    return session;
  }
}
```

