4. Make a request from your Next.js frontend to create a checkout

Install the necessary packages:

```bash
npm install --save @apollo/client graphql
```

Add a call to the `createCheckoutSession` mutation in your Next.js frontend using the Apollo Client:

```javascript
import { gql, useMutation } from '@apollo/client';

const CREATE_CHECKOUT_SESSION = gql`
  mutation CreateCheckoutSession($lineItems: [LineItemInput]) {
    createCheckoutSession(lineItems: $lineItems)
  }
`;

function CheckoutButton() {
  const [createCheckoutSession] = useMutation(CREATE_CHECKOUT_SESSION);

  const handleCheckout = async () => {
    const { data } = await createCheckoutSession({
      variables: {
        lineItems: [
          {
            name: 'Product Name',
            description: 'Product Description',
            amount: 500, // Amount in cents
            currency: 'usd',
            quantity: 1,
          },
        ],
      },
    });
    const sessionId = data.createCheckoutSession;

    // Redirect to Stripe Checkout
    const stripe = Stripe('your_stripe_publishable_key');
    stripe.redirectToCheckout({ sessionId });
  };

  return <button onClick={handleCheckout}>Checkout</button>;
}
```

