import { Injectable } from '@nestjs/common';
import { Inject } from '@nestjs/common/decorators/core/component.decorators';
import Stripe from 'stripe';

@Injectable()
export class CheckoutService {
  constructor(@Inject('STRIPE') private readonly stripe: Stripe) {}

  async createCheckoutSession(
    season: 'low' | 'mid' | 'high',
    bookingDays: number,
  ): Promise<Stripe.Checkout.Session> {
    // Replace these with your actual price IDs from Stripe Dashboard
    const priceIds: Record<string, string> = {
      low: 'price_LOW_SEASON_ID',
      mid: 'price_MID_SEASON_ID',
      high: 'price_HIGH_SEASON_ID',
    };

    const selectedPriceId = priceIds[season];

    const session = await this.stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      mode: 'payment',
      metadata: { price_id: selectedPriceId },
      line_items: [
        {
          price: selectedPriceId,
          quantity: bookingDays, // Using bookingDays as quantity
        },
      ],
      success_url: 'https://example.com/success',
      cancel_url: 'https://example.com/cancel',
    });

    return session;
  }
}

