import java.util.List;
enum WashProgram {
SNEL,
DELICAAT,
KATOEN,
ECO,
WARM
}
class WashingMachine {
private boolean on;
private boolean inUse;
private int capacity;
private List<ClothingItem> clothingItems;

public WashingMachine(int capacity) {
this.on = false;
this.inUse = false;
this.capacity = capacity;
this.clothingItems = new ArrayList<>();
}

public boolean isOn() {
return on;
}

public void turnOn() {
this.on = true;
}

public void turnOff() {
this.on = false;
this.inUse = false;
this.clothingItems.clear();
}

public boolean start(WashProgram program, int temperature, int duration) {
if (!on || inUse) {
return false;
}

// Start het wasprogramma met de gegeven instellingen
System.out.println("Washing machine started. Program: " + program + ", Temperature: " + temperature + ", Duration: " + duration);
this.inUse = true;
return true;
}

public boolean addClothingItem(ClothingItem item) {
if (!on || inUse || clothingItems.contains(item) || getLoad() + item.getWeight() > capacity) {
return false;
}

clothingItems.add(item);
return true;
}

public boolean removeClothingItem(ClothingItem item) {
if (!on || inUse) {
return false;
}

return clothingItems.remove(item);
}

public void finish() {
this.inUse = false;
this.clothingItems.clear();
}

public double getLoad() {
double load = 0;
for (ClothingItem item : clothingItems) {
load += item.getWeight();
}
return load;
}
public int getCapacity() {
return capacity;
}
