Вот пример реализации своего класса HashMap на языке Java с указанными методами:

```java
import java.util.*;

public class MyHashMap<K, V> {

    private static final int INITIAL_CAPACITY = 16;
    private static final float LOAD_FACTOR = 0.75f;
    private int size;
    private Entry<K, V>[] table;

    public MyHashMap() {
        table = new Entry[INITIAL_CAPACITY];
    }

    public void put(K key, V value) {
        int index = indexForKey(key);
        Entry<K, V> entry = table[index];
        while (entry != null) {
            if (key.equals(entry.key)) {
                entry.value = value;
                return;
            }
            entry = entry.next;
        }

        table[index] = new Entry<>(key, value, table[index]);
        size++;

        if (size >= table.length * LOAD_FACTOR) {
            resize();
        }
    }

    public V get(K key) {
        int index = indexForKey(key);
        Entry<K, V> entry = table[index];
        while (entry != null) {
            if (key.equals(entry.key)) {
                return entry.value;
            }
            entry = entry.next;
        }
        return null;
    }

    public Set<K> keySet() {
        Set<K> keys = new HashSet<>();
        for (Entry<K, V> entry : table) {
            while (entry != null) {
                keys.add(entry.key);
                entry = entry.next;
            }
        }
        return keys;
    }

    public Collection<V> values() {
        List<V> values = new ArrayList<>();
        for (Entry<K, V> entry : table) {
            while (entry != null) {
                values.add(entry.value);
                entry = entry.next;
            }
        }
        return values;
    }

    public boolean containsKey(K key) {
        int index = indexForKey(key);
        Entry<K, V> entry = table[index];
        while (entry != null) {
            if (key.equals(entry.key)) {
                return true;
            }
            entry = entry.next;
        }
        return false;
    }

    public boolean containsValue(V value) {
        for (Entry<K, V> entry : table) {
            while (entry != null) {
                if (value.equals(entry.value)) {
                    return true;
                }
                entry = entry.next;
            }
        }
        return false;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public V remove(K key) {
        int index = indexForKey(key);
        Entry<K, V> prev = null;
        Entry<K, V> entry = table[index];

        while (entry != null) {
            if (key.equals(entry.key)) {
                if (prev == null) {
                    table[index] = entry.next;
                } else {
                    prev.next = entry.next;
                }
                size--;
                return entry.value;
            }
            prev = entry;
            entry = entry.next;
        }
        return null;
    }

    public int size() {
        return size;
    }

    public void clear() {
        Arrays.fill(table, null);
        size = 0;
    }

    private int indexForKey(K key) {
        int hash = key.hashCode() % table.length;
        return hash < 0 ? hash + table.length : hash;
    }

    private void resize() {
        Entry<K, V>[] newTable = new Entry[table.length * 2];
        System.arraycopy(table, 0, newTable, 0, table.length);
        table = newTable;
    }

    private static class Entry<K, V> {
        K key;
        V value;
        Entry<K, V> next;

        public Entry(K key, V value, Entry<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    public static void main(String[] args) {
        MyHashMap<String, Integer> map = new MyHashMap<>();
        map.put("One", 1);
        map.put("Two", 2);
        map.put("Three", 3);

        System.out.println("Size: " + map.size()); // Size: 3
        System.out.println("Value of key 'One': " + map.get("One")); // Value of key 'One': 1
        System.out.println("Contains key 'Two': " + map.containsKey('Two')); // Contains key 'Two': true
        System.out.println("Contains value 3: " + map.containsValue(3)); // Contains value 3: true
        System.out.println("Keys: " + map.keySet()); // Keys: [Three, One, Two]
        System.out.println("Values: " + map.values()); // Values: [3, 1, 2]

        map.remove("Three");
        System.out.println("Size after remove: " + map.size()); // Size after remove: 2
        map.clear();
        System.out.println("Size after clear: " + map.size()); // Size after clear: 0
    }
}
```

Здесь был использован метод открытой адресации в качестве коллизионного разрешения. Класс MyHashMap реализует методы put, get, keySet, values, containsKey, containsValue, isEmpty, remove, size и clear, как и было указано в задании.

