#include <set>

class Node {
public:
    int id;
    std::vector<Node*> neighbours;

    Node(int id) : id(id) {}

    void addNeighbour(Node* node) {
        neighbours.push_back(node);
    }
};

double findGlobalClusteringCoefficient(const std::vector<Node*>& component) {
    int triangles = 0;
    int triples = 0;

    for (Node* node : component) {
        std::set<int> neighbourIds;
        for (Node* neighbour : node->neighbours) {
            neighbourIds.insert(neighbour->id);
        }

        int nodeTriangles = 0;
        for (Node* neighbour : node->neighbours) {
            int commonNeighbours = 0;
            for (Node* nextNeighbour : neighbour->neighbours) {
                if(neighbourIds.count(nextNeighbour->id)){
                    commonNeighbours++;
                }
            }
            nodeTriangles += commonNeighbours;
        }

        triangles += nodeTriangles / 2;
        triples += (node->neighbours.size() * (node->neighbours.size() - 1)) / 2;
    }

    if (triples == 0) {
        return 0.0;
    }

    return static_cast<double>(triangles) / triples;
}

