```c++
#include <bits/stdc++.h>
using namespace std;

const int N = 100;

vector<int> g[N];
bool vis[N];

void dfs(int u) {
    vis[u] = true;
    for (int v : g[u]) {
        if (!vis[v]) {
            dfs(v);
        }
    }
}

bool is_connected(int n) {
    memset(vis, false, sizeof(vis));
    dfs(0);
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            return false;
        }
    }
    return true;
}

void connected_components(int n) {
    memset(vis, false, sizeof(vis));
    int comp = 0;
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            comp++;
            dfs(i);
            cout << "Component " << comp << ": ";
            for (int j = 0; j < n; j++) {
                if (vis[j]) {
                    cout << j << " ";
                }
            }
            cout << endl;
        }
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    if (is_connected(n)) {
        cout << "The graph is connected." << endl;
        cout << "Connected components:" << endl;
        connected_components(n);
    } else {
        cout << "The graph is not connected." << endl;
    }
    return 0;
}
```

This code first checks if the graph is connected using a DFS traversal, and then finds the connected components by running DFS from each unvisited vertex. The `g` vector represents the adjacency list of the graph. The `is_connected` function returns `true` if and only if all vertices can be reached from vertex 0. The `connected_components` function prints the indices of the vertices in each connected component.

