        $sql = "INSERT INTO `{$wp_prefix}cashback_transactions` (
                                `id`,
                                `merchant_transaction_id`,
                                `user`,
                                `store`,
                                `source`,
                                `transaction_amount`,
                                `commission_amount`,
                                `transaction_status`,
                                `transaction_date`,
                                `cashback_amount`,
                                `comment`
                            ) VALUES (
