In this example, we will create a Bluetooth GATT server application using BlueZ, which is the official Linux Bluetooth protocol stack. In this example, the GATT server will send a binary file in chunks (blobs) to a connected GATT client.

Prerequisites:
- BlueZ with GATT support (version >= 5.40)
- GCC and pkg-config for compilation
- A Bluetooth GATT client such as a smartphone app or another computer running a GATT client application

1. First, create the header file "btgatt_server.h":

```c
#ifndef BTGATT_SERVER_H_
#define BTGATT_SERVER_H_

#include <stdbool.h>

void btgatt_server_start(const char *filename);

#endif /* BTGATT_SERVER_H_ */
```

2. Next, create the C file "btgatt_server.c":

```c
#include <unistd.h>
#include <fcntl.h>
#include <glib.h>
#include <stdio.h>
#include <bluetooth/bluetooth.h>
#include <bluetooth/hci.h>
#include <bluetooth/hci_lib.h>
#include <bluetooth/l2cap.h>
#include "btgatt_server.h"

#define GATT_MTU 23

static guint blob_read_cb(const gchar *label, guchar *buf, guint16 offset) {
    (void) label;
    int fd = *(int *)(buf);
    guint16 len = GATT_MTU;

    if (lseek(fd, offset, SEEK_SET) == -1)
        return -ENOENT;

    len = (guint16)read(fd, buf, len);

    return len;
}

void btgatt_server_start(const char *filename) {
    struct gatt_db_attribute *service, *blob;
    struct bt_att *att;
    int fd;

    fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open file");
        return;
    }

    service = gatt_db_add_service(gatt_db, GATT_SERV_UUID_BLOB_TRANSFER, true, 1);
    if (!service) {
        fprintf(stderr, "Failed to create Blob Transfer service.\n");
        return;
    }

    blob = bt_gatt_add_descriptor(bt_gatt, service, GATT_DESC_UUID_BLOB, BD_GATT_PERM_READ, blob_read_cb, NULL);
    if (!blob) {
        fprintf(stderr, "Failed to create Blob descriptor.\n");
        return;
    }

    gatt_db_attribute_write_value(blob, (void*)&fd, sizeof(fd));
}
```

3. Now, create a `Makefile` to compile your program:

```
all: btgatt_server

btgatt_server: btgatt_server.o main.o
    gcc btgatt_server.o main.o -o btgatt_server -lbluetooth -lglib -lgatt -I/usr/include/glib-2.0 -I/usr/lib/glib-2.0/include -I/usr/include/dbus

btgatt_server.o: btgatt_server.c btgatt_server.h
    gcc -c btgatt_server.c -o btgatt_server.o

main.o: main.c btgatt_server.h
    gcc -c main.c -o main.o

clean:
    rm -rf *.o btgatt_server
```

4. Create a simple C file called `main.c` as your main entry point:

```c
#include <stdio.h>
#include "btgatt_server.h"

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    btgatt_server_start(argv[1]);

    return 0;
}
```

5. Compile the program:

```bash
$ make
```

6. Run the compiled `btgatt_server` application, passing the path to the binary file you want to send as the first argument:

```bash
$ sudo ./btgatt_server <filename>
```

Now you have a GATT server that can send a binary file in chunks (blobs) to a connected GATT client.

Remember to run a Bluetooth GATT client on your smartphone, or another computer to connect to the server and request the file.

If you need additional functionality in your GATT server, the BlueZ project provides further documentation and examples. You can find them here: https://git.kernel.org/pub/scm/bluetooth/bluez.git/tree

