LRESULT CALLBACK WndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);

LocalClipboardWindow::LocalClipboardWindow()
    : m_hwnd(NULL), m_next_viewer(NULL)
{
}

LocalClipboardWindow::~LocalClipboardWindow()
{
    if (m_hwnd != NULL)
        DestroyWindow(m_hwnd);
}

bool LocalClipboardWindow::init()
{
    HINSTANCE hInstance = GetModuleHandle(NULL);

    WNDCLASSEX wcex = { sizeof(WNDCLASSEX) };

    wcex.style          = CS_HREDRAW | CS_VREDRAW;
    wcex.lpfnWndProc    = WndProc;
    wcex.hInstance      = hInstance;
    wcex.hCursor        = LoadCursor(NULL, IDC_ARROW);
    wcex.hbrBackground  = (HBRUSH)(COLOR_WINDOW + 1);
    wcex.lpszClassName  = _T("LocalClipboardWindowClass");

    if (!RegisterClassEx(&wcex))
    {
        printf("Error: RegisterClassEx failed (%d)\n", GetLastError());
        return false;
    }

    m_hwnd = CreateWindowEx(
        WS_EX_TOOLWINDOW | WS_EX_TOPMOST | WS_EX_LAYERED,
        wcex.lpszClassName,
        _T("Local Clipboard"),
        WS_POPUP,
        0, 0, 0, 0,
        NULL, NULL, hInstance, NULL);

    if (m_hwnd == NULL)
    {
        printf("Error: CreateWindowEx failed (%d)\n", GetLastError());
        return false;
    }

    SetLayeredWindowAttributes(m_hwnd, RGB(0, 0, 0), 200, LWA_ALPHA);
    ShowWindow(m_hwnd, SW_SHOW);

    m_next_viewer = SetClipboardViewer(m_hwnd);

    return true;
}

bool LocalClipboardWindow::run()
{
    MSG msg = { 0 };

    while (GetMessage(&msg, NULL, 0, 0))
    {
        if (msg.message == WM_DESTROYCLIPBOARD)
        {
            // Remote clipboard has changed, send the new data over the network
            HANDLE hData = GetClipboardData(CF_UNICODETEXT);
            WCHAR* pText = (WCHAR*)GlobalLock(hData);
            size_t size = (wcslen(pText) + 1) * sizeof(WCHAR);

            // TODO: Send clipboard data over the network...

            GlobalUnlock(hData);

            EmptyClipboard();
            OpenClipboard(m_hwnd);
            SetClipboardData(CF_UNICODETEXT, nullptr); // Clear local clipboard
            CloseClipboard();
        }
        else if (msg.message == WM_DRAWCLIPBOARD)
        {
            // Another window has changed the clipboard, update the local clipboard
            SendMessage(m_next_viewer, msg.message, msg.wParam, msg.lParam);
            OpenClipboard(m_hwnd);
            SetClipboardData(CF_UNICODETEXT, nullptr); // Clear local clipboard
            HANDLE hData = GetClipboardData(CF_UNICODETEXT);
            WCHAR* pText = (WCHAR*)GlobalLock(hData);

            // TODO: Update local clipboard contents based on remote clipboard data...

            GlobalUnlock(hData);
            CloseClipboard();
        }
        else
        {
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }
    }

    return true;
}

LRESULT CALLBACK WndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    if (message == WM_CREATE)
    {
        return 0;
    }
    else if (message == WM_DESTROY)
    {
        PostQuitMessage(0);
    }

    return DefWindowProc(hwnd, message, wParam, lParam);
}

