```javascript
const numRows = 6;
const numCols = 7;
const winningLength = 4; // Change this to a higher number for a more difficult game

let currentPlayer = 1;
let gameState = Array.from({ length: numRows }, () => Array(numCols).fill(null));

function createBoard() {
    const board = document.getElementById("board");
    for (let row = 0; row < numRows; row++) {
        const rowDiv = document.createElement("div");
        for (let col = 0; col < numCols; col++) {
            const cell = document.createElement("div");
            cell.className = "cell";
            cell.addEventListener("click", () => onCellClicked(row, col));
            rowDiv.appendChild(cell);
        }
        board.appendChild(rowDiv);
    }
}

function onCellClicked(row, col) {
    if (gameState[row][col] !== null) return;

    let targetRow = row;
    while (targetRow < numRows - 1 && gameState[targetRow + 1][col] === null) {
        targetRow++;
    }

    gameState[targetRow][col] = currentPlayer;
    updateCell(targetRow, col);

    if (isWinningMove(targetRow, col)) {
        setTimeout(() => alert(`Player ${currentPlayer} wins!`), 100);
    } else {
        currentPlayer = 3 - currentPlayer; // Switches between 1 and 2
    }
}

function updateCell(row, col) {
    const cell = document.getElementById("board").children[row].children[col];
    cell.setAttribute("data-player", gameState[row][col]);
}

function isWinningMove(row, col) {
    const directions = [
        { dr: -1, dc: 0 },
        { dr: -1, dc: 1 },
        { dr: 0, dc: 1 },
        { dr: 1, dc: 1 },
    ];
    for (const { dr, dc } of directions) {
        let count = 1;
        for (let factor = -1; factor <= 1; factor += 2) {
            for (
                let r = row + factor * dr, c = col + factor * dc;
                r >= 0 &&
                r < numRows &&
                c >= 0 &&
                c < numCols &&
                gameState[r][c] === currentPlayer;
                r += factor * dr, c += factor * dc
            ) {
                count++;
            }
        }
        if (count >= winningLength) return true;
    }
    return false;
}

// Initialize the game
createBoard();
```

