  id: 'user',
  initial: 'idle',
  states: {
    idle: {
      on: {
        FETCH_USER: 'loading',
      },
    },
    loading: {
      invoke: {
        src: 'fetchUser',
        onDone: {
          target: 'loaded',
          actions: ['setUser'],
        },
        onError: {
          target: 'error',
        },
