    private URI getSiteUrl(Integer luminateSiteId) {
        LegacyTenant tenant = legacyTenantClient.find(luminateSiteId);
        if (tenant == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "The specified site id does not exist.");
        }
        tenant.getSiteDomains().sort(Comparator.comparing(com.blackbaud.tenants.api.SiteDomain::getPriority));
        com.blackbaud.tenants.api.SiteDomain siteDomain = tenant.getSiteDomains().get(0);
        String siteUrl = "https://" + siteDomain.getSecureDomain() + siteDomain.getSecurePath();
        if (legacyTenantClient instanceof StubLegacyTenantClient) {
            siteUrl = siteDomain.getSecureDomain() + "/site";
        }
        try {
            return new URI(siteUrl);
        } catch (URISyntaxException e) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Incorrect site url format: " + siteUrl);
        }
    }

