Next, we can add a basic cryptocurrency by adding a `Transaction` class to the `Block` class. Each block can contain a vector of transactions that represent all the transactions that took place during that block. 

```c++
#include <iostream>
#include <vector>

using namespace std;

class Transaction {
public:
    string fromAddress;
    string toAddress;
    float amount;

    Transaction(string fromAddress, string toAddress, float amount) {
        this->fromAddress = fromAddress;
        this->toAddress = toAddress;
        this->amount = amount;
    }
};

class Block {
public:
    int index;
    vector<Transaction> transactions;
    string previousHash;
    string hash;

    Block(int index, vector<Transaction> transactions, string previousHash) {
        this->index = index;
        this->transactions = transactions;
        this->previousHash = previousHash;
        this->hash = calculateHash();
    }

    string calculateHash() {
        string transactionString;
        for (Transaction transaction : transactions) {
            transactionString += transaction.toAddress + to_string(transaction.amount);
        }
        return to_string(index) + transactionString + previousHash; // This is a simple hash function
    }
};

class Blockchain {
public:
    vector<Block> chain;
    vector<Transaction> pendingTransactions;
    float miningReward = 100; // Reward for mining a block

    Blockchain() {
        // Create the first block (genesis block)
        chain.emplace_back(Block(0, vector<Transaction>(), "0"));
    }

    void minePendingTransactions(string minerAddress) {
        Block previousBlock = chain.back(); // Get the last block in the chain
        int newIndex = previousBlock.index + 1;
        string previousHash = previousBlock.hash;

        // Add a transaction to the miner's address as a reward
        pendingTransactions.emplace_back(Transaction("", minerAddress, miningReward));

        Block newBlock(newIndex, pendingTransactions, previousHash);
        chain.emplace_back(newBlock);

        pendingTransactions.clear();
    }

    void createTransaction(Transaction transaction) {
        pendingTransactions.emplace_back(transaction);
    }

    float getBalance(string address) {
        float balance = 0;
        for (Block block : chain) {
            for (Transaction transaction : block.transactions) {
                if (transaction.fromAddress == address) {
                    balance -= transaction.amount;
                }
                if (transaction.toAddress == address) {
                    balance += transaction.amount;
                }
            }
        }
        return balance;
    }
};

int main() {
    Blockchain blockchain;

    blockchain.createTransaction(Transaction("address1", "address2", 10));
    blockchain.createTransaction(Transaction("address2", "address1", 5));

    cout << "Balance of address1: " << blockchain.getBalance("address1") << endl;
    cout << "Balance of address2: " << blockchain.getBalance("address2") << endl;

    blockchain.minePendingTransactions("miner1");

    cout << "Current block reward: " << blockchain.miningReward << endl;
    cout << "Balance of miner1: " << blockchain.getBalance("miner1") << endl;

    blockchain.createTransaction(Transaction("address1", "address2", 5));
    blockchain.createTransaction(Transaction("address2", "address1", 3));

    blockchain.minePendingTransactions("miner2");

    cout << "Current block reward: " << blockchain.miningReward << endl;
    cout << "Balance of miner2: " << blockchain.getBalance("miner2") << endl;

    return 0;
}
```

This code adds a `Transaction` class that represents a single transaction. The `Block` class now contains a vector of transactions. The `Blockchain` class also contains a vector of `pendingTransactions` that are waiting to be added to a future block. 

The `minePendingTransactions` function adds a new block to the chain with all the pending transactions, plus a reward for the miner who mined the block. Each transaction also deducts the relevant amount from the sender's balance and adds it to the receiver's balance.

In this code, we also added a `getBalance` function that calculates the current balance of an address by looping through all the blocks in the chain and all the transactions in each block. 

