```java
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.AdapterView;
import android.widget.GridView;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.navigation.fragment.NavHostFragment;

public class GridFragment extends Fragment {

    GridView gridView;

    // Sample drawable image names
    String[] names = new String[]{
        "Flower", "Animal", "Book", "Computer", "Guitar", "Painting", "Speaker", "Television"
    };

    // Sample drawable image resource IDs
    int[] resourceIds = new int[]{
        R.drawable.flower, R.drawable.animal, R.drawable.book, R.drawable.computer,
        R.drawable.guitar, R.drawable.painting, R.drawable.speaker, R.drawable.television
    };

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_grid, container, false);
    }

    public void onViewCreated(@NonNull View view, Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        gridView = (GridView) view.findViewById(R.id.gridView);

        gridView.setAdapter(new CustomGridAdapter(getContext(), names, resourceIds));

        gridView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                NavHostFragment.findNavController(GridFragment.this)
                    .navigate(R.id.action_GridFragment_to_DetailFragment);
