Here's a sample Java code to perform addition, subtraction, and multiplication of two polynomials using LinkedList:

```java
import java.util.LinkedList;
import java.util.Scanner;

class Term {
    int coef;
    int exp;

    public Term(int coef, int exp) {
        this.coef = coef;
        this.exp = exp;
    }
}

public class PolynomialOperations {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the number of terms in the first polynomial:");
        int terms1 = scanner.nextInt();
        LinkedList<Term> poly1 = new LinkedList<>();

        System.out.println("Enter the coef and exp of each term for the first polynomial:");
        for (int i = 0; i < terms1; i++) {
            poly1.add(new Term(scanner.nextInt(), scanner.nextInt()));
        }

        System.out.println("Enter the number of terms in the second polynomial:");
        int terms2 = scanner.nextInt();
        LinkedList<Term> poly2 = new LinkedList<>();

        System.out.println("Enter the coef and exp of each term for the second polynomial:");
        for (int i = 0; i < terms2; i++) {
            poly2.add(new Term(scanner.nextInt(), scanner.nextInt()));
        }

        LinkedList<Term> sum = add(poly1, poly2);
        LinkedList<Term> diff = subtract(poly1, poly2);
        LinkedList<Term> product = multiply(poly1, poly2);

        System.out.println("Sum of polynomials: " + displayPoly(sum));
        System.out.println("Difference of polynomials: " + displayPoly(diff));
        System.out.println("Product of polynomials: " + displayPoly(product));
    }

    public static LinkedList<Term> add(LinkedList<Term> poly1, LinkedList<Term> poly2) {
        LinkedList<Term> result = new LinkedList<>();

        int i = 0, j = 0;
        while (i < poly1.size() || j < poly2.size()) {
            if (i >= poly1.size()) {
                result.add(poly2.get(j++));
            } else if (j >= poly2.size()) {
                result.add(poly1.get(i++));
            } else if (poly1.get(i).exp > poly2.get(j).exp) {
                result.add(poly1.get(i++));
            } else if (poly1.get(i).exp < poly2.get(j).exp) {
                result.add(poly2.get(j++));
            } else {
                int coefSum = poly1.get(i).coef + poly2.get(j).coef;
                result.add(new Term(coefSum, poly1.get(i).exp));
                i++;
                j++;
            }
        }
        return result;
    }

    public static LinkedList<Term> subtract(LinkedList<Term> poly1, LinkedList<Term> poly2) {
        LinkedList<Term> result = new LinkedList<>();

        int i = 0, j = 0;
        while (i < poly1.size() || j < poly2.size()) {
            if (i >= poly1.size()) {
                result.add(new Term(-poly2.get(j).coef, poly2.get(j).exp));
                j++;
            } else if (j >= poly2.size()) {
                result.add(poly1.get(i++));
            } else if (poly1.get(i).exp > poly2.get(j).exp) {
                result.add(poly1.get(i++));
            } else if (poly1.get(i).exp < poly2.get(j).exp) {
                result.add(new Term(-poly2.get(j).coef, poly2.get(j).exp));
                j++;
            } else {
                int coefDiff = poly1.get(i).coef - poly2.get(j).coef;
                result.add(new Term(coefDiff, poly1.get(i).exp));
                i++;
                j++;
            }
        }
        return result;
    }

    public static LinkedList<Term> multiply(LinkedList<Term> poly1, LinkedList<Term> poly2) {
        LinkedList<Term> result = new LinkedList<>();

        for (Term t1 : poly1) {
            for (Term t2 : poly2) {
                int coefProd = t1.coef * t2.coef;
                int expSum = t1.exp + t2.exp;
                Term newTerm = new Term(coefProd, expSum);

                boolean inserted = false;
                for (int i = 0; i < result.size(); i++) {
                    if (result.get(i).exp == expSum) {
                        result.get(i).coef += coefProd;
                        inserted = true;
                        break;
                    } else if (result.get(i).exp < expSum) {
                        result.add(i, newTerm);
                        inserted = true;
                        break;
                    }
                }
                if (!inserted) {
                    result.add(newTerm);
                }
            }
        }
        return result;
    }

    public static String displayPoly(LinkedList<Term> poly) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < poly.size(); i++) {
            if (poly.get(i).coef == 0) {
                continue;
            }
            sb.append(poly.get(i).coef);
            if (poly.get(i).exp > 0) {
                sb.append("x^").append(poly.get(i).exp);
            }
            if (i < poly.size() - 1 && poly.get(i+1).coef >= 0) {
                sb.append(" + ");
            }
        }
        if (sb.length() == 0) {
            return "0";
        }
        return sb.toString();
    }
}
```

This code defines a `Term` class to represent a term in the polynomial and uses `LinkedList<Term>` to represent the polynomials. The main function reads the input and calls the static methods `add`, `subtract`, and `multiply` to perform the desired operations. The results are displayed using a helper method `displayPoly`.

