Yes, you can use Node.js backend code and MongoDB to handle user registration and authentication for your front-end application. Here's an example of how you could set this up:

1. Install the required dependencies:
```
npm install express body-parser cors bcrypt jsonwebtoken mongoose
```

2. Create a `User` model with `mongoose` that will represent a user in your database and will contain the user's email and password (hashed).
```javascript
// models/User.js

const mongoose = require('mongoose');
const Schema = mongoose.Schema;
const bcrypt = require('bcrypt');

const UserSchema = new Schema({
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
});

UserSchema.pre('save', function(next) {
  const user = this;
  if (!user.isModified('password')) {
    return next();
  }
  bcrypt.genSalt(10, (err, salt) => {
    if (err) {
      return next(err);
    }
    bcrypt.hash(user.password, salt, (err, hash) => {
      if (err) {
        return next(err);
      }
      user.password = hash;
      next();
    });
  });
});

UserSchema.methods.comparePassword = function(candidatePassword, callback) {
  bcrypt.compare(candidatePassword, this.password, (err, isMatch) => {
    if (err) {
      return callback(err);
    }
    callback(null, isMatch);
  });
};

module.exports = mongoose.model('User', UserSchema);
```

3. Create an Express server with routes for handling user registration and authentication.
```javascript
// server.js

const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const mongoose = require('mongoose');
const User = require('./models/User');

const app = express();
app.use(cors());
app.use(bodyParser.json());

mongoose.connect('mongodb://localhost/myapp', {
  useCreateIndex: true,
  useNewUrlParser: true,
  useUnifiedTopology: true,
});
mongoose.connection.on('error', err => {
  console.error(`Mongoose connection error: ${err}`);
  process.exit(1);
});

const JWT_SECRET = 'mysecretkey';

function verifyToken(req, res, next) {
  const Authorization = req.headers['authorization'];
  if (!Authorization) {
    return res.status(401).send('Unauthorized');
  }
  const token = Authorization.replace('Bearer ', '');
  jwt.verify(token, JWT_SECRET, (err, payload) => {
    if (err) {
      return res.status(401).send('Unauthorized');
    }
    req.user = payload;
    next();
  });
}

app.post('/api/register', async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await User.create({ email, password });
    res.status(201).send(user.toJSON());
  } catch (err) {
    console.error(err);
    res.status(400).send(err.message);
  }
});

app.post('/api/authenticate', async (req, res) => {
  const { email, password } = req.body;
  const user = await User.findOne({ email });
  if (!user) {
    return res.status(404).send('User not found');
  }
  user.comparePassword(password, async (err, isMatch) => {
    if (err) {
      console.error(err);
      return res.status(400).send(err);
